(window.GIM_TS=window.GIM_TS||{})["Chullin.5"]={"from":120,"a":[["\u0003היה בקי בהן\u0004 בעופות הטמאים \u0003ובשמותיהן,\u0004 שיודע מה שמו של כל אחד מהם, הרי \u0003עוף\u0004 אחר \u0003הבא\u0004 לפניו \u0003בסימן אחד\u0004 בלבד של טהרה — \u0003טהור,\u0004 שהרי אין עוף טמא שיש בו סימן אחד של טהרה אלא פרס ועזניה, והרי הוא בקי ויודע שלא מדובר בהם. \u0003לא היה בקי בהן ובשמותיהן,\u0004 אם בא לפניו עוף שיש לו רק \u0003סימן אחד\u0004 של טהרה — \u0003טמא,\u0004 שמא הוא פרס או עזניה. אם בא לפניו עוף שיש לו \u0003שני סימנין\u0004 של טהרה — \u0003טהור, והוא\u0004 (וזהו דווקא) כ\u0003שיכיר\u0004 \u0003עורב,\u0004 וידע שהעוף שלפניו אינו עורב, שהרי אין עוף טמא שיש לו שני סימנים אלא עורב.","ושואלים: שיכיר \u0003עורב ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 מה שנאמר ברשימת העופות הטמאים: \"את כל עורב למינו\" (ויקרא יא, טו), \u0003\"עורב\"\u0004 — \u0003זה עורב\u0004 שאנו מכירים, \u0003\"למינו\"\u0004 מה בא לרבות? \u0003ר' אליעזר אומר: להביא\u0004 (לרבות) לאיסור \u0003את הזרזיר,\u0004 שהוא ממין העורב. \u0003אמרו לו לר' אליעזר: והלא אנשי כפר תמרתא שביהודה היו אוכלים אותן\u0004 את הזרזירים, \u0003מפני שיש להן זפק! אמר להם: אף הן עתידין ליתן את הדין\u0004 על שאוכלים דברים אסורים.","\u0003דבר אחר:\u0004 מה שנאמר בעורב \u0003\"למינהו\"\u0004 — הרי זה \u0003להביא סנונית לבנה,\u0004 שגם היא אסורה, אלו \u0003דברי ר' אליעזר. אמרו לו: והלא אנשי גליל העליון אוכלים אותו, מפני שקרקבנו נקלף! אמר להם: אף הן עתידין ליתן את הדין.\u0004 על כל פנים, מוסכם כי יש עופות טמאים נוספים שיש להם שני סימני טהרה כמו עורב, שהרי נאמר בו \"למינו\"! \u0003אלא\u0004 צריך לומר, שמה שאמר רב נחמן שעוף הבא לפנינו בשני סימני טהרה טהור, והוא שיכיר עורב, כוונתו — והוא שיכיר \u0003עורב וכל מין עורב.\u0004","\u0003אמר אמימר, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003עוף\u0004 שאינו ידוע כמין טמא \u0003הבא\u0004 לפנינו \u0003בסימן\u0004 טהרה \u0003אחד\u0004 — \u0003טהור, והוא\u0004 שידע שהעוף הזה \u0003לא דריס\u0004 \u0005[אינו דורס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב נחמן\u0004 לעיל, שעוף הבא לפנינו בסימן אחד של טהרה אינו מותר, עד שיהיה בקי בהם ובשמותיהם, וידע שאין זה אחד מהם, \u0003מאי\u0004 \u0005[מהו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע לי\u0004 \u0005[לא שמעתי],\u0006 \u0003כלומר,\u0004 בלשון נקיה: \u0003לא סבירא לי\u0004 \u0005[איני סבור כן].\u0006 שכן, \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 לחשוש, \u0003משום פרס ועזניה,\u0004 שיש בהם סימן אחד של טהרה? שני אלו הם \u0003ליתנהו\u0004 \u0005[אינם מצויים]\u0006 \u0003בישוב,\u0004 ואין לחשוש להם.","\u0003אמר רב יהודה:\u0004 עוף הידוע בכינוי \u0003עוף המסרט\u0004 — \u0003כשר לטהרת מצורע,\u0004 כלומר, עוף טהור הוא, שנאמר שם: \"ולקח למיטהר שתי צפרים חיות טהורות\" (ויקרא יד, ד). \u0003וזו היא סנונית לבנה שנחלקו בה ר' אליעזר וחכמים\u0004 בברייתא שהובאה קודם, האם היא טהורה.","\u0003אמר אמימר:\u0004 שני מינים מוכרים לנו בשם סנונית לבנה, זו שכריסה לבנה וזו שכריסה ירוקה (צהובה); \u0003בחיורא כרסה\u0004 \u0005[בכריסה לבנה]\u0006 — \u0003כולי עלמא לא פליגי דשריא\u0004 \u0005[הכל אינם חלוקים שהיא מותרת],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בדירוקא כרסה\u0004 \u0005[בשכריסה ירוקה],\u0006 \u0003ר' אליעזר אסר\u0004 \u0005[אוסר],\u0006 \u0003ורבנן שרו\u0004 \u0005[וחכמים מתירים],\u0006 \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כר' אליעזר.\u0004","\u0003מר זוטרא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את דברי אמימר: \u0003בדירוקא כרסה\u0004 \u0005[בשכריסה ירוקה]\u0006 \u0003כולי עלמא לא פליגי דאסיר\u0004 \u0005[הכל אינם חלוקים שאסור],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בדחיורא כרסה\u0004 \u0005[בשכריסה לבנה],\u0006 \u0003ר' אליעזר אסר\u0004 \u0005[אוסר],\u0006 \u0003ורבנן שרו\u0004 \u0005[וחכמים מתירים],\u0006 \u0003והלכתא כרבנן דשרו\u0004 \u0005[והלכה כחכמים שמתירים].\u0006","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח למי שאומר]\u0006 \u0003בחיורא כרסה פליגי\u0004 \u0005[בכריסה לבנה הם חלוקים]\u0006 — \u0003היינו דקתני\u0004 \u0005[זה שהוא שונה]\u0006 בברייתא לעיל: \"למינו\" — \u0003זו היא סנונית לבנה, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003בדירוקא פליגי\u0004 \u0005[בשל ירוקה\u0006 כרסה \u0005הם חלוקים],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הלשון \u0003\"זו היא סנונית לבנה\"?\u0004 והלוא כרסה ירוקה! ומשיבים: מה שנאמר \"סנונית לבנה\" הריהו \u0003לאפוקי דבתי דאוכמתי\u0004 \u0005[להוציא את סנונית הבתים, שהיא שחורה לגמרי].\u0006","\u0003אמר רחבה, אמר ר' יהודה: תסיל,\u0004 שהוא עוף הדומה ליונה ותור — \u0003פסול\u0004 להקרבה בקטנותו \u0003משום תורין,\u0004 שהם כשרים רק כשהם בוגרים, \u0003וכשר\u0004 בקטנותו, \u0003משום בני יונה,\u0004 שהם כשרים דווקא בקטנותם. כלומר, הוא נחשב למין של יונה. ואילו העוף הקרוי \u0003דאציפי,\u0004 \u0003ו\u0004כן \u0003תורין של רחבה\u0004 — \u0003כשרין\u0004 רק בבגרותם \u0003משום תורין, ופסולין משום בני יונה,\u0004 מפני שהם מין תור. \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב דניאל בר רב קטינא\u0004 על כך ממה ששנינו במסכת פרה: \u0003כל העופות\u0004"],["\u0003פוסלין מי חטאת\u0004 (מים שנותנים לתוכם אפר פרה אדומה) כששתו מהם, מפני שלאחר שהם שותים — מקצת מן המים שבפיהם (שנפסלו) — נופלים בחזרה לכלי. ודבר זה הוא בכל העופות \u0003חוץ מן היונה, מפני שמוצצת\u0004 את המים, ואין המים חוזרים מפיה לכלי. \u0003ואם איתא\u0004 \u0005[אכן]\u0006 תסיל הוא מין יונה — גם הוא מוצץ, ואם כן \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003חוץ מיונה ותסיל!\u0004 \u0003אמר ר' זירא:\u0004 אף על פי שהוא ממינה, וגם הוא מוצץ, מכל מקום לענין מי חטאת יש הבדל ביניהם, \u0003זה\u0004 התסיל — \u0003מוצץ ומקיא\u0004 חלק מן המים בחזרה, ולכן הוא פוסל, \u0003וזה\u0004 היונה — \u0003מוצץ ואינו מקיא.\u0004","\u0003אמר רב יהודה: הני כופשני צוצייני\u0004 \u0005[אותם\u0006 תורים הקרויים \u0005תורים צוציינים]\u0006 \u0003כשרים\u0004 להקרבה \u0003לגבי מזבח, והן הן\u0004 \u0003תורין של רחבה,\u0004 שנאמר בעמוד הקודם שהם כשרים משום תורים. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו: \u0003אזוב\u0004 שהצריכה התורה בעניינים שונים, וכגון לטהרת המצורע, הוא אזוב סתם, \u0003ולא\u0004 זה הקרוי \u0003אזוב יון, ולא אזוב כוחלי, ולא אזוב רומי, ולא\u0004 אזוב \u0003מדברי, ולא כל אזוב שיש לו שם לווי.\u0004 ולפי זה נמצא שגם לענין תורים, רק תורים סתם כשרים להקרבה, ולא תורים צוציינים שיש להם שם לווי!","\u0003אמר אביי: כל שנשתנה שמו קודם מתן תורה,\u0004 שהיו בו כמה מינים בעלי שם לווי קודם מתן תורה, \u0003והקפידה תורה עליו,\u0004 ולא הזכירה אותו בשם לווי, וכגון אזוב, אם \u0003יש לו שם לווי\u0004 — הריהו \u0003פסול.\u0004 \u0003והני\u0004 \u0005[ואלה]\u0006 התורים הצוציינים — \u0003לא נשתנו שמן,\u0004 לא היו מכונים \"תורים צוציינים\" \u0003קודם מתן תורה,\u0004 אלא תורים סתם. ולכן, למרות שעכשיו יש להם שם לווי — כשרים הם. \u0003רבא אמר\u0004 תירוץ אחר: \u0003הני כופשני צוצייני\u0004 \u0005[אלה התורים הצוציינים],\u0006 \u0003באתרייהו\u0004 \u0003סתמא קרי להו\u0004 \u0005[במקומם,\u0006 תורים \u0005סתם קוראים להם].\u0006","ובענין דומה \u0003אמר רב יהודה: הני כרזי דבי חילפי שרו\u0004 \u0005[אותם\u0006 מיני \u0005חגבים שמצויים בין שיחי הבר מותרים],\u0006 שממיני החגבים הטהורים הם, \u0003ודבי כרבי אסירי\u0004 \u0005[ושבין הכרובים אסורים].\u0006 \u0003אמר רבינא: ומלקינן עלייהו\u0004 \u0005[ומלקים עליהם]\u0006 את מי שאוכל אותם \u0003משום שרץ העוף\u0004 (\"וכל שרץ העוף טמא הוא לכם לא יאכלו\". דברים יד, יט). \u0003ואמר רב יהודה:\u0004 העוף הקרוי \u0003צרדא\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 והקרוי \u0003ברדא\u0004 — \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003וסימניך\u0004 כדי לזכור את האסור: הביטוי \u0003\"בר מיניה\"\u0004 \u0005[חוץ ממנו],\u0006 שמשמעו איסור, שיש לו דמיון למלה \"ברדא\". \u0005העוף הקרוי\u0006 \u0003מרדא\u0004 — \u0003ספקא\u0004 \u0005[ספק]\u0006 אם הוא כשר או לא.","\u0003אמר רב אסי, שמונה\u0004 עופות \u0003ספיקות הן: חובא, חוגא, סוגא והרנוגא, תושלמי, ומרדא, כוחילנא, ובר נפחא.\u0004 ומסבירים: \u0003מאי ספיקייהו\u0004 \u0005[מה ספיקם]?\u0006 \u0003עופות טהורים קורקבנן\u0004 (העור הפנימי של הקורקבן) \u0003נקלף,\u0004 כפי ששנינו במשנתנו, \u0003וטמאין\u0004 — \u0003אין קורקבנן נקלף; והני\u0004 \u0005[ו\u0006שמונה \u0005אלה]\u0006 \u0003קורקבנן נקלף,\u0004 אבל לא ביד, \u0003אלא\u0004 \u0003בסכינא\u0004 \u0005[בסכין].\u0006 ושואלים: ומדוע אינו כשר?","\u0003והא ההיא בר אווזא דהוה בי\u0004 \u0005[והרי אותו ברווז שהיה בביתו של]\u0006 \u0003מר שמואל, דלא הוה קא מקלף קורקבניה\u0004 \u0005[שלא היה נקלף קורקבנו],\u0006 \u0003ואותביה בשימשא\u0004 \u0005[והניח אותו בשמש],\u0006 \u0003וכיון דרפי איקליף\u0004 \u0005[וכיון שהתרפה\u0006 קצת \u0005נקלף]!\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כי רפי איקליף בידא\u0004 \u0005[כאשר התרפה נקלף ביד],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בשמונה ספקות אלה, \u0003אף על גב דרפי לא מקליף אלא בסכינא\u0004 \u0005[אף על פי שמתרפה אינו נקלף אלא בסכין].\u0006","\u0003אמר אביי: תרנגולא דאגמא\u0004 \u0005[תרנגול האגם,\u0006 הביצה\u0005]\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 \u0003משמונה ספיקות הוא, והיינו\u0004 \u0005[והוא]\u0006 העוף הקרוי \u0003מרדו\u0004 (מרדא). ובענין זה \u0003אמר רב פפא: תרנגולא דאגמא אסירא\u0004 \u0005[תרנגול האגם אסור],\u0006 אבל \u0003תרנגולתא דאגמא שריא\u0004 \u0005[תרנגולת האגם מותרת],\u0006 \u0003וסימניך\u0004 לזכור איזה מהם מותר ואיזה איסור, מה שדרשו חכמים בכתוב \"לא יבוא עמוני בקהל ה'\" (דברים כג, ד) — \u0003עמוני ולא עמונית,\u0004 שהזכר אסור והנקבה מותרת. \u0003דרש מרימר\u0004 בציבור: \u0003תרנגולתא דאגמא אסירא\u0004 \u0005[תרנגולת האגם\u0006 גם היא \u0005אסורה],\u0006 שהרי \u0003חזיוה דדרסה ואכלה\u0004 \u0005[ראו אותה\u0006 חכמים \u0005ש\u0006היא \u0005דורסת ואוכלת],\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 העוף הנקרא \u0003גירותא,\u0004 שידוע היה שהוא אסור (להלן קט,ב).","\u0003אמר רב:\u0004 העוף המכונה \u0003שבור אנדרפטא\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 והמכונה \u0003פירוז אנדרפטא\u0004 — \u0003אסור, וסימניך\u0004 לזכור איזה מהם אסור — \u0003פירוז רשיעא\u0004 \u0005[הרשע],\u0006 שהיה רשע ידוע בשם זה. \u0003אמר רב הונא:\u0004 העוף הנקרא \u0003בוניא\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 הקרוי \u0003פרוא\u0004 — \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003וסימניך\u0004 לזכור איזה מהם אסור — \u0003פרואה אמגושא\u0004 \u0005[המכשף]\u0006 הידוע.","\u0003אמר רב פפא:\u0004 העוף הקרוי \u0003\"מרדו זגיד ואכיל\"\u0004 \u0005[מרדו המסב ואוכל]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 זה שנקרא \"מרדו \u0003סגיד ואכיל\"\u0004 \u0005[המשתחוה ואוכל]\u0006 — \u0003אסור, וסימניך\u0004 — \u0003\"לא תשתחוה לאל אחר\"\u0004 (שמות לד, יח), שהמשתחווה אסור. \u0003אמר שמואל:\u0004 הצפור הנקראת \u0003שתיא חמרא\u0004 \u0005[שתיינית יין]\u0006 — \u0003אסירא\u0004 \u0005[אסור],\u0006 \u0003וסימניך\u0004 — מה ששנינו שכהנים \u0003שתויי יין פסולין לעבודה. ואמר שמואל:\u0004 הצפור הנקראת \u0003מזגא חמרא\u0004 \u0005[מוזגת היין]\u0006 — \u0003אסירא\u0004 \u0005[אסור],\u0006"],["העוף הנקרא \u0003בת מזגא חמרא\u0004 \u0005[בת מוזגת היין]\u0006 — \u0003שריא\u0004 \u0005[מותר],\u0006 \u0003וסימניך\u0004 לזכור — מה שאמרו חכמים בענין אחר: \u0003\"יפה כח הבן מכח האב\",\u0004 שמוזגת היין אסורה, ובת מוזגת היין מותרת.","\u0003אמר רב יהודה:\u0004 העוף הקרוי \u0003שקיטנא\u0004 \u0005[שקיטן]\u0006 יש בו כמה מינים, \u0003אריכי שקי\u0004 \u0005[\u0006בעלי \u0005שוקיים ארוכים]\u0006 \u0003וסומקי\u0004 \u0005[ואדומים,\u0006 שגופם אדום\u0005]\u0006 — \u0003שריא\u0004 \u0005[מותר],\u0006 \u0003וסימניך\u0004 לזה הוא עוף בשם \u0003מורזמא,\u0004 שכך היה נראה, וידוע היה שהוא טהור. \u0003גוצי וסומקי\u0004 \u0005[קטנים ואדומים]\u0006 — \u0003אסירי\u0004 \u0005[אסורים],\u0006 \u0003וסימניך\u0004 מה ששנו חכמים: כהן \u0003ננוס\u0004 (ננס) \u0003פסול\u0004 לעבודה במקדש. \u0003אריכי שקי וירוקי\u0004 \u0005[ארוכי שוקיים, וירוקים,\u0006 צהובים\u0005] —\u0006 \u0003אסירי\u0004 \u0005[אסורים],\u0006 \u0003וסימניך\u0004 מה ששנינו בהלכות טריפות: בני מעיים \u0003ירוקין פסולין.\u0004","\u0003אמר רב יהודה: שלך\u0004 שנזכר בין העופות הטמאים (ויקרא יא, יז) — \u0003זה\u0004 העוף \u0003השולה דגים מן הים, דוכיפת\u0004 (שם יט) נקרא כך על שם \u0003שהודו כפות,\u0004 שיש לו כרבולת עבה, הנראית כפופה וקשורה. ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003דוכיפת\u0004 — הוא העוף \u0003שהודו כפות, וזהו\u0004 העוף \u0003ש\u0004כמסופר במקום אחר (גיטין סח,ב) \u0003הביא שמיר לבית המקדש\u0004 בימי שלמה, כדי לבקע באמצעותו את האבנים לבנין המקדש, שנאמר בו: \"כל כלי ברזל לא נשמע בבית בהיבנותו\" (מלכים א ו, ז).","מסופר: \u0003ר' יוחנן, כי הוה חזי\u0004 \u0005[כאשר היה רואה]\u0006 \u0003שלך, אמר\u0004 \u0005[\u0006היה \u0005אומר]:\u0006 \u0003\"משפטיך תהום רבה\"\u0004 (תהלים לו, ז). \u0003כי הוה חזי\u0004 \u0005[כאשר היה רואה]\u0006 \u0003נמלה, אמר\u0004 \u0005[\u0006היה \u0005אומר]:\u0006 \u0003\"צדקתך כהררי אל\"\u0004 (שם).","\u0003אמר אמימר:\u0004 העופות הקרויים \u0003לקני ובטני שריין\u0004 \u0005[מותרים].\u0006 אלו הקרויים \u0003שקנאי ובטנאי, מקום שנהגו לאכול\u0004 אותם — \u0003אוכלין, מקום שנהגו שלא לאכול\u0004 — \u0003אין אוכלין.\u0004 ותוהים: \u0003אטו במנהגא תליא מילתא\u0004 \u0005[וכי במנהג תלוי הדבר]\u0006 האם הוא מותר או אסור? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסור — הרי זה \u0003באתרא דשכיחי\u0004 \u0005[במקום שמצויים]\u0006 \u0003פרס ועזניה,\u0004 שיש להם דמיון לעופות אלה, ואנשים עלולים להחליף ביניהם. \u0003הא\u0004 \u0005[זה]\u0006 שמותר — \u0003באתרא דלא שכיחי\u0004 \u0005[במקום שאין מצויים]\u0006 \u0003פרס ועזניה,\u0004 והחשש אינו קיים.","\u0003אמר אביי:\u0004 העופות הקרויים \u0003קואי וקקואי אסירי\u0004 \u0005[אסורים],\u0006 \u0003קקואתא שריא\u0004 \u0005[מותרת].\u0006 ואילו \u0003במערבא מלקו עילוה\u0004 \u0005[בארץ ישראל היו מלקים עליה]\u0006 את מי שאוכל אותה, \u0003וקרו\u0004 \u0005[וקוראים]\u0006 \u0003לה תחוותא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"תנשמת\"\u0004 שנזכרת בין העופות הטמאים (ויקרא יא, יח) היא \u0003באות שבעופות.\u0004 ויש לשאול: \u0003אתה אומר באות שבעופות, או אינו אלא באות שבשרצים?\u0004 שהרי גם בין השרצים הטמאים נזכרה תנשמת (שם ל)! \u0003אמרת: צא ולמד משלש עשרה מדות שהתורה נדרשת בהן,\u0004 שאחת מהן היא: \u0003דבר הלמד מענינו,\u0004 שיש לפרש את הכתוב לפי הענין שבו הוא נזכר. והרי \u0003במה הכתוב\u0004 באותם פסוקים \u0003מדבר? בעופות, אף\u0004 תנשמת שנזכרת \u0003כאן\u0004 היא \u0003בעופות.\u0004","ומעירים: \u0003תניא נמי\u0004 \u0005[שנויה גם כן\u0006 ברייתא\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 פרשת ה\u0003שרצים כהאי גוונא\u0004 \u0005[כגון זה]:\u0006 \u0003תנשמת\u0004 האמורה שם היא \u0003באות שבשרצים. אתה אומר באות שבשרצים, או אינו אלא באות שבעופות? אמרת: צא ולמד משלש עשרה מדות שהתורה נדרשת בהן\u0004 במידת \u0003דבר הלמד מענינו, במה הכתוב מדבר? בשרצים, אף\u0004 התנשמת הנזכרת \u0003כאן\u0004 היא \u0003בשרצים.\u0004","\u0003אמר אביי: באות שבעופות\u0004 הוא הקרוי \u0003קיפוף, באות שבשרצים\u0004 הוא הקרוי \u0003קורפדאי. אמר רב יהודה: קאת\u0004 הנזכרת בין העופות הטמאים (שם יח) — \u0003זו הקוק, רחם\u0004 — \u0003זו\u0004 הקרוי \u0003שרקרק.\u0004","וביחס לרחם הנזכר באותו פסוק, \u0003אמר ר' יוחנן: למה נקרא שמו רחם? כיון שבא רחם\u0004 לארץ \u0003באו רחמים לעולם,\u0004 שהוא בא סמוך לעונת הגשמים, שהם רחמים לעולם. \u0003אמר רב ביבי בר אביי: והוא\u0004 סימן לגשמים רק בשעה \u0003דיתיב אמידי ועביד\u0004 \u0005[שיושב על דבר מה ועושה\u0006 קול\u0005]\u0006 \u0003\"שרקרק\",\u0004 ולא כשהוא מעופף. \u0003וגמירי דאי יתיב אארעא ושריק\u0004 \u0005[ולמודים אנו\u0006 במסורת \u0005שאם הוא יושב על הארץ,\u0006 שלא כדרכו \u0005ושורק]\u0006 — סימן הוא ש\u0003אתא משיחא\u0004 \u0005[בא המשיח],\u0006 \u0003שנאמר \"אשרקה להם ואקבצם\"\u0004 (זכריה י, ח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר שימי למר בר רב אידאי: והא ההוא דיתיב בי כרבא ושרק\u0004 \u0005[והרי מעשה באותו\u0006 רחם \u0005שישב בשדה חרוש ושרק],\u0006 \u0003ואתא גלל אפסקיה למוחיה\u0004 \u0005[ובאה אבן ושברה את מוחו,\u0006 גולגלתו\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא ביידא הוה\u0004 \u0005[אותו\u0006 רחם \u0005שקרן היה],\u0006 ולכן אירע לו כן.","ועל הכתוב \"את כל עורב למינו\" (ויקרא יא, טו) \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"עורב\"\u0004 — \u0003זה עורב, \"את כל העורב\"\u0004 — \u0003להביא עורב העמקי, \"למינו\"\u0004 — \u0003להביא עורב הבא בראשי יונים.\u0004 ומבארים את הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עורב\u0004 — \u0003זה עורב.\u0004 ושואלים: \u0003אטו קמן קאי\u0004 \u0005[וכי לפנינו הוא עומד]\u0006 כשאנו שונים ברייתא זו, שאפשר להראות עליו באצבע ולומר: זה עורב? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003\"עורב\"\u0004 — \u0003זה עורב אוכמא\u0004 \u0005[שחור],\u0006 \u0003וכן הוא אומר \"קווצותיו תלתלים שחורות כעורב\"\u0004 (שיר השירים ה, יא). ומה ששנינו עורב \u0003העמקי\u0004 עניינו — עורב \u0003חיוורא\u0004 \u0005[לבן].\u0006 \u0003וכן הוא אומר:\u0004 \"ו הנה \u0003מראהו עמוק מן העור\"\u0004 (ויקרא יג, ל), והסבירו חכמים — \u0003כמראה חמה העמוקה מן הצל,\u0004 שהמקום המואר והבהיר נראה נמוך ועמוק יותר מן הצל המוטל עליו.","ובביאור מה ששנינו: \u0003ועורב הבא בראשי יונים, אמר רב פפא: לא תימא דאתי בריש יוני\u0004 \u0005[אל תאמר\u0006 שהכוונה היא \u0005שהוא בא בראש היונים],\u0006 לפניהם, ששוכן עמם. \u0003אלא, דדמי רישיה לדיונה\u0004 \u0005[שדומה ראשו ל\u0006ראש \u0005של יונה].\u0006","ועל הכתוב \"ואת הנץ למינהו\" (ויקרא יא, טז) \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"הנץ\"\u0004 — \u0003זה הנץ\u0004 עצמו, \u0003\"למינהו\"\u0004 — \u0003להביא את\u0004 העוף הקרוי \u0003בר חיריא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003בר חיריא? אמר אביי:\u0004 הוא העוף שנקרא \u0003שורינקא.\u0004","ועל הכתוב ברשימת העופות הטמאים \"ואת החסידה האנפה למינה\" (שם יט) \u0003אמר רב יהודה: \"החסידה\"\u0004 — \u0003זו דיה לבנה.\u0004 ו\u0003למה נקרא שמה חסידה? שעושה חסידות עם חברותיה,\u0004 שעוזרת להם ממזונותיה. \u0003\"האנפה\"\u0004 — \u0003זו דיה רגזנית.\u0004 ו\u0003למה נקרא שמה אנפה? שמנאפת\u0004 (שכועסת ורבה) \u0003עם חברותיה.\u0004","\u0003אמר רב חנן בר רב חסדא אמר רב חסדא אמר רב חנן בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אמר רב: עשרים וארבעה עופות טמאין הן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן בר רב חסדא לרב חסדא\u0004 אביו: עופות טמאים \u0003דהיכא\u0004 \u0005[של היכן\u0006 בתורה\u0005]?\u0006 שהרי שתי רשימות של העופות הטמאים יש בתורה, \u0003אי\u0004 \u0005[אם]\u0006 אלה שב\u0003ויקרא\u0004 (פרק יא) — הלא רק \u0003עשרים הוו\u0004 \u0005[הם]!\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אלה שב\u0003משנה תורה\u0004 (דברים פרק יד) — הלא רק \u0003עשרים וחד הוו\u0004 \u0005[ואחד הם]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003דאה דכתיבא\u0004 \u0005[שכתובה]\u0006 \u0003בויקרא ולא כתיבא\u0004 \u0005[ואינה כתובה]\u0006 \u0003במשנה תורה, שדייה עלייהו\u0004 \u0005[הטל,\u0006 הוסף \u0005אותה עליהם]\u0006 על אלה שבמשנה תורה — \u0003אכתי עשרין ותרין הוו\u0004 \u0005[עדיין עשרים ושנים הם],\u0006 ולא יותר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003הכי אמר אבוה דאמך\u0004 \u0005[כך אמר אבי אמך],\u0006 הוא רב חנן בר רבא \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: \"למינה\" \"למינה\" \"למינו\" \"למינהו\"\u0004 שנזכרו בפרשת העופות הטמאים — \u0003הרי כאן ארבע\u0004 נוספים. ומקשים: \u0003אי הכי עשרין ושית הוו\u0004 \u0005[אם כך עשרים ושש הם]!\u0006 \u0003אמר אביי: דאה\u0004 שנזכרה בויקרא, \u0003וראה\u0004 שנזכרה במשנה תורה — \u0003אחת היא, דאי סלקא דעתך תרתי אינון\u0004 \u0005[שאם עולה על דעתך ששתים הן],\u0006 שני עופות שונים,"],["\u0003מכדי\u0004 \u0005[הואיל]\u0006 ואנו מניחים כי מה שנאמר ברשימת העופות הטמאים שב\u0003משנה תורה\u0004 (ספר דברים) \u0003לאוסופי הוא דאתא\u0004 \u0005[להוסיף\u0006 על זו שבויקרא \u0005הוא שבא],\u0006 \u0003מאי שנא הכא דכתיב\u0004 \u0005[מה שונה כאן,\u0006 בויקרא, \u0005שכתוב]\u0006 \u0003דאה\u0004 (ויקרא יא, יד) \u0003ומאי שנא הכא דכתיב\u0004 \u0005[ומה שונה כאן,\u0006 במשנה תורה, \u0005שכתוב]\u0006 \u0003ראה\u0004 (דברים יד, יג), \u0003ולא כתיב\u0004 \u0005[ולא כתוב]\u0006 \u0003דאה? אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מין ראה ודאה אחת היא.\u0004","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003עשרים וחמשה הוו\u0004 \u0005[הם],\u0006 ולא עשרים וארבעה כפי שאמר רב חסדא בשם רב! \u0003אמר אביי: כשם שראה ודאה אחת היא, כך איה ודיה\u0004 שנזכרה במשנה תורה בלבד — \u0003אחת היא. דאי סלקא דעתך תרתי אינון\u0004 \u0005[שאם עולה על דעתך ששתים הן],\u0006 \u0003מכדי\u0004 \u0005[הואיל]\u0006 ואנו מניחים כי מה שנאמר ב\u0003משנה תורה לאוסופי הוא דאתא\u0004 \u0005[להוסיף\u0006 על זו שבויקרא \u0005הוא שבא],\u0006 \u0003מאי שנא הכא דכתיב\u0004 \u0005[מה שונה כאן,\u0006 בויקרא, \u0005שכתוב]\u0006 \u0003\"למינה\"\u0004 על \u0003איה\u0004 (ויקרא יא, יד), שהכתוב בא לאסור עופות נוספים ממין האיה, \u0003ומאי שנא התם דכתיב\u0004 \u0005[ומה שונה שם,\u0006 במשנה תורה, \u0005שכתוב]\u0006 \u0003\"למינה\"\u0004 על \u0003דיה\u0004 (דברים יד, יג), לאן נעלם מין האיה? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003איה ודיה אחת היא.\u0004","ושואלים: \u0003וכי מאחר שאיה ודיה אחת היא, למה ליה למיכתב\u0004 \u0005[למה לו לכתוב]\u0006 גם \u0003איה ו\u0004גם \u0003דיה?\u0004 ומשיבים: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 איה ודיה עוף אחד הן, ואם כן לכאורה, \u0003אקרא אני\u0004 רק \u0003איה,\u0004 ודי לי בכך כדי לאוסרה, \u0003דיה למה נאמרה? כדי שלא תתן פתחון פה לבעל דין לחלוק, שלא תהא אתה קורא\u0004 אותה \u0003איה,\u0004 \u0003והוא,\u0004 אדם אחר, \u0003קורא\u0004 אותה \u0003דיה,\u0004 ורוצה להכשירה. וכן להיפך, אם היה כתוב רק דיה, שלא תהא \u0003אתה קורא\u0004 אותה \u0003דיה והוא קורא\u0004 אותה \u0003איה\u0004 ומכשירה — \u0003לכך כתב במשנה תורה: \"והראה ואת האיה והדיה למינה\"\u0004 (דברים יד, יג), לומר שכל הקרוי באחד משמות אלו — אסור. ונמצא שלשיטת רב חסדא בשם רב, שעשרים וארבעה עופות טמאים יש בתורה, דאה וראה אחת הן, וכן איה ודיה, ולא נוסף במשנה תורה עוף על אלו שבויקרא.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003למה\u0004 חזרו ו\u0003נשנו\u0004 בעלי החיים הטמאים במשנה תורה אחר שכבר הוזכרו בספר ויקרא? \u0003בבהמה\u0004 נשנו \u0003מפני השסועה\u0004 שנוספה שם (דברים יד, ז), ולא נזכרה בויקרא, \u0003ובעופות\u0004 — \u0003מפני הראה. מאי לאו\u0004 \u0005[האם לא],\u0006 \u0003מ\u0004מה ש\u0003בהמה\u0004 שנזכרת \u0003התם\u0004 \u0005[שם]\u0006 במשנה תורה — \u0003לאוסופי\u0004 \u0005[\u0006באה \u0005להוסיף]\u0006 עוד מין אחד, נלמד כי ב\u0003עופות נמי\u0004 \u0005[גם כן]\u0006 — \u0003לאוסופי\u0004 \u0005[להוסיף]\u0006 מין חדש באו? ודוחים: \u0003לא, התם לאוסופי\u0004 \u0005[שם,\u0006 בבהמה, באה כדי \u0005להוסיף],\u0006 \u0003הכא לפרושי\u0004 \u0005[כאן\u0006 בעופות, כדי \u0005לפרש].\u0006","\u0003ופליגא\u0004 \u0005[וחלוקה\u0006 דעה זו\u0005],\u0006 שדאה וראה אחת היא, ואיה ודיה אחת היא, על \u0003ר' אבהו,\u0004 ש\u0003אמר ר' אבהו: ראה זו איה, ולמה נקרא שמה ראה?\u0004 מפני \u0003שרואה ביותר, וכן הוא אומר \"נתיב לא ידעו עיט ולא שזפתו עין איה\"\u0004 (איוב כח, ז), שאפילו איה שראייתה טובה ביותר אינה מכירה אותו. וכן \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 הראה \u0003עומדת בבבל ורואה נבלה בארץ ישראל.\u0004 ודנים בדברי ר' אבהו.","\u0003מ\u0004כיון ש\u0003ראה היינו\u0004 \u0005[היא]\u0006 \u0003איה, מכלל\u0004 הדברים צריך אתה לומר ש\u0003דאה לאו היינו\u0004 \u0005[אין היא]\u0006 \u0003ראה,\u0004 כפי שהסברנו לדעת רב חסדא בשם רב. ואולם, \u0003מכדי\u0004 \u0005[הואיל]\u0006 ומה שנאמר ב\u0003משנה תורה לאוסופי הוא דאתא\u0004 \u0005[להוסיף הוא שבא],\u0006 \u0003מאי שנא הכא דכתיב\u0004 \u0005[מה שונה כאן,\u0006 בויקרא, \u0005שכתוב]\u0006 \u0003דאה, ומאי שנא התם דלא כתיב\u0004 \u0005[ומה שונה שם,\u0006 במשנה תורה, \u0005שלא כתוב]\u0006 \u0003דאה? אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שמדובר באותו עוף? ואם כן בהכרח צריך אתה לומר כי לדעת ר' אבהו \u0003דאה וראה ואיה\u0004 — \u0003אחת היא. ו\u0004עוד, \u0003מ\u0004כיון שלדברי ר' אבהו","\u0003ראה היינו\u0004 \u0005[היא]\u0006 \u0003איה, מכלל\u0004 הדברים צריך אתה לומר לכאורה, ש\u0003דיה לאו היינו\u0004 \u0005[אין היא]\u0006 \u0003איה.\u0004 ואולם, הואיל ומה שנאמר במשנה תורה בא להוסיף על הנאמר בויקרא, \u0003מאי שנא התם דכתיב\u0004 \u0005[מה שונה שם,\u0006 בויקרא, \u0005שכתוב]\u0006 \u0003\"למינהו\"\u0004 על \u0003איה, ומאי שנא הכא דלא כתיב\u0004 \u0005[ומה שונה כאן\u0006 במשנה תורה \u0005שלא כתוב]\u0006 \u0003\"למינהו\"\u0004 על \u0003איה, אלא\u0004 על \u0003דיה?\u0004 לאן נעלם מינה של האיה? \u0003אלא\u0004 בא הדבר ללמדנו שאיה ודיה אחת היא. ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לדעת ר' אבהו \u0003דאה וראה דיה ואיה\u0004 — \u0003אחת היא,\u0004 שכל אלה \u0003הם שמות שונים של מין עוף אחד. ונמצא שלשיטת ר' אבהו יש עשרים ושלושה עופות טמאים, ולא עשרים וארבעה כשיטת רב.\u0004","בענין מה שאמרה התורה \"האיה למינה\" (ויקרא יא, יד) \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר: מאה עופות טמאין יש במזרח, וכולן מין איה הן. תני\u0004 \u0005[שנה]\u0006 \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו: שבע מאות מיני דגים\u0004 טמאים \u0003הן, ושמונה מאות מיני חגבים\u0004 טמאים הם, \u0003ולעופות אין מספר.\u0004 ותמהים: \u0003עופות\u0004 טמאים, הלא \u0003עשרים וארבע הוו\u0004 \u0005[הם]\u0006 שהוזכרו בתורה! \u0003אלא: ולעופות טהורים אין מספר.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: גלוי וידוע לפני מי שאמר והיה העולם שבהמה טמאה מרובה\u0004 במיניה \u0003מן הטהורות, לפיכך מנה הכתוב בטהורה\u0004 את רשימת הבהמות הטהורות — לומר שכל השאר טמאות. ומן הצד השני, \u0003גלוי וידוע לפני מי שאמר והיה העולם שעופות טהורין מרובין על הטמאין, לפיכך מנה הכתוב בטמאין.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רבי בדבריו אלה? ומשיבים: \u0003כ\u0004דברי \u0003רב הונא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב הונא אמר רב משום\u0004 (בשם) \u0003ר' מאיר: לעולם ישנה אדם לתלמידו דרך קצרה,\u0004 את המועט ולא את המרובה, שמן התורה אנו למדים דבר זה.","\u0003אמר ר' יצחק: עוף טהור נאכל\u0004 (מותר באכילה) \u0003במסורת,\u0004 בלא לבדוק בסימנים שהוא טהור. וכן \u0003נאמן הצייד לומר: עוף זה טהור,\u0004 שכך \u0003מסר לי\u0004 אודותיו \u0003רבי. אמר ר' יוחנן: והוא ש\u0004רבו \u0003בקי בהן\u0004 מכיר את העופות הטמאים, \u0003ובשמותיהן.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 האם מדובר ב\u0003רבו\u0004 שהיה \u0003חכם\u0004 בתורה, \u0003או רבו\u0004 ה\u0003צייד,\u0004 שלימדו לצוד? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר, ש\u0003אמר ר' יוחנן: והוא שבקי בהן ובשמותיהן. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003רבו\u0004 ה\u0003צייד\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \u0003רבו\u0004 ה\u0003חכם, בשלמא שמייהו\u0004 \u0005[נניח שמותיהם]\u0006 — \u0003גמיר להו\u0004 \u0005[הוא למד אותם],\u0006 \u0003אלא אינהו\u0004 \u0005[אותם עצמם]\u0006 \u0003מי ידע להו\u0004 \u0005[האם הוא יודע אותם],\u0006 הרי אינו צייד! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]:\u0006 \u0003רבו\u0004 ה\u0003צייד.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לוקחין\u0004 (קונים) \u0003ביצים מן הגוים בכל מקום, ואין חוששין\u0004 בהם \u0003לא משום\u0004 ביצי \u0003נבלות,\u0004 שמא נמצאו בתוך מעיה של תרנגולת נבילה (שמתה שלא על ידי שחיטה כשרה) והן אסורות, \u0003ולא משום\u0004 ביצי \u0003טרפות\u0004 שהן אסורות, מפני שהן מיעוט, שאין חוששים לו.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 של \u0003עוף טמא נינהו\u0004 \u0005[הם]!\u0006 \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל:\u0004 מדובר כאן \u0003ב\u0004אופן ש\u0003אומר\u0004 הגוי שהן \u0003של עוף פלוני,\u0004 ואנו יודעים שהוא \u0003טהור.\u0004 ושואלים: אם אתה סומך עליו, מדוע צריך שיזכיר את שם העוף? \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 רק שהן \u0003של עוף טהור!\u0004 ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין צורך שיזכיר את שם העוף, הרי אם הוא רוצה לשקר \u0003אית ליה לאישתמוטי\u0004 \u0005[יש לו\u0006 אפשרות \u0005להשתמט]\u0006 ולומר: אף על פי שאין אתה מכיר שהוא מעוף טהור פלוני, הרי הוא מעוף טהור אחר. אבל כשהוא מזכיר את שם העוף — ניתן להשוות את הביצים שהוא מוכר לביצים של אותו עוף, ולגלות את התרמית ולכן הוא חושש לשקר. ושואלים: ומדוע להסתמך על הגוי?","\u0003ולבדוק\u0004 \u0005[ושיבדוק]\u0006 \u0003בסימנין, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כסימני ביצים\u0004 טהורות — \u0003כך סימני דגים!\u0004 ותחילה תוהים: \u0003סימני דגים סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הלא \u0003סנפיר וקשקשת אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 שהם סימני הדגים (ויקרא יא, ט)! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כך סימני\u0004"],["\u0003עוברי דגים,\u0004 ביצי הדגים הדבוקות יחד במעי הדג.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 \u0003גבי ביצים, אלו הן סימני ביצים: כל שכודרת ועגולגולת,\u0004 עשויה כעין כדור עגול, אבל אינה ממש ככדור, אלא \u0003ראשה אחר כד\u0004 (מעוגל) \u0003וראשה אחד חד\u0004 — היא \u0003טהורה. שני ראשיה כדין, או שני ראשיה חדין\u0004 — הרי הם \u0003טמאין.\u0004 היה \u0003ה\u0004\u0003חלבון\u0004 (החלק הלבן) \u0003מבחוץ וחלמון\u0004 (החלק הצהוב) שלה \u0003מבפנים\u0004 — זו היא \u0003טהורה. חלמון מבחוץ וחלבון מבפנים\u0004 — \u0003טמאה. חלמון וחלבון מעורבין זה בזה\u0004 — \u0003בידוע שהיא ביצת השרץ.\u0004 ואם כן ניתן לזהות אם מדובר בביצה טמאה, ואין צורך לסמוך על עדותו של הגוי!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה שהביצים \u0003חתוכות,\u0004 כך שלא ניתן לדעת את צורתן. ושואלים: \u0003וליבדוק\u0004 \u0005[ושיבדוק]\u0006 \u0003בחלמון וחלבון\u0004 שלהם, מה בפנים ומה בחוץ! ומשיבים: מדובר במקרה שהביצים \u0003טרופות בקערה,\u0004 ואי אפשר לדעת.","ושואלים: \u0003וכהאי גוונא מי זבנינן מינייהו\u0004 \u0005[וכגון זה,\u0006 שהן טרופות, \u0005האם אנו קונים מהם]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מוכרין ביצת\u0004 תרנגולת \u0003טרפה לגוי אלא אם כן\u0004 היא \u0003טרופה בקערה, לפיכך אין לוקחין\u0004 (קונים) \u0003מהם ביצים טרופות בקערה,\u0004 שמא ביצת טריפה היא שמכרה להם ישראל. ואם כן, בהכרח מדובר בביצים שאינן טרופות, שניתן לברר, לפי סימניהן, אם טהורות הן או טמאות!","\u0003אלא אמר ר' זירא:\u0004 טעם הדבר שלא ניתן לסמוך על כך, הוא משום ש\u0003סימנין\u0004 אלו בביצים \u0003לאו דאורייתא\u0004 \u0005[אינם מן התורה],\u0006 ולכן אי אפשר לסמוך עליהם באיסור של תורה. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 אלא ניתן לסמוך על הסימנים, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב אסי\u0004 בענין עופות טמאים: \u0003שמנה\u0004 עופות \u0003ספיקות הן\u0004 האם טמאים הם או טהורים — \u0003ליבדוק בביצים דידהו\u0004 \u0005[שנבדוק את הביצים שלהם],\u0006 ונראה לפי הסימנים האמורים בברייתא, אם הם טהורים או לא! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003סימנין לאו דאורייתא\u0004 \u0005[אינם מן התורה].\u0006","ושואלים: \u0003אלא\u0004 אם לא ניתן לסמוך על הסימנים, \u0003למאי הלכתא קתני לה\u0004 \u0005[לאיזו הלכה שנה אותה]\u0006 את הברייתא הזו של סימני הביצים? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אם \u0003שני ראשיה כדין, או שני ראשיה חדין, או חלמון מבחוץ וחלבון מבפנים\u0004 — \u0003ודאי טמאה\u0004 היא. אבל \u0003אם\u0004 \u0003רישיה חד\u0004 \u0005[ראשה האחד]\u0006 \u0003חד, ורישיה חד\u0004 \u0005[וראשה\u0006 השני\u0005]\u0006 \u0003כד\u0004 \u0005[רחב],\u0006 \u0003וחלבון מבחוץ וחלמון מבפנים, ואמר לך\u0004 גוי: \u0003של עוף פלוני\u0004 הן, \u0003וטהור הוא\u0004 — \u0003סמוך עליהם\u0004 על סימנים אלה. אבל \u0003בסתמא\u0004 \u0005[בסתם]\u0006 שלא אמר לך באיזה עוף מדובר, אלא באות לפניו ביצים עם סימנים אלה — \u0003לא תסמוך עליהם, דאיכא דעורבא דדמי לדיונה\u0004 \u0005[שיש\u0006 ביצים \u0005של עורב שדומים לשל יונה].\u0006","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003חלבון וחלמון מעורבין זה בזה\u0004 — \u0003בידוע שהיא ביצת השרץ,\u0004 ולא ביצת עוף טמא. ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר? והרי בין זו ובין זו אסורות הן! \u0003אמר רב עוקבא בר חמא: לומר שאם\u0004 ביצה כזו \u0003ריקמה\u0004 (נוצר השרץ בתוכה), \u0003וניקבה,\u0004 ונגע בה — \u0003טמאה,\u0004 אם גודלו של השרץ שבתוכה הוא \u0003בכעדשה,\u0004 שהוא השיעור שבו שרץ מת מטמא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: ודלמא\u0004 \u0005[ושמא]\u0006 ביצת \u0003נחש היא,\u0004 שהחלבון והחלמון מעורבים בה, ונחש אינו אחד מן השרצים המטמאים במותם! \u0003אלא אמר רבא,\u0004 מה שנאמר בברייתא: בידוע שהיא ביצת השרץ, אינו נוגע לדיני טומאה, אלא לומר \u0003שאם\u0004 ביצה כזו \u0003ריקמה\u0004 (נוצר השרץ בתוכה) \u0003ואכלה\u0004 — \u0003לוקה עליה משום \"שרץ השורץ על הארץ\"\u0004 (ויקרא יא, מא).","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעל איסור אכילה מדובר, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 בביצה של \u0003טמאה\u0004 של שרץ? \u0003אפילו\u0004 בביצה של \u0003טהורה נמי\u0004 \u0005[גם כן]\u0006 לוקה על אכילתה! \u0003דתניא\u0004 \u0005[ששנויה ברייתא]:\u0006 \u0003\"כל השרץ השורץ על הארץ\"\u0004 (שם) —"],["\u0003לרבות\u0004 לאיסור אכילה \u0003אפרוחים\u0004 של יונים ועוד \u0003שלא נפתחו עיניהם!\u0004 ומשיבים: איסור זה הוא \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וקרא\u0004 \u0005[והמקרא]\u0006 שהבאנו הוא \u0003אסמכתא בעלמא\u0004 \u0005[בלבד],\u0006 שחכמים הסמיכו עליו את איסורם. אבל האוכל ביצת שרץ שריקמה — לוקה עליה משום \"השרץ השורץ על הארץ\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גיעולי ביצים,\u0004 ביצים טהורות שהתבשלו עם הטמאות — \u0003מותרות. ביצים מוזרות\u0004 שלא הופרו במעי התרנגולת על ידי זכר, ואין אפרוח נוצר בהן — מותרות, למרות שהתרנגולת ישבה עליהן ימים רבים, ו\u0003נפש יפה\u0004 (אדם שאינו איסטניס) \u0003תאכלם.\u0004 \u0003נמצא עליה\u0004 על ביצה \u0003קורט\u0004 (מעט) \u0003דם\u0004 — \u0003זורק את הדם,\u0004 שהוא תחילת ריקום האפרוח, \u0003ואוכל את השאר.\u0004","\u0003אמר ר' ירמיה: והוא שנמצא\u0004 הדם \u0003על קשר שלה,\u0004 במקום בחלבון שבו מתחילה יצירת האפרוח, שדבר זה מוכיח שלא נתפשט הריקום לשאר הביצה. וכן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003דוסתאי אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב אפטוריקי\u0004 בברייתא: \u0003לא שנו\u0004 שזורק את הדם והשאר מותר, \u0003אלא שנמצא\u0004 הדם \u0003על חלבון שלה,\u0004 כלומר, במקום הקשר, \u0003אבל נמצא על חלמון שלה\u0004 — \u0003אפילו ביצה\u0004 עצמה (ולא רק הדם) \u0003אסורה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — מורה הדבר \u0003דשדא תכלא\u0004 \u0005[שנתפשט הקלקול]\u0006 \u0003בכולה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב גביהה מבי כתיל לרב אשי: איפכא תני תנא קמיה\u0004 \u0005[ההיפך שנה התנא לפני]\u0006 \u0003אביי:\u0004 לא שנו אלא שנמצא על חלמון שלה, אבל נמצא על חלבון שלה — אפילו ביצה אסורה. \u0003ואביי הוא דתרצה ניהליה הכי\u0004 \u0005[שתירץ,\u0006 יישב, \u0005אותה כך].\u0006","\u0003אמר חזקיה: מנין לביצת\u0004 עוף \u0003טמאה\u0004 (של עוף טמא) \u0003שהיא אסורה\u0004 באכילה \u0003מן התורה? שנאמר: \"ואת בת היענה\"\u0004 (ויקרא יא, טז), \u0003וכי בת יש לה ליענה? אלא איזו? זו ביצה טמאה,\u0004 שהיא נקראת בת היענה. ושואלים: \u0003ודלמא היינו שמייהו\u0004 \u0005[ושמא זהו שמם]\u0006 של עופות אלו, בת היענה! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[שהרי נאמר]:\u0006 \u0003\"בת עמי לאכזר כיענים במדבר\"\u0004 (איכה ד, ג), משמע ששמן הוא יענה.","ומוסיפים ושואלים: \u0003ולא\u0004 בת יענה שמם? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אעשה מספד כתנים ואבל כבנות יענה\"\u0004 (מיכה א, ח)! ומשיבים: הכוונה היא \u0003כיענה זו שמתאבלת על בניה,\u0004 כלומר: אעשה אבל כאבל היענה על בנות היענה. ושואלים עוד: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ושכנו שם בנות יענה\"\u0004 (ישעיה יג, כא), הרי שזהו שמם! ומתרצים, גם כאן הכוונה היא: ושכנו שם \u0003כיענה זו ששוכנת עם בניה.\u0004 ומוסיפים להקשות: כיצד ניתן לפרש ש\"בת היענה\" היא ביצת היענה?","\u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"תכבדני חית השדה תנים ובנות יענה\u0004 כי נתתי במדבר מים נהרות בישימון להשקות עמי\" (שם מג, כ), שבעלי החיים שוכני המדבר יהללו את הקדוש ברוך הוא על החסד שהוא עושה לעמו. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שבת היענה היא \u0003ביצה,\u0004 וכי \u0003ביצה בת מימר\u0004 \u0005[יכולה לומר]\u0006 \u0003שירה היא,\u0004 שתכבד את ה' בשירתה? \u0003אלא\u0004 צריך לומר כך: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב \u0003\"היענה\", וכתיב\u0004 \u0005[ונאמר]\u0006 גם \u0003\"בת היענה\",\u0004 ושניהם שמות אפשריים של עוף זה, ולכאורה אין מכאן ראיה.","\u0003ו\u0004אולם \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 הכתוב משנה כאן מהרגלו בשמות בעלי חיים, \u0003דפסק ספרא\u0004 \u0005[שפוסק הסופר]\u0006 את שם העוף \u0003לשתי תיבות,\u0004 \"בת היענה\", למרות שמדובר בעוף אחד, \u0003ומדפסיק להו ספרא\u0004 \u0005[ומכיון שפוסק אותם הסופר]\u0006"],["\u0003בתרתי\u0004 \u0005[בשתי]\u0006 \u0003תיבות\u0004 (מילים) — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003תרי\u0004 \u0005[שני]\u0006 \u0003שמות\u0004 נבדלים \u0003נינהו\u0004 \u0005[הם].\u0006","ושואלים: \u0003אלא מעתה \"את כדר לעומר\"\u0004 (בראשית יד, ד), \u0003דפסק להו ספרא בתרי\u0004 \u0005[שפוסק אותם הסופר לשנים],\u0006 \u0003הכי נמי דתרתי שמי נינהו\u0004 \u0005[כך גם כן\u0006 אתה אומר \u0005ששני שמות הם]?\u0006 והרי מדובר שם במלך אחד! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בשתי תיבות\u0004 \u0003פסיק להו\u0004 \u0005[מפסיק אותם],\u0006 \u0003בשני שיטין\u0004 (שורות) \u0003לא פסיק להו\u0004 \u0005[אינו מפסיק אותם],\u0006 אלא כותב אותם באותה שורה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בבת היענה — \u0003אפילו בשני שיטין נמי פסיק להו\u0004 \u0005[גם כן פוסק אותם],\u0006 שרשאי לכתוב \"בת\" בשורה אחת ו\"היענה\" בשורה הבאה, משמע שהם נבדלים לגמרי.","שנינו במשנה: \u0003אבל אמרו חכמים כל עוף\u0004 הדורס טמא. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן גמליאל אומר:\u0004 עוף ש\u0003דורס ואוכל\u0004 — \u0003בידוע שהוא טמא, יש לו אצבע יתירה וזפק וקרקבנו נקלף\u0004 — \u0003בידוע שהוא טהור. ר' אלעזר בר' צדוק אומר: מותחין לו חוט של משיחה,\u0004 והוא יושב עליו, ו\u0003אם חולק את רגליו, שתים\u0004 מן האצבעות \u0003לכאן\u0004 לפנים, \u0003ושתים לכאן\u0004 לאחור — \u0003טמא,\u0004 היו \u0003שלש לכאן ואחת לכאן\u0004 — \u0003טהור. ר' שמעון בן אלעזר אומר: כל עוף הקולט\u0004 מאכל \u0003מן האויר\u0004 — \u0003טמא.\u0004","על כך תוהים: העוף הקרוי \u0003ציפרתא נמי מקלט קלטה\u0004 \u0005[גם כן קולטת\u0006 מן האויר\u0005],\u0006 והיא טהורה! \u0003אמר אביי:\u0004 ש\u0003קולט ו\u0004גם \u0003אוכל\u0004 באויר \u0003קאמרי\u0004 \u0005[אומרים אנו],\u0006 \u0005ולא כזה שקולט באויר ואחר כך מניח לארץ ואוכל, כפי שעושה הציפרתא. ושבים לברייתא,\u0006","\u0003אחרים אומרים:\u0004 אם הוא \u0003שכן\u0004 (נמצא בשכנות) \u0003עם\u0004 עופות \u0003טמאים\u0004 — \u0003טמא,\u0004 שכן \u0003עם טהורים\u0004 — \u0003טהור.\u0004","ושואלים: \u0003כמאן\u0004 \u0005[כדעת מי]\u0006 היא דעת אחרים? האם \u0003כ\u0004דעת \u0003ר' אליעזר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: לא לחנם הלך זרזיר\u0004 ושכן \u0003אצל עורב,\u0004 כפי המוכר לנו, \u0003אלא מפני שהוא מינו?\u0004 ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים]\u0006 החלוקים על ר' אליעזר, וסבורים שהזרזיר עוף כשר, \u0003שכן ונדמה קאמרינן\u0004 \u0005[אומרים אנו],\u0006 כלומר, לא די שהוא שוכן עם עופות טמאים, \u0003אלא רק אם הוא גם דומה להם —\u0004 הרי זה סימן שגם הוא ממיניהם.","שנינו במשנה: \u0003ובחגבים, כל שיש לו\u0004 ארבע רגלים וארבע כנפיים וקרצולים (כרעי ניתור) וכנפיו חופים את רובו הריהו כשר. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003רובו? אמר רב יהודה אמר רב: רוב ארכו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003רוב הקיפו. אמר רב פפא: הלכך\u0004 \u0005[מכיון שכך]\u0006 שיש שתי לשונות — מחמירים אנו בשתיהן, ולכן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שכנפיו יהיו חופות \u0003רוב ארכו, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 גם שיהיו חופות את \u0003רוב הקיפו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לו\u0004 לחגב כנפיים \u0003עכשיו ועתיד לגדל לאחר זמן, כגון ה\u0004חגב הקרוי \u0003זחל\u0004 — הרי זה \u0003מותר. ר' אלעזר בר' יוסי אומר:\u0004 נאמר ביחס לחגב \"אך את זה תאכלו... \u0003אשר לא כרעים\u0004 ממעל לרגליו לנתר בהן על הארץ\" (ויקרא יא, כא), הקרי שלו הוא \"אשר לו כרעים\", והכתיב \"אשר לא\" — ללמד: \u0003אף על פי שאין לו\u0004 כרעים \u0003עכשיו ועתיד לגדל לאחר זמן\u0004 הריהו מותר באכילה. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003זחל? אמר אביי:\u0004 הוא מה שקורין בארמית \u0003אסקרין.\u0004","ובענין החגבים הטהורים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בפירוש הכתוב: \u0003\"את אלה מהם תאכלו את הארבה\u0004 למינו ואת הסלעם למינהו ואת החרגול למינהו ואת החגב למינהו\" (שם כב), \u0003ארבה\u0004 — \u0003זה\u0004 הקרוי \u0003גובאי, סלעם\u0004 — \u0003זה רשון, חרגול\u0004 — \u0003זה ניפול, חגב\u0004 — \u0003זה גדיאן. מה תלמוד לומר,\u0004 מה בא ללמד \u0003\"למינו\" \"למינהו\" \"למינהו\" \"למינהו\" ארבע פעמים,\u0004 לאחר כל אחד מהם? \u0003להביא\u0004 ארבעה מינים דומים לאלו: \u0003ציפורת כרמים, ויוחנא ירושלמית, והערצוביא, והרזבנית,\u0004 שגם הם מותרים באכילה.","\u0003דבי\u0004 \u0005[\u0006החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \"למינו\" \"למינהו\" \"למינהו\" \"למינהו\" \u0003אלו כללי כללות\u0004 (כללים), \u0003ו\u0004המינים שנזכרו במפורש \u0003אלו פרטי פרטות\u0004 (פרטים). וכך דורשים את הכתוב: \u0003בפסוק הקודם נאמר \"אך את זה תאכלו... אשר לו כרעים ממעל לרגליו לנתר בהן על הארץ\", ואנו דורשים את האמור בשני פסוקים אלה במידת כלל ופרט וכלל: \"אשר לו כרעים\" הוא כלל —\u0004 כל שיש לו כרעים לנתר בהן (קרצולים), \u0003\"ארבה\"\u0004 — \u0003זה\u0004 פרט הקרוי \u0003גובאי, \"למינו\"\u0004 — הרי זה כלל, ולפי כללי מדרש ההלכה, כאשר יש כלל ופרט וכלל — בא הכלל השני להוסיף כל דבר שהוא כעין הפרט, וכאן בא הכלל \"למינו\" \u0003להביא\u0004 (לרבות)"],["\u0003ציפורת כרמים,\u0004 שכמו הארבה גם לה אין גבחת, שאין ראשה חלק, אלא יש בו כמין שערות.","וממשיכה הברייתא: ויש לשאול, \u0003אין לי\u0004 להכשיר לפי זה \u0003אלא\u0004 מין חגב \u0003הבא\u0004 לפנינו \u0003ואין לו גבחת,\u0004 אבל \u0003הבא\u0004 לפנינו \u0003ויש לו גבחת מנין\u0004 שגם הוא כשר? \u0003תלמוד לומר: \"סלעם\"\u0004 (ויקרא יא, כב) — \u0003זה ניפול,\u0004 שיש לו גבחת. וממה שנאמר אחר כך \u0003\"למינהו\",\u0004 שהוא כלל, יש לדרוש גם כאן במידת כלל ופרט וכלל (אשר לו כרעים... סלעם... למינהו), לרבות מה שהוא כעין הפרט — \u0003להביא את האושכף,\u0004 שיש לו גבחת, שהוא כשר כמו הסלעם.","ויש לשאול: והרי יש צד משותף לאלו שאין להם זנב, \u0003ו\u0004אם כן \u0003אין לי\u0004 להתיר \u0003אלא\u0004 חגב \u0003הבא\u0004 לפנינו \u0003ואין לו גבחת\u0004 כמו ארבה, וכן \u0003חגב\u0004 \u0003הבא\u0004 לפנינו \u0003ויש לו גבחת,\u0004 כמו הסלעם, ואולם מדובר בחגב \u0003הבא\u0004 לפנינו \u0003ואין לו זנב;\u0004 אבל \u0003הבא ויש לו זנב, מנין\u0004 שהוא כשר? \u0003תלמוד לומר\u0004 מיד אחר כך: \u0003\"חרגול\"\u0004 — \u0003זה רשון,\u0004 שיש לו זנב. ומה שנאמר לאחריו \u0003\"למינהו\"\u0004 — הרי זה כלל, לדון שוב במידת כלל ופרט וכלל — \u0003להביא את הכרספת ואת השחלנית,\u0004 שכמו החרגול, גם להם יש זנב.","וממשיכה הברייתא: \u0003ואין לי\u0004 להכשיר ממה שלמדנו עד כה, \u0003אלא\u0004 חגב \u0003הבא\u0004 לפנינו \u0003ואין לו גבחת,\u0004 או \u0003הבא ויש לו גבחת,\u0004 וכן \u0003הבא ואין לו זנב,\u0004 או \u0003הבא ויש לו זנב,\u0004 ואולם דווקא זה \u0003הבא ואין ראשו ארוך,\u0004 שהרי כל אלו אין ראשם ארוך; אבל \u0003הבא\u0004 לפנינו \u0003וראשו ארוך, מנין\u0004 שהוא כשר?","ומשיבים: \u0003אמרת\u0004 (אומר אתה), \u0003הרי אתה דן\u0004 במידת \u0003בנין אב משלשתן:\u0004 הרי שלושתם אינם דומים, \u0003לא ראי\u0004 (ענין) \u0003ארבה\u0004 שאין לו גבחת ואין לו זנב, \u0003כראי חרגול\u0004 שיש לו גבחת ויש לו זנב; \u0003ולא ראי חרגול כראי ארבה; ולא ראי שניהם כראי סלעם,\u0004 שיש לו גבחת ואין לו זנב, \u0003ולא ראי סלעם כראי שניהם.\u0004 הרי שיש בכל אחד מהם צדדים שאין בחבירו, ואת שלושתם הכשיר הכתוב, ונמצא שאין הטהרה תלויה בסימנים אלה, אלא בצד השווה בכולם, ו\u0003הצד השוה שבהן\u0004 הוא — \u0003ש\u0004לכל אחד מהם \u0003יש לו ארבע רגלים, וארבע כנפים, וקרצולים\u0004 (רגלי ניתור), \u0003וכנפיו חופין את רובו,\u0004 ומכאן נלמד כבנין אב: \u0003אף כל שיש לו ארבע רגלים, וארבע כנפים, וקרצולים,\u0004 \u0003וכנפיו חופין את רובו\u0004 — כשר.","ויש לשאול: \u0003והלא הצרצור הזה יש לו ארבע רגלים וארבע כנפים וקרצולים וכנפיו חופין את רובו, יכול יהא מותר?\u0004 לכן \u0003תלמוד לומר\u0004 בסוף הפסוק: \u0003\"חגב\"\u0004 — לומר שצריך \u0003ש\u0004יהא \u0003שמו חגב,\u0004 וכל אלו שנזכרו הם ממיני החגבים.","ויש לשאול: \u0003אי\u0004 (אם) \u0003שמו חגב, יכול\u0004 יהיה כשר גם אם \u0003אין בו כל הסימנין הללו? תלמוד לומר\u0004 מיד אחר כך: \u0003\"למינהו\"\u0004 — ללמד שגם אם שמו חגב אינו כשר \u0003עד שיהא בו כל הסימנין הללו:\u0004 ארבעה רגלים, וארבעה כנפים, וקרצולים, וכנפיו חופות את רובו. עד כאן הברייתא ששנה החכם מבית מדרשו של ר' ישמעאל.","\u0003פריך\u0004 \u0005[הקשה]\u0006 על כך \u0003רב אחאי:\u0004 וכיצד אתה למד בבנין אב מארבה סלעם וחרגול, לכל שיש לו ארבע רגלים וארבע כנפים וקרצולים וכנפיו חופים את רובו? \u0003מה להנך\u0004 \u0005[ל\u0006שלושה \u0005אלה],\u0006 \u0003שכן\u0004 יש בהם צד משותף, ש\u0003אין ראשן ארוך!\u0004 ואם כן חגב שראשו ארוך, מניין שהוא כשר? \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003כיון דשוו\u0004 \u0005[ש\u0006הם \u0005שווים]\u0006 \u0003בארבעה סימנין\u0004 — \u0003מייתינן ולא פרכינן\u0004 \u0005[מביאים,\u0006 לומדים \u0005אנו\u0006 לכל שיש בו ארבעה סימנים אלה, ואיננו \u0005פורכים,\u0006 שוברים את הלימוד\u0005],\u0006 שבמידת \"כלל ופרט וכלל\" אין צורך שהפרטים הנלמדים יהיו שווים לגמרי לפרט המפורש; \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מניח, \u0003חרגול נמי\u0004 \u0005[גם כן],\u0006 \u0003דשוו להו\u0004 \u0005[ששווה להם]\u0006 לארבה וסלעם בארבעה סימנים אלה — \u0003לא ליכתוב\u0004 \u0005[שלא ייכתב],\u0006 \u0003ותיתי\u0004 \u0005[ושיבוא,\u0006 יילמד\u0005]\u0006 \u0003מארבה וסלעם\u0004 במידה זו!","\u0003אלא\u0004 מדוע הוצרך הכתוב להכשיר חרגול במפורש — מפני שאם היו כתובים רק ארבה וסלעם \u0003איכא למיפרך\u0004 \u0005[יש מקום להקשות]:\u0006 \u0003מה להנך\u0004 \u0005[לאלה]\u0006 לארבה וסלעם, \u0003שכן אין להן זנב,\u0004 וכיון שלחרגול יש זנב, ואינו דומה להם בכל ענין, אינו יכול להילמד מהם. אם כן, \u0003הכי נמי איכא למיפרך\u0004 \u0005[כך גם כן יש לפרוך]:\u0006 \u0003מה להנך\u0004 \u0005[לאלו]\u0006 שנזכרו בפסוק, \u0003שכן אין ראשן ארוך,\u0004 ומניין להכשיר מין חגב שיש בו ארבעה סימנים אבל ראשו ארוך?","\u0003אלא אמר רב אחאי,\u0004 מכאן למד התנא להכשיר חגב שראשו ארוך: \u0003סלעם\u0004 שנזכר בפסוק — \u0003יתירא\u0004 \u0005[יתר]\u0006 \u0003הוא,\u0004 שכן \u0003לא ליכתוב רחמנא\u0004 \u0005[\u0006ש\u0005לא תכתוב התורה]\u0006 \u0003סלעם, ותיתי\u0004 \u0005[ותביא\u0006 אותו\u0005]\u0006 בבנין אב \u0003מארבה ומחרגול,\u0004 בצד השווה בהם, שיש בהם ארבעה רגלים, וארבע כנפיים, וקרצולים, וכנפיהם חופים את רובם. \u0003דמאי פרכת\u0004 \u0005[שמה אתה מקשה]?\u0006 \u0003מה לארבה\u0004 שאין אתה יכול ללמוד ממנו לסלעם, שהרי \u0003אין לו גבחת,\u0004 ולסלעם יש גבחת — \u0003הרי חרגול\u0004 שנזכר בכתוב \u0003יש לו גבחת.\u0004 ואם תקשה: \u0003מה לחרגול\u0004 ש\u0003יש לו זנב,\u0004 ולסלעם אין זנב — \u0003הרי\u0004 הכשיר הכתוב \u0003ארבה\u0004 ש\u0003אין לו זנב!\u0004 ואם כן \u0003סלעם דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 אלא \u0003אם אינו ענין\u0004 (אם לא הוצרך) \u0003לגופו\u0004 — \u0003תנהו ענין ל\u0004חגב ש\u0003ראשו ארוך,\u0004 לומר שהוא כשר."],["ואומרים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה מקרה \u0005חלוקים]\u0006 \u0003תנא דבי\u0004 \u0005[התנא מבית מדרשו]\u0006 של \u0003רב,\u0004 ששנה את הברייתא הראשונה (לעיל סה,א), \u0003ותנא דבי\u0004 \u0005[והתנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל? ב\u0004חגב ש\u0003ראשו ארוך קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שלדעת תנא דבי רב הוא אסור, ולדעת תנא דבי ר' ישמעאל הוא מותר.","ומפרטים: \u0003תנא דבי\u0004 \u0005[התנא מבית מדרשו]\u0006 של \u0003רב סבר\u0004 \u0005[סבור]\u0006 שכך יש לדרוש את הכתובים: \"את זה תאכלו וכו' \u0003אשר לו כרעים\u0004 ממעל לרגליו לנתר בהן על הארץ\" (ויקרא יא, כא) — הרי זה \u0003כלל, \"ארבה\" \"סלעם\" \"חרגול\" \"חגב\",\u0004 וגם \u0003\"למינהו\"\u0004 הכתוב אחר כל אחד מהם — כל אחד מהם הוא \u0003פרט,\u0004 ולפי כללי מדרש ההלכה \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ונמצא שרק \u0003דמיניה\u0004 \u0005[\u0006מה \u0005שהוא מינו]\u0006 של כל אחד מן הפרטים המפורשים בכתוב — \u0003אין\u0004 \u0005[כן],\u0006 טהור, אבל כל \u0003דלאו דמיניה\u0004 \u0005[שאינו מינו]\u0006 — \u0003לא. ו\u0004מ\"מינהו\" שנאמר אחרי כל אחד מן הפרטים הוא \u0003מרבי דדמי ליה\u0004 \u0005[מרבה את מה שדומה לו]\u0006 \u0003משני צדדין,\u0004 כלומר, רק מה שהוא דומה לו לגמרי. והואיל ולכל אחד מן הפרטים המפורשים בכתוב יש ראש קצר, נמצא שחגב שראשו ארוך אסור באכילה.","ואילו \u0003תנא דבי\u0004 \u0005[התנא מבית מדרשו]\u0006 של \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 שכך יש לדרוש את הכתוב: \u0003\"אשר לו כרעים\"\u0004 — הרי זה \u0003כלל, \"ארבה\" \"סלעם\" \"חרגול\" \"חגב\"\u0004 — \u0003פרט, \"למינהו\"\u0004 האמור בכל אחד מהם — \u0003חזר וכלל,\u0004 ואם כן יש לנו \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה — \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, ומרבי כל דדמי ליה בחד צד\u0004 \u0005[ומרבה כל שדומה לו,\u0006 לפרט, אפילו \u0005בצד אחד],\u0006 כלומר, שיש לו ארבעה סימנים, שהוא הצד המשותף לכל החגבים שהזכיר הכתוב במפורש, למרות שראשו ארוך.","ותוהים: לדעת תנא דבי ר' ישמעאל, כיצד ניתן לדרוש כאן במידת כלל ופרט וכלל? \u0003והא לא דמי כללא קמא לכללא בתרא\u0004 \u0005[והרי אינו דומה הכלל הראשון לכלל האחרון]!\u0006 שכן \u0003כללא קמא\u0004 \u0005[הכלל הראשון]\u0006 — \u0003\"אשר לו כרעים\u0004 ממעל לרגליו\" \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003דאית ליה אכול דלית ליה לא תיכול\u0004 \u0005[\u0006כל \u0005שיש לו\u0006 כרעיים \u0005אכול, שאין לו\u0006 כרעיים \u0005אל תאכל],\u0006 ומשמע שאין צורך בסימנים נוספים, ואילו \u0003כללא בתרא\u0004 \u0005[הכלל האחרון],\u0006 \"למינהו\", מלמד שאינם כשרים \u0003עד דשוו\u0004 \u0005[שיהיו שווים]\u0006 \u0003בארבעה סימנין,\u0004 כפי שלמדנו מן הצד השווה שבכולם!","ומשיבים: \u0003תנא דבי\u0004 \u0005[התנא מבית מדרשו]\u0006 של \u0003ר' ישמעאל בכללי ופרטי כי האי גוונא דאין\u0004 \u0005[בכללים ופרטים כגון זה\u0006 הוא \u0005דן],\u0006 שלמרות שהכללים אינם שווים הוא דן במידת כלל ופרט וכלל. ומעירים: \u0003ודאמרינן נמי בעלמא דדאין תנא דבי\u0004 \u0005[ומה שאנו אומרים בכלל,\u0006 בכמה מקומות בתלמוד, \u0005שדן התנא מבית מדרשו]\u0006 של \u0003ר' ישמעאל בכללי ופרטי כי האי גוונא\u0004 \u0005[בכללים ופרטים כגון זה],\u0006 דבר זה נלמד \u0003מהכא\u0004 \u0005[מכאן].\u0006","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם],\u0006 התנא דבי ר' ישמעאל בסוף הברייתא: מ\"חגב\" שנזכר בפסוק זה למדנו שאינו כשר עד שיהא שמו חגב. ויש לשאול: \u0003אי\u0004 (אם) \u0003שמו חגב יכול\u0004 יהא כשר גם אם \u0003אין בו כל הסימנין הללו\u0004 המשותפים למינים המפורשים בפסוק — ארבעה רגלים וארבע כנפיים, וקרצוליים, וכנפיו חופים את רובו? \u0003תלמוד לומר \"למינהו\"\u0004 — \u0003עד שיהו בו כל הסימנין הללו.\u0004 ושואלים: ואם \u0003אין בו כל הסימנין הללו מהיכא תיתי\u0004 \u0005[מהיכן תבוא,\u0006 תלמד\u0005]\u0006 שיהיה מותר? הלא \u0003ארבה וחרגול כתיב\u0004 \u0005[נאמר\u0006 תחילה\u0005],\u0006 ויש בהם כל אותם סימנים!","ומשיבים: \u0003אי לא כתיב\u0004 \u0005[אם לא היה כתוב]\u0006 \u0003סלעם\u0004 — הייתי מפרש \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר].\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003סלעם,\u0004 ממנו למדנו \u0003לרבויי\u0004 \u0005[לרבות]\u0006 זה ש\u0003ראשו ארוך,\u0004 ואינו דומה לכל הפרטים המנויים בפסוק זה, אם כן \u0003אימא לירבי נמי כל דהו\u0004 \u0005[אמור שנרבה גם כן כל שהוא],\u0006 גם זה שאין בו סימנים אלה, אם שמו חגב — על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","ושואלים על סתירה שיש לכאורה בין הברייתות: \u0003מאי שנא התם דאמרת\u0004 \u0005[במה שונה שם\u0006 בברייתא של תנא דבי רב \u0005שאתה אומר]:\u0006 \u0003סלעם\u0004 — \u0003זה רשון, חרגול\u0004 — \u0003זה ניפול. ומאי שנא הכא דאמרת\u0004 \u0005[ומה שונה כאן\u0006 בברייתא של תנא דבי ר' ישמעאל \u0005שאמרת]:\u0006 \u0003סלעם\u0004 — \u0003זה ניפול, חרגול\u0004 — \u0003זה רשון?\u0004 ומשיבים: \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה כ\u0006לשון \u0005מקומו וחכם זה כמקומו].\u0006","שנינו במשנה: \u0003ובדגים כל שיש לו סנפיר וקשקשת. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לו עכשיו\u0004 קשקשים \u0003ועתיד לגדל לאחר זמן, כגון הסולתנית והעפיאן,\u0004 שאין להם קשקשים בצעירותם — \u0003הרי זה מותר.\u0004 וכן אם \u0003יש לו\u0004 קשקשים \u0003עכשיו ועתיד להשירן בשעה ש\u0004הוא \u0003עולה מן המים, כגון\u0004"],["הדגים הקרויים \u0003אקונס, ואפונס, כספתיאס, ואכספטיאס, ואטונס\u0004 — \u0003הרי זה מותר.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת נדה: \u0003כל שיש לו קשקשת\u0004 ודאי \u0003יש לו סנפיר, ויש שיש לו סנפיר ואין לו קשקשת. יש לו קשקשת ויש לו סנפיר\u0004 — הרי זה \u0003דג טהור, יש לו סנפיר ואין לו קשקשת\u0004 — \u0003דג טמא.\u0004","ושואלים: \u0003מכדי\u0004 \u0005[הואיל]\u0006 ורק \u0003על\u0004 \u0003קשקשת קא סמכינן\u0004 \u0005[אנו סומכים]\u0006 להכשיר דג שבא לפנינו, שהרי כל שיש לו קשקשת ודאי יש לו סנפיר, אבל סנפיר לבד יש גם בדג טמא, אם כן \u0003ליכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003קשקשת\u0004 כסימן טהרה, \u0003ולא ליכתוב\u0004 \u0005[ושלא תכתוב]\u0006 \u0003סנפיר\u0004 כלל! ומשיבים: \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 \u0003קשקשת ולא כתב\u0004 \u0005[ולא היתה כותבת]\u0006 \u0003סנפיר, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003קשקשת?\u0004 לא אותם קשקשים הקבועים בו, אלא \u0003סנפיר\u0004 שהוא שט בו, \u0003ו\u0004הייתי מכשיר \u0003אפילו דג טמא,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003סנפיר וקשקשת,\u0004 כדי שלא יבואו לידי טעות.","ושואלים: \u0003והשתא דכתב רחמנא\u0004 \u0005[ו\u0006הרי גם \u0005עכשיו שכתבה התורה]\u0006 \u0003סנפיר וקשקשת, ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אנו יודעים ש\u0003קשקשת לבושא\u0004 \u0005[לבוש]\u0006 הדג \u0003הוא,\u0004 ולא מה שהוא שט בו — ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במקום אחר: \u0003\"ושריון קשקשים הוא לבוש\"\u0004 (שמואל א יז, ה); ואם כן חוזרת השאלה: \u0003וליכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 רק \u0003קשקשת, ולא ליכתוב\u0004 \u0005[ושלא תכתוב]\u0006 \u0003סנפיר,\u0004 שהרי אנו יודעים מהי קשקשת, ואין חשש שנבוא לידי טעות, לומר שקשקשת היא סנפיר!","\u0003אמר ר' אבהו, וכן תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 רצה הקדוש ברוך הוא לזכות את ישראל, לפיכך הרבה להם תורה, שנאמר: \"ה' חפץ למען צדקו \u0003יגדיל תורה ויאדיר\"\u0004 (ישעיהו מב, כא), והרחיב גם במקום שניתן היה לכאורה לצמצם.","ובענין הדגים הטהורים והטמאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"את זה תאכלו מכל אשר במים כל אשר לו סנפיר וקשקשת\" (ויקרא יא, ט), ואחר כך נאמר: \"וכל אשר אין לו סנפיר וקשקשת... לא תאכלו\" (שם י— יא). ויש לשאול: מדוע הוצרכנו לשניהם? והרי \u0003ממשמע שנאמר: אכול את שיש לו\u0004 סנפיר וקשקשת, \u0003שומע אני\u0004 ממילא: \u0003אל תאכל את שאין לו, וממשמע שנאמר: אל תאכל את שאין לו\u0004 סנפיר וקשקשת, \u0003שומע אני: אכול את שיש לו, ולמה שנאן? לעבור עליו,\u0004 על אכילת דג טמא, \u0003ב\u0004איסור \u0003עשה ו\u0004איסור \u0003לא תעשה.\u0004 ודנים במקרים בהם מותר לאכול דגים או שאר שרצי מים.","נאמר: \"את זה תאכלו מכל אשר במים, כל אשר לו סנפיר וקשקשת במים בימים ובנחלים אותם תאכלו\" (שם ט), ויש לשאול: \"את זה \u0003תאכלו מכל אשר במים\" מה תלמוד לומר?\u0004 מה בא ללמד? ומסבירים: \u0003ש\u0004לולא כתוב זה \u0003יכול\u0004 היית לומר: \u0003הואיל והתיר\u0004 הכתוב בפסוק אחד שרצי מים (שאין להם סנפיר וקשקשת) \u0003במפורש, והתיר\u0004 אותם בפסוק אחר \u0003בסתם,\u0004 שלא בצורה מפורשת (וכפי שיבואר להלן), אם כן יש ללמוד מזה על זה: \u0003מה כשהתיר במפורש\u0004 \u0003לא התיר אלא\u0004 את אלה שנמצאים במים ש\u0003בכלים,\u0004 כמבואר להלן, \u0003אף כשהתיר בסתם\u0004 — \u0003לא התיר אלא בכלים.\u0004 ואם כן \u0003מנין לרבות\u0004 ולהתיר גם \u0003בורות\u0004 \u0003שיחין\u0004 (חפירות מאורכות) \u0003ומערות, ששוחה ושותה מהן\u0004 מים, \u0003ואינו נמנע\u0004 מלשתותם עם השרצים שבתוכם? \u0003תלמוד לומר \"תאכלו מכל אשר במים\",\u0004 להתיר גם אלו שבבורות שיחין ומערות.","ואומרים: \u0003היכן התיר בכלים? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"את זה תאכלו מכל אשר במים\u0004 כל אשר לו סנפיר וקשקשת במים בימים ובנחלים אותם תאכלו\" (שם), ודי היה לומר: \"במים\", ומדוע נאמר \"בימים ובנחלים\"? לומר: דווקא \u0003בימים ובנחלים הוא דכי אית ליה\u0004 \u0005[שכאשר יש לו]\u0006 סנפיר וקשקשת \u0003אכול\u0004 אותו, \u0003דלית ליה לא תיכול\u0004 \u0005[שאין לו\u0006 סנפיר וקשקשת \u0005אל תאכל]\u0006 אותו, \u0003הא\u0004 \u0005[אבל]\u0006 זה שנמצא במים ש\u0003בכלים\u0004 — \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 סנפיר וקשקשת \u0003אכול.\u0004","ושואלים, \u0003אימא\u0004 \u0005[אמור]\u0006 ודייק להיפך: דווקא בימים ובנחלים — אם יש לו סנפיר וקשקשת תאכל, אבל \u0003בכלים\u0004 — \u0003אף על גב דאית ליה\u0004 \u0005[אף על פי שיש לו]\u0006 סימנים אלה \u0003לא תיכול\u0004 \u0005[אל תאכל]!\u0006 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בהמשך: \u0003\"וכל אשר אין לו סנפיר וקשקשת בימים ובנחלים מכל שרץ המים\u0004 וכו' לא תאכלו\" (שם י— יא), לומר: \u0003בימים ובנחלים\u0004 הוא \u0003דלית ליה לא תיכול\u0004 \u0005[ש\u0006אם \u0005אין לו\u0006 סנפיר וקשקשת \u0005אל תאכל],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003בכלים\u0004 — \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 סימנים אלה \u0003אכול.\u0004 ושואלים: ומדוע הוצרכנו לכתוב \"תאכלו מכל אשר במים\" להתיר שרצי מים שבבורות שיחין ומערות?","\u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש כך: \"את זה תאכלו מכל אשר במים כל אשר לו סנפיר וקשקשת במים בימים ובנחלים\", \"את זה תאכלו מכל אשר \u0003במים\"\u0004 — הרי זה \u0003כלל, \"בימים ובנחלים\"\u0004 — \u0003פרט, כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ב\u0003ימים ונחלים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אכול רק את שיש לו סנפיר וקשקשת, אבל בכל מים אחרים, כגון אלו המצויים ב\u0003נעיצין וחריצין,\u0004 בברכות ותעלות, וכן בבורות שיחין ומערות — \u0003לא\u0004 נאמרה מצוה זו, אלא מותר אתה לאכול גם את אלו שאין להם סנפיר וקשקשת!","ומשיבים: מה שנאמר שוב \u0003\"במים\"\u0004 בפסוק זה, לפני \"בימים ובנחלים\" — \u0003חזר וכלל,\u0004 ויש כאן כלל (\"מים\") ופרט (\"בימים ובנחלים\") וכלל (\"מים\"), ולפי כללי מדרש ההלכה, בכלל ופרט וכלל — לא רק הפרט המפורש נאסר, אלא כל שהוא כעין הפרט, ואם כן כל מים שנמצאים בקרקע בכלל זה, משום כך הוצרך הכתוב \"תאכלו מכל אשר במים\" — כדי להתיר את אלה הנמצאים בבורות שיחין ומערות (ולא בנעיצין וחריצין).","ושואלים: וכיצד אתה דורש פסוק זה בדרך כלל ופרט וכלל? והלא \u0003הני תרי כללי דסמיכי להדדי נינהו\u0004 \u0005[אלה שני כללים שסמוכים זה לזה הם],\u0006 ש\"במים\" השני נאמר גם כן לפני הפרט \"בימים ובנחלים\", ואם יש כאן כלל וכלל ופרט! \u0003אמר רבינא, כדאמרי במערבא\u0004 \u0005[כמו שאומרים בארץ ישראל]:\u0006 \u0003כל מקום שאתה מוצא שני כללות\u0004 \u0003הסמוכין זה לזה,\u0004 אם יש פרט סמוך להם —"],["\u0003הטל\u0004 את ה\u0003פרט ביניהם ודונם בכלל ופרט וכלל.\u0004 ולפי זה, כך יש לדרוש את הכתוב \"מכל אשר במים וכו' במים בימים ובנחלים אותם תאכלו\" (ויקרא יא, ט) כאילו נאמר: \"כל אשר במים וכו' בימים ובנחלים במים אותם תאכלו\": \u0003\"במים\"\u0004 — הרי זה \u0003כלל, \"בימים ובנחלים\"\u0004 — \u0003פרט, \"במים\"\u0004 —","\u0003חזר וכלל, כלל ופרט וכלל\u0004 — \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש\u0004 — ימים ונחלים, שהם \u0003מים נובעים, אף כל\u0004 \u0003מים נובעים\u0004 נאסר בהם מה שאין לו סנפיר וקשקשת. ואם כן \u0003מאי רבי\u0004 \u0005[מה ריבה\u0006 בכך\u0005]?\u0006 ריבה \u0003חריצין ונעיצין לאיסורא\u0004 \u0005[לאיסור],\u0006 שהמים שבהם נובעים, \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט? בורות שיחין ומערות להתירא\u0004 \u0005[להיתר],\u0006 שאין המים שבהם נובעים, אלא מי גשמים נאספים לתוכם.","ושואלים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003מה הפרט מפורש\u0004 — \u0003מים גדלין\u0004 (נמצאים) \u0003על גבי קרקע\u0004 — \u0003אף כל\u0004 שהוא \u0003מים גדלין על גבי קרקע. ו\u0004לפי זה, \u0003מאי רבי\u0004 \u0005[מה ריבה]\u0006 בכך — \u0003אפילו בורות שיחין ומערות לאיסורא\u0004 \u0005[לאיסור],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 בכך? \u0003מיעט\u0004 רק מים שב\u0003כלים!\u0004","ומשיבים: \u0003אם כן,\u0004 הכתוב \u0003\"תאכלו\u0004 מכל אשר במים\" (שם), שנאמר בתחילת הפסוק כדי להתיר, \u0003מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006 מה הוא בא להתיר? הרי גם בלעדיו לא היינו אוסרים כלים, שהרי אינם דומים כלל לפרט המפורש, שהוא מים המצויים על הקרקע! אלא לכך נאמר \"תאכלו\" — ללמדנו שמה שנאסר כעין הפרט, הוא רק חריצין ונעיצין.","התנא \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 כך, דרש כך את הכתוב: מה שנאמר בפסוק זה \u0003\"במים\" \"במים\" שתי פעמים\u0004 (\"מכל אשר במים כל אשר לו סנפיר וקשקשת במים בימים ובנחלים אותם תאכלו\". ויקרא יא, ט) — \u0003אין זה כלל ופרט, אלא\u0004 צריך ללמוד אותו בדרך של \u0003ריבה ומיעט,\u0004 ובאופן זה: \u0003\"במים\"\u0004 — \u0003ריבה, \"בימים ובנחלים\"\u0004 — \u0003מיעט, \"במים\"\u0004 — \u0003חזר וריבה.\u0004 ולפי כללי מדרש ההלכה \u0003ריבה ומיעט וריבה\u0004 — \u0003ריבה הכל,\u0004 חוץ ממה שאינו דומה כלל לימים ונחלים. ואם כן, \u0003מאי רבי\u0004 \u0005[מה ריבה]?\u0006 את הדגים שאין להם סנפיר וקשקשת ב\u0003חריצין ונעיצין לאיסורא\u0004 \u0005[לאיסור],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט?\u0004 את אלה שב\u0003בורות שיחין ומערות להתירא\u0004 \u0005[להיתר].\u0006","ושואלים, הואיל ואתה מרבה הכל חוץ ממה שאינו דומה כלל לימים ונחלים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ריבה?\u0004 ריבה \u0003בורות שיחין ומערות לאיסורא\u0004 \u0005[לאיסור],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 להיתר? \u0003מיעט\u0004 רק \u0003כלים!\u0004 ומשיבים: \u0003אם כן, \"תאכלו\"\u0004 שנאמר בתחילת הפסוק להתיר, \u0003מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006 הרי לדרך זו, כבר הותרו כלים על ידי ריבוי ומיעוט! אלא בוודאי בא כדי ללמדנו שיש ללמוד בריבוי ומיעוט להתיר את אלה שבבורות שיחין ומערות.","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני],\u0006 ואומר שריבה בורות לאיסור, ומיעט חריצין ונעיצין להיתר! ומשיבים: יש לתרץ דבר זה \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 החכם \u0003מתתיה, דתני\u0004 \u0005[ששנה]\u0006 \u0003מתתיה בר יהודה: מאי\u0004 \u0005[מה]\u0006 \u0003ראית לרבות בורות שיחין ומערות להתירא\u0004 \u0005[להיתר],\u0006 \u0003ולהוציא חריצין ונעיצין לאיסורא\u0004 \u0005[לאיסור]?\u0006 \u0003מרבה אני בורות שיחין ומערות שהן\u0004 המים \u0003עצורים\u0004 (סגורים בתוכם) \u0003ככלים, ומוציא אני חריצין ונעיצין שאין עצורין ככלים,\u0004 אלא המים זורמים לתוכם ויוצאים מהם.","בברייתא שהובאה בעמוד הקודם נאמר כי הכתוב התיר פעמיים שרץ המים שאין לו סנפיר וקשקשת, פעם במפורש ופעם בסתום, מה כשהתיר במפורש — התיר במים שבכלים, אף כשהתיר בסתום — לא התיר אלא במים שבכלים. ושואלים: \u0003הי\u0004 \u0005[איזהו]\u0006 ה\u0003סתום והי\u0004 \u0005[ואיזהו]\u0006 ה\u0003מפורש? פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד מהם]\u0006 \u0003אמר:\u0004 הכתוב המתיר כל ש\u0003יש לו\u0004 סנפיר וקשקשת בימים ובנחלים (ויקרא יא, ט) הוא ה\u0003מפורש, ו\u0004הכתוב האוסר זה \u0003ש\u0004\u0003אין לו\u0004 סנפיר וקשקשת בימים ובנחלים (שם י—יא) הוא ה\u0003סתום. וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר:\u0004 הכתוב האוסר את ש\u0003אין לו\u0004 סנפיר וקשקשת בימים ובנחלים, הוא ה\u0003מפורש, ו\u0004הכתוב המתיר את ש\u0003יש לו\u0004 סנפיר וקשקשת בימים ובנחלים, הוא ה\u0003סתום.\u0004","ושואלים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 שהכתוב המתיר כל ש\u0003יש לו\u0004 סנפיר וקשקשת בימים ובנחלים הוא ה\u0003מפורש?\u0004 ומשיבים, \u0003אמר לך\u0004 \u0005[יכול הוא לומר לך]\u0006 כך: \u0003מיניה הוא דקא משתרו\u0004 \u0005[\u0006שהרי \u0005ממנו,\u0006 מפסוק זה \u0005הוא\u0006 שלמדנו \u0005שמותרים]\u0006 השרצים שבמים ב\u0003כלים.\u0004 שכן דרשנו: בימים ובנחלים הוא שתאכלו את שיש לו סנפיר וקשקשת, ולא את זה שאין לו סנפיר וקשקשת. אבל בכלים — אפילו זה שאין לו סנפיר וקשקשת מותר.","ושואלים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 שהכתוב האוסר זה ש\u0003אין לו\u0004 סנפיר וקשקשת הוא ה\u0003מפורש?\u0004 ומשיבים: מפני \u0003דהאי הוא דקמוכח אהאיך\u0004 \u0005[שהוא שמוכיח על\u0006 הכתוב \u0005האחר,\u0006 הראשון\u0005]\u0006 שהוא בא להתיר. \u0003דאי מהאיך\u0004 \u0005[שאם מהאחר]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ומדייק לאיסור: בימים ובנחלים הוא שתאכל את שיש לו סנפיר וקשקשת, ומכאן ש\u0003בכלים\u0004 — \u0003אף על גב דאית ליה\u0004 \u0005[אף על פי שיש לו סנפיר וקשקשת]\u0006 \u0003נמי לא תיכול\u0004 \u0005[גם כן לא תאכל],\u0006 ולכן בא כתוב זה \"וכל אשר אין לו סנפיר וקשקשת בימים ובנחלים לא תאכלו\", לומר: בימים ובנחלים לא תאכלו את שאין לו סנפיר וקשקשת, אבל בכלים — אף את זה שאין לו סנפיר וקשקשת תאכלו.","ובענין המים שבכלים, שהשרצים שגדלים בהם מותרים, \u0003אמר רב הונא: לא לשפי אינש שיכרא בצבייתא באורתא\u0004 \u0005[לא ישפוך אדם שיכר\u0006 לכלי \u0005דרך קיסמים בלילה]\u0006 כדי לסננו, \u0003דילמא פריש לעיל מצבייתא והדר נפיל לכסא\u0004 \u0005[שמא יפרוש\u0006 השרץ \u0005על הקיסמים ואחר כך יפול\u0006 מהם \u0005לכוס],\u0006 \u0003ו\u0004כשהוא שותה את השיכר עם השרצים שבתוכו, מתוך הנחה שלא באו מן החוץ (שהרי סינן את השיכר), אלא נוצרו בכלי והריהם מותרים, \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003עובר\u0004 עליו \u0003משום \"שרץ השורץ על הארץ\"\u0004 (ויקרא יא, מא).","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה חושש לכעין זה, \u0003במנא נמי\u0004 \u0005[\u0006בשיכר סתם הנמצא \u0005בכלי גם כן]\u0006 יש לחשוש, \u0003דלמא פריש לדפנא דמנא והדר נפיל למנא\u0004 \u0005[שמא פרש לדופן הכלי וחזר ונפל לכלי]!\u0006 ומשיבים: \u0003התם היינו רביתיה\u0004 \u0005[שם זהו דרך גידולו],\u0006 שכשהוא בכלי הוא נדבק לדופן הכלי, ואין זה נחשב כמי שפרש מן המים.","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 שדבר שהוא בדרך גידולו אין מקפידים עליו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין לרבות\u0004 מים שב\u0003בורות שיחין ומערות ששוחה ושותה מהן, ואינו נמנע\u0004 מלשתותם עם שרצים שבהם? \u0003תלמוד לומר: \"תאכלו מכל אשר במים\"\u0004 (שם ט), להתיר הגדל במים שבבורות, למרות שאין לו סנפיר וקשקשת; \u0003ו\u0004לכאורה \u0003ליחוש דלמא פריש לדפנא והדר נפיל\u0004 \u0005[ושנחשוש שמא פרש לדופן\u0006 הבור, ונעשה שרץ הארץ, \u0005וחזר ונפל]\u0006 למים! \u0003אלא\u0004 אומר אתה: \u0003היינו רביתיה\u0004 \u0005[זהו דרך גידולו],\u0006 ואינו נאסר בכך — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בכלי, אמור: \u0003היינו רביתיה\u0004 \u0005[זוהי דרך גידולו]\u0006 ואינו נאסר בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב הונא, תניא דמסייע לך\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת לך],\u0006 שרק בשיכר שסיננו יש לחשוש לשרצים שפרשו ונפלו לתוכו. ששנינו: מה שנאמר \u0003\"כל השרץ השורץ על הארץ\"\u0004 (שם מא) — הרי זה בא \u0003לרבות יבחושין\u0004 הנמצאים במים (או שאר משקים) \u0003שסיננן;\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003סיננן, הא\u0004 \u0005[אבל]\u0006 אם \u0003לא סיננן\u0004 — \u0003שרי\u0004 \u0005[מותרים\u0006 הם\u0005],\u0006 ואין לחשוש אם פרשו לדופן הכלי וחזרו.","ועוד בענייני \"שרץ השורץ על הארץ\". \u0003אמר שמואל: קישות\u0004 (מלפפון) \u0003שהתליעה\u0004 (שגדלו בה תולעים)"],["\u0003באביה,\u0004 בעוד היא מחוברת לקרקע — \u0003אסורה\u0004 התולעת שבה \u0003משום \"השרץ השורץ על הארץ\"\u0004 (ויקרא יא, מא), כיון ששרצה בעוד הקישות מחוברת לארץ.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם אפשר לסייע לו],\u0006 ממה שנראה כסתירה לכאורה בין שתי ברייתות, \u0003דתני חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 \"השרץ השורץ \u0003על הארץ\"\u0004 — \u0003להוציא את הזיזין\u0004 (מיני חרקים) \u0003ש\u0004מצויים \u0003בעדשים, ואת היתושים ש\u0004נמצאים \u0003בכליסים\u0004 (מין קטניות), \u0003ותולעת שבתמרים ושבגרוגרות\u0004 (תמרים יבשות), שהם מותרים, מפני שאינם שורצים בארץ. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כל השרץ השורץ על הארץ\",\u0004 \"כל\" — \u0003לרבות\u0004 \u0003תולעת ש\u0004נמצאת \u0003בעיקרי זיתים ושבעיקרי גפנים,\u0004 שגם היא אסורה.","\u0003מאי לאו\u0004 \u0005[האם לא],\u0006 \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 עוסקות בתולעת הנמצאת \u0003בפירא\u0004 \u0005[בתוך הפרי],\u0006 \u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו],\u0006 שאסרה תולעת בזיתים ובגפנים, עוסקת כשהתליעה \u0003באביה,\u0004 כשהפרי צומח ומחובר לקרקע, \u0003והא\u0004 \u0005[וזו]\u0006 שהתירה זיזים שבעדשים, עוסקת כשהתליעה \u0003שלא באביה,\u0004 אלא לאחר שנתלשו. ומכאן סיוע לדברי שמואל, שקישות שהתליעה באביה אסורה?","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 עוסקות בתולעת שהתליעה \u0003באביה,\u0004 בעוד הפרי מחובר, \u0003ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003הא בפירא\u0004 \u0005[זו\u0006 שמתירה, עוסקת בתולעת שגדלה \u0005בפרי],\u0006 וגם כשהוא מחובר, שלא כדברי שמואל שאוסר, \u0003הא באילנא גופא\u0004 \u0005[וזו\u0006 האוסרת, עוסקת בתולעת הגדלה \u0005בגוף האילן].\u0006","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן כך],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003תולעת שבעיקרי זיתים ושבעיקרי גפנים,\u0004 כלומר, בגזע עץ הזית או הגפן. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ממה ששנינו לעיל נמצא שלכל הדעות, תולעת שנוצרה בפרי כשהוא תלוש, ולא פרשה ממנו לארץ — מותרת, ואין בה משום \"שרץ השורץ על הארץ\". ובפרטי עניין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף:\u0004 אם \u0003פרשה\u0004 התולעת מן הפרי \u0003ומתה\u0004 מיד, קודם שהספיקה לרחוש על הארץ, \u0003מהו\u0004 דינה, האם היא מותרת? אם פירשה \u0003מקצתה, מהו?\u0004 אם פירשה \u0003לאויר העולם\u0004 ולא נפלה לארץ, \u0003מהו?\u0004 כל השאלות הללו לא נפתרו, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 תולעת שנוצרה בתוך תמרה, וטיפסה ועלתה \u0003לגג\u0004 (החלק העליון) של ה\u0003תמרה, מהו?\u0004 האם היא נחשבת כרוחשת על דבר אחר, ואסורה משום \"שרץ השורץ על הארץ\", או שמא היא נחשבת כמצויה במקום גידולה ומותרת? ואם תאמר שגג התמרה אינו נחשב מקום גידולה, עלתה התולעת \u0003לגג גרעינתה\u0004 של התמרה, \u0003מהו?\u0004 האם גם זה בכלל מקום גידולה, או לא? לא טיפסה התולעת לגג התמרה, אלא יצאה \u0003מתמרה לתמרה\u0004 אחרת שהיתה דבוקה לה, \u0003מהו?\u0004 שאלות אלה לא נפתרו, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: קוקיאני,\u0004 תולעים שיש באיברים הפנימיים של בהמות, כגון בריאה ובכבד — \u0003אסירי\u0004 \u0005[אסורות]\u0006 באכילה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מעלמא אתו\u0004 \u0005[מבחוץ באו],\u0006 שבלעה אותן, וכבר נאסרו קודם לכן משום \"שרץ השורץ על הארץ\".","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: אי מעלמא אתו\u0004 \u0005[אם מבחוץ הן באות],\u0006 שבלעה אותם — \u0003לישתכחו\u0004 \u0005[שיימצאו]\u0006 גם ב\u0003דרך בית הריעי,\u0004 במערכת העיכול. ומאחר שלא נמצאו במערכת העיכול אלא בכבד או בריאה, משמע שנוצרו בתוך הבהמה, ואין הם שרץ הארץ!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: קוקיאני שרו\u0004 \u0005[מותרות],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מיניה גבלי\u0004 \u0005[ממנה\u0006 הם \u0005נוצרים].\u0006 \u0003אמר רב אשי: פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, \u0003דאי מעלמא קא אתו\u0004 \u0005[שאם מהעולם,\u0006 מהחוץ \u0005הן באות]\u0006 — \u0003לישתכחו\u0004 \u0005[שיימצאו]\u0006 \u0003דרך בית הריעי!\u0004","ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003קוקיאני אסירי\u0004 \u0005[אסורות],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מינם ניים, ועיילי ליה באוסייה\u0004 \u0005[ישנה\u0006 הבהמה \u0005ונכנסות בחוטמה]\u0006 ה\u0003תולעים,\u0004 ומשם עוברים לאיבריה הפנימיים, שלא דרך מערכת העיכול. \u0003דרני דבשרא\u0004 \u0005[תולעים שנמצאות בבשר]\u0006 הבהמה, בין העור לבשר — \u0003אסירי\u0004 \u0005[אסורות],\u0006 \u0003דכוורי\u0004 \u0005[\u0006אלו \u0005שנמצאות בדגים]\u0006 — \u0003שריין\u0004 \u0005[מותרות].\u0006","וכן מסופר, \u0003אמר לה רבינא לאימיה\u0004 \u0005[לאמו]:\u0006 \u0003אבלע לי ואנא איכול\u0004 \u0005[הבליעי לי\u0006 את \u0005התולעים שבדגים,\u0006 שלא אראה אותן, שנפשי קצה בדבר, \u0005ואני אוכל]\u0006 את הדגים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא לרבינא\u0004 שנהג כן: \u0003מאי שנא מהא דתניא\u0004 \u0005[במה שונה\u0006 הדבר \u0005מזו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003\"ואת נבלתם תשקצו\"\u0004 (ויקרא יא, יא) — \u0003לרבות את הדרנים\u0004 (התולעים) \u0003שבבהמה,\u0004 שהם אסורים! מדוע אלו שבדגים מותרות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003בהמה\u0004 — רק \u0003בשחיטה הוא דמשתריא\u0004 \u0005[שנעשית מותרת],\u0006 וקודם לכן הריהי בכלל איסור אבר מן החי, היא וכל מה שגדל בגופה. \u0003והני, מדלא קא מהניא להו\u0004 \u0005[ואלה,\u0006 התולעים שבה, \u0005מכיון שאין מועילה להן]\u0006 ה\u0003שחיטה,\u0004 שהרי יש להן חיים לעצמן — \u0003באיסורייהו קיימן\u0004 \u0005[באיסורן הן עומדות].\u0006 \u0003אבל דגים\u0004 — \u0003באסיפה בעלמא מישתרי\u0004 \u0005[באסיפה בלבד הם מותרים],\u0006 ואין בהם איסור אבר מן החי, \u0003והני כי קא גבלן\u0004 \u0005[ו\u0006תולעים \u0005אלה, כאשר הן נוצרות\u0006 בתוכם\u0005]\u0006 — \u0003בהיתרא קא גבלן\u0004 \u0005[בהיתר הם נוצרות].\u0006 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר: \"כל הולך על גחון, וכל הולך על ארבע, עד כל מרבה רגלים לכל השרץ השורץ על הארץ לא תאכלום\" (ויקרא יא, מב), \u0003\"הולך על גחון\"\u0004 — \u0003זה נחש, \"כל\u0004 הולך על גחון\" — \u0003לרבות השילשול ואת הדומה לשילשול, \"על ארבע\"\u0004 — \u0003זה עקרב, \"כל הולך\u0004 על ארבע\" — \u0003לרבות את החיפושית ואת הדומה לחיפושית, \"מרבה רגלים\"\u0004 — \u0003זה נדל, \"עד כל\u0004 מרבה רגלים\" — \u0003לרבות את הדומה\u0004 לנדל, \u0003ואת הדומה לדומה.\u0004","","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בן דורמסקית אומר: לויתן\u0004 שנזכר בכתובים — \u0003דג טהור הוא, שנאמר\u0004 בו: \u0003\"גאוה אפיקי מגנים\"\u0004 (איוב מא, ז), וכן נאמר בו: \u0003\"תחתיו חדודי חרש\"\u0004 (שם, כב); \u0003\"אפיקי מגנים\"\u0004 — \u0003אלו קשקשים שבו,\u0004 שמגינים עליו כמו שריון, \u0003\"תחתיו חדודי חרש\"\u0004 — \u0003אלו סנפירין שפורח\u0004 (ששט) \u0003בהן,\u0004",""],["\u0003בהמה המקשה לילד\u0004 ועמדו לשוחטה, \u0003והוציא העובר את ידו,\u0004 \u0003והחזירו\u0004 לפני שנשחטה הבהמה — אינו נחשב כילוד ו\u0003מותר באכילה,\u0004 שהעובר ניתר באכילה בשחיטת אמו. \u0003הוציא\u0004 העובר \u0003את ראשו, אף על פי שהחזירו\u0004 לאחר מכן — \u0003הרי זה כילוד,\u0004 וצריך שחיטה לעצמו.","אם היה \u0003חותך מעובר שבמעיה\u0004 קודם שחיטה, ולא הוציא ממעיה את מה שחתך — הרי זה \u0003מותר באכילה\u0004 לאחר שחיטתה, אבל אם חתך \u0003מן הטחול ומן הכליות\u0004 של הבהמה עצמה קודם שחיטה — \u0003אסור באכילה,\u0004 למרות שלא הוציאם מגופה, משום שנעשו אבר שנחתך מן החי, ושוב לא תועיל השחיטה להתירם. \u0003זה הכלל: דבר ש\u0004הוא \u0003גופה\u0004 — \u0003אסור\u0004 באכילה, \u0003ו\u0004דבר \u0003שאינה גופה\u0004 — \u0003מותר.\u0004","על מה ששנינו שאם הוציא עובר את ידו והחזירו קודם שחיטה — מותר, \u0003אמר רב יהודה אמר רב: ואבר עצמו,\u0004 היד שהוציא העובר — \u0003אסור\u0004 באכילה לעולם.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל), והמלה \"בשדה\", שהיא מיותרת לכאורה, באה ללמדנו הלכה כללית: \u0003כיון שיצא בשר חוץ למחיצתו,\u0004 מחוץ למקום בו הוא מותר — \u0003נאסר.\u0004 והרי הרחם הוא מחיצת העובר, ששם הוא נעשה מותר בשחיטת האם, ולכן כשיצא אבר משם — נאסר.","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003בהמה המקשה לילד, והוציא העובר את ידו והחזירו\u0004 — \u0003מותר באכילה, מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003ל\u0004\u0003אבר,\u0004 ליד שהוציא, שהוא מותר באכילה? והרי זה שלא כדעת רב. ודוחים: \u0003לא,\u0004 על ה\u0003עובר\u0004 עצמו מדובר, שהוא מותר, חוץ מן האבר שיצא.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 על ה\u0003עובר, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע מדובר דווקא\u0005]\u0006 כש\u0003החזירו\u0004 את האבר? \u0003אפילו לא החזירו נמי\u0004 \u0005[גם כן]\u0006 יהיה העובר עצמו מותר! ומשיבים: באמת, \u0003הוא הדין אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא החזירו\u0004 גם כן מותר העובר באכילה, \u0003ואיידי דקא בעי מיתנא סיפא\u0004 \u0005[ו\u0006רק \u0005מתוך שרצה לשנות בסוף,\u0006 בהמשך\u0005],\u0006 שאם \u0003הוציא את ראשו אף על פי שהחזירו הרי זה כילוד,\u0004 ואינו ניתר בשחיטת האם — \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן בתחילה]\u0006 לשון \u0003החזירו.\u0004","ומקשים: \u0003וסיפא\u0004 \u0005[ובסוף\u0006 עצמו\u0005]\u0006 \u0003מאי קמשמע לן\u0004 \u0005[מה בא להשמיע לנו],\u0006 ש\u0003כיון\u0004 ש\u0003יצא ראשו הויא לה\u0004 \u0005[הרי זו]\u0006 \u0003לידה?\u0004 הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה במסכת בכורות, בדיני בכור אדם: \u0003איזהו בכור לנחלה,\u0004 שיורש חלק כפול מאחיו, \u0003ו\u0004אולם \u0003אינו בכור לכהנים,\u0004 שאינו קדוש בבכורה ואיך צורך לפדותו? \u0003זה\u0004 \u0003הבא\u0004 (הנולד) \u0003אחר נפלים,\u0004 אחרי עובר שלא נגמר הריונו, \u0003אף על פי שיצא ראשו\u0004 של הנפל \u0003חי, או\u0004 הנולד אחר \u0003בן תשעה\u0004 חדשים, שכבר נגמר הריונו, אלא \u0003שיצא ראשו\u0004 כשהוא \u0003מת.\u0004","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה שיצא \u0003ראשו מת\u0004 — הבא אחריו בכור לנחלה, \u0003הא\u0004 \u0005[אבל]\u0006 אם יצא \u0003ראשו\u0004 של בן תשעה \u0003חי\u0004 אף שמת קודם שיצא כולו — לידה גמורה היא, \u0003ו\u0004\u0003הבא אחריו\u0004 אפילו \u0003בכור לנחלה נמי לא הוי\u0004 \u0005[גם כן איננו].\u0006 ואם כן, כבר השמיע לנו התנא שיציאת הראש נחשבת לידה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שם \u0003אשמעינן\u0004 \u0005[השמיע לנו]\u0006 דין זה \u0003באדם, וקא משמע לן\u0004 \u0005[ומשמיע לנו]\u0006 דין זה במשנתנו \u0003בבהמה.\u0004","והוצרך לכך, שכן \u0003אדם מבהמה\u0004 לכאורה \u0003לא יליף\u0004 \u0005[אינו לומד],\u0006 לפי ש\u0003אין פרוזדור לבהמה,\u0004 אלא פתח הרחם שלה מגולה, ויש לומר שדווקא בה נחשבת יציאת הראש בלידה. אבל באדם, שירכיה של האשה הן כעין פרוזדור לפתח הרחם, ואין יציאת הראש לבדו ניכרת, הייתי אומר שלא תיחשב יציאת הראש כלידה. \u0003ו\u0004כן מצד שני, אם היה שונה רק את המשנה בענין אדם, הייתי אומר כי \u0003בהמה מאדם לא ילפא\u0004 \u0005[אינה נלמדת],\u0006 כי דווקא באדם יציאת הראש לעצמה נחשבת לידה, מפני \u0003דחשיב\u0004 \u0005[שחשוב]\u0006 \u0003פרצוף פנים דידיה\u0004 \u0005[שלו],\u0006 שנברא בצלם אלקים, ויש בו דעת, מה שאין כן בבהמה. ולכן הוצרכנו למה ששנינו במשנתנו, שהוצאת הראש בבהמה נחשבת כלידה.","ואולם \u0003הא נמי תנינא\u0004 \u0005[\u0006דבר \u0005זה,\u0006 שדין הבהמה כדין האדם, \u0005גם כן שנינו]:\u0006 \u0003שליא\u0004 (מעין כיס שבתוכו מצוי הוולד) \u0003שיצתה\u0004 (שיצאה) \u0003מקצתה\u0004 קודם שחיטת הבהמה — \u0003אסורה\u0004 כולה \u0003באכילה,\u0004 שמא יצא ראש העובר באותו מקצת, והרי זה כילוד שלא הותר בשחיטה, מפני שהשליא, \u0003כ\u0004שם שהיא \u0003סימן ולד באשה\u0004 — \u0003כך\u0004 היא \u0003סימן ולד בבהמה!\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003החזירו דרישא דוקא\u0004 \u0005[\u0006של תחילת המשנה \u0005מדוייק],\u0006 לומר: עובר שהוציא את ידו, אם החזירה קודם שחיטה — מותרת היד באכילה, ואם לא החזירה — היד עצמה אסורה, מובן מדוע שנה בסיפא דין החזיר ראשו, למרות שכבר שנינו דין זה במשנה במסכת בכורות, שכן \u0003תנא סיפא אטו רישא\u0004 \u0005[שנה את הסוף\u0006 שהוציא ראשו והחזירו \u0005משום\u0006 דין החזיר ידו \u0005שבתחילה].\u0006","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 \u0003לא דרישא דוקא ולא דסיפא דוקא\u0004 \u0005[לא\u0006 דין החזיר ידו \u0005של ההתחלה\u0006 נאמר בדווקא, \u0005ולא\u0006 דין החזיר ראשו \u0005של הסוף\u0006 נאמר בדווקא\u0005],\u0006 \u0003למה ליה למתנייה\u0004 \u0005[למה לו לשנות אותו]\u0006 \u0003כלל\u0004 דין הוציא אבר והחזירו במשנתנו! אלא בהכרח, מה שנאמר בתחילת המשנה: הוציא ידו והחזירו מותר — על היד נאמר, שאם החזירה הריהי מותרת, שלא כדברי רב יהודה בשם רב!","ודוחים: \u0003לא, לעולם\u0004 מה שנאמר מותר באכילה מדבר על ה\u0003עובר\u0004 עצמו, ולא על היד שהחזיר. \u0003ו\u0004אף שלכאורה, העובר עצמו מותר גם אם לא החזיר את היד — יש להסביר את הדבר כמו ש\u0003אמר רב נחמן בר יצחק\u0004 בהסבר הברייתא להלן (עמוד ב), ש\u0003לא נצרכה אלא למקום חתך. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש להסביר: \u0003לא נצרכה\u0004 הלכה זו, \u0003אלא למקום חתך,\u0004 שאם לא החזיר העובר את ידו — נאסר המקום בגוף העובר אליו מחוברת היד, אבל אם החזירה — רק היד עצמה נאסרה, וכדברי רב.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נגד רב ממה ששנינו בברייתא: \u0003בהמה המקשה לילד, הוציא עובר את ידו והחזירה, ואחר כך שחט\u0004 השוחט \u0003את אמו\u0004 — \u0003מותר באכילה. שחט את אמו ואחר כך החזירה\u0004 את ידו — \u0003אסור באכילה.\u0004","\u0003הוציא\u0004 העובר \u0003את ידו וחתכו, ואחר כך שחט את אמו,\u0004 אותו חלק \u0003ש\u0004היה \u0003בחוץ\u0004 ונחתך — \u0003טמא ואסור,\u0004 כדין אבר מן החי, \u0003ו\u0004מה \u0003ש\u0004היה \u0003בפנים\u0004 — \u0003טהור ומותר.\u0004","ואם \u0003שחט את אמו ואחר כך חתכו\u0004 —"],["\u0003הבשר,\u0004 כלומר, כל בשר העובר חוץ מן היד, וכן בשר הבהמה שנשחטה — טמאים בטומאת \u0003מגע נבלה,\u0004 כדין בשר הנוגע בנבילה, שהרי נגעו באבר מן החי, שמטמא כנבילה, אלו \u0003דברי רבי מאיר.\u0004","\u0003וחכמים אומרים:\u0004 למרות שהאבר עצמו אסור באכילה, הועילה שחיטת האם לטהרו מידי נבילה, כשם ששחיטה מועילה לטריפה. ולכן דין בשר העובר ובשר הבהמה — כדין \u0003מגע טריפה שחוטה,\u0004 שמדין תורה היא טהורה, וחכמים גזרו שתטמא בשר קדשים שנגע בה.","\u0003קתני מיהא רישא\u0004 \u0005[הריהו שונה על כל פנים בתחילה]:\u0006 \u0003הוציא עובר את ידו והחזירה ואחר כך שחט את אמו\u0004 — \u0003מותר באכילה; מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר על ה\u0003אבר,\u0004 שהוא מותר כשהחזירו, ושלא כדברי רב? ודוחים: \u0003לא,\u0004 הכוונה ל\u0003עובר.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 על ה\u0003עובר\u0004 מדובר, \u0003אימא סיפא\u0004 \u0005[אמור את סופה,\u0006 המשכה של הברייתא\u0005]:\u0006 \u0003שחט את אמו ואחר כך החזירו\u0004 (את היד) — \u0003אסור באכילה, ואי\u0004 \u0005[ואם]\u0006 הכוונה ל\u0003עובר, אמאי\u0004 \u0005[מדוע]\u0006 הוא עצמו \u0003אסור?\u0004 הרי ניתר בשחיטת אמו!","ומשיבים, \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב נחמן בר יצחק: לא נצרכה\u0004 הלכה זו \u0003אלא ל\u0004אסור בגוף העובר את \u0003מקום\u0004 ה\u0003חתך\u0004 של היד שיצאה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר: \u0003לא נצרכה\u0004 הלכה זו \u0003אלא למקום חתך,\u0004 שאם לא החזיר את היד קודם שחיטה — גם מקום החתך אסור. ומכל מקום היד עצמה אסורה בכל מקרה, גם אם החזירה.","ושואלים: \u0003איני\u0004 \u0005[וכך הוא]?\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003אבימי מבי חוזאי, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא\u0006 זו \u0005בידו]:\u0006 בכתוב שממנו למדנו שעובר ניתר בשחיטת אמו הוזכרו \"פרסה\" ו\"פרסות\", ומשם יש ללמוד כי אם הוציא העובר \u0003פרסה\u0004 (יד) ו\u0003החזיר\u0004 — \u0003אכול,\u0004 וכן אם הוציא \u0003פרסות\u0004 ו\u0003החזיר\u0004 — \u0003אכול. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה: \u0003החזיר פרסה\u0004 — \u0003אכול פרסה,\u0004 החזיר פרסות — אכול פרסות? הרי שהאבר שהחזירו מותר. ושלא כדברי רב!","ודוחים: \u0003לא,\u0004 הכוונה היא: \u0003החזיר פרסה\u0004 — \u0003אכול\u0004 את ה\u0003עובר,\u0004 ולא את הפרסה. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בהיתר אכילה של ה\u0003עובר, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 כש\u0003החזיר\u0004 פרסה? \u0003אפילו לא החזיר נמי\u0004 \u0005[גם כן]\u0006 העובר עצמו מותר! \u0003אמר רב נחמן בר יצחק: לא נצרכה\u0004 הלכה זו \u0003אלא למקום חתך\u0004 (מקום חיבור היד שיצאה לגוף), שאם החזיר את היד — לא נאסר מקום החתך שבגוף העובר, ואם לא החזירו — נאסר מקום החתך.","ומקשים: \u0003והא תרי קראי קא נסיב לה\u0004 \u0005[והרי שני מקראות הוא מביא],\u0006 \"פרסה\" ו\"פרסות\", \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 נאמר \u0003ל\u0004ענין היתר ה\u0003אבר\u0004 שהחזירו, \u0003וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003ל\u0004היתר \u0003מקום חתך?\u0004 ודוחים: \u0003לא, חד\u0004 \u0005[אחד מהם]\u0006 \u0003ל\u0004היתר \u0003מקום חתך, וחד\u0004 \u0005[ואחד מהם]\u0006 לענין אחר, \u0003ל\u0004התיר עובר \u0003קלוט\u0004 (שפרסותיו קלוטות, אינן שסועות) שנמצא \u0003במעי פרה,\u0004 לומר שהוא מותר בשחיטתה.","\u0003ו\u0004הוצרכנו לכך \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 ש\u0003אמר ר' שמעון: קלוט בן פרה אסור,\u0004 מפני שאינו שוסע שסע, שהוא אחד מסימני הטהרה של בהמה, ובא הכתוב לומר: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003יצא לאויר העולם,\u0004 ואז הוא אסור, \u0003אבל במעי אמו\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 כחלק ממנה.","עד כאן דנו בשיטת רב יהודה בשם רב, שאם הוציא עובר אבר ממעי אמו — אותו אבר נאסר, למרות שהחזירו. ובניגוד לכך, \u0003עולא אמר\u0004 בשם \u0003ר' יוחנן: ואבר עצמו מותר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לעולא, והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אבר עצמו אסור! אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003מאן יהיב לן מעפרא\u0004 \u0005[מי יתן לנו מעפרם]\u0006 של \u0003רב ושמואל ומלינן עיינין\u0004 \u0005[ונמלא ממנו את עינינו],\u0006 שאני מכבדם ומעריצם. \u0003אלא\u0004 שאני הולך בשיטת ר' יוחנן, והרי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: הכל,\u0004 כל היוצאים מן המחיצה שבתוכה הם מותרים, \u0003היו בכלל\u0004 הכתוב \u0003\"בשר בשדה טרפה\u0004 \u0003לא תאכלו\"\u0004 (שמות כב, ל), לומר שמשעה שיצאו חוץ ממחיצתם (\"בשדה\") — נאסרו עולמית, ובכלל זה עובר במעי אמו, וכן קדשים שיצאו ממקומם, כגון קדשים קלים שיצאו חוץ לירושלים, וקדשי קדשים שיצאו חוץ לחומת העזרה;","\u0003כש\u0004חזר ו\u0003פרט לך הכתוב\u0004 בפרשת שמיני (ויקרא י, יח) \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חטאת שיצתה\u0004 (שיצאה) \u0003חוץ למחיצתה וחזרה,\u0004 שהיא \u0003אסורה,\u0004 למרות שלא הוצרך לכך, הרי זה בא ללמד: \u0003חטאת הוא דפרט רחמנא בה\u0004 \u0005[שפרטה התורה בה],\u0006 שגם אם חזרה למחיצתה עדיין נשארה באיסורה, \u0003אבל כל מילי\u0004 \u0005[הדברים]\u0006 שיצאו למחיצתם — \u0003כיון דהדור שרי\u0004 \u0005[שחזרו למקומם מותרים],\u0006 ובכלל זה עובר שהוציא את ידו והחזירה, שהיד מותרת.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על דברי ר' יוחנן\u0005]\u0006 ממה ששנינו בברייתא: מה שנאמר \u0003\"בשר בשדה טרפה לא תאכלו\", מה תלמוד לומר?\u0004 אם ללמד על בשר שיצא ממחיצתו (\"שדה\") שהוא אסור, לשם מה נזכרה שם טריפה? אלא \u0003לפי שמצינו במעשר שני ובכורים, שאף על פי שיצאו חוץ למחיצתן,\u0004 חוץ לירושלים, שרק בה הם מותרים באכילה, \u0003ו\u0004למרות זאת, אם \u0003חזרו\u0004 למקומם — \u0003מותרין, יכול אף זה,\u0004 העובר שהוציא ידו ממעי אמו, דינו \u0003כן,\u0004 שאם חזר האבר למחיצתו — מותר? \u0003תלמוד לומר \"טרפה\".\u0004","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה התלמוד],\u0006 כיצד הדברים נלמדים מן הכתוב? \u0003אמר רבה:\u0004 לומר שדינו של בשר שיצא ממחיצתו הוא \u0003כטרפה, מה טרפה,\u0004 \u0003כיון שנטרפה\u0004 — \u0003שוב אין לה היתר, אף בשר, כיון שיצא חוץ למחיצתו\u0004 — \u0003שוב אין לו היתר!\u0004 ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003עולא\u0004 בשם ר' יוחנן. ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו.","ושבים לדון במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003לפי שמצינו במעשר שני ובכורים\u0004 שאם יצאו חוץ למחיצתם, כלומר, חוץ לירושלים, וחזרו — מותרים. ושואלים: \u0003היכן מצינו\u0004 דבר זה?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תוכל לאכול בשעריך מעשר דגנך...\u0004 ותרומת ידך (כלומר, ביכורים) כי אם לפני ה' אלקיך תאכלנו\" \u0003וגו'\u0004 (דברים יב, יז— יח). ולכאורה, די היה לומר \"לפני ה' אלקיך תאכלנו\", אלא ממה שנאמר \"לא תוכל בשעריך\" (כלומר, בכל עריך) אתה למד הדגשה נוספת: \u0003בשעריך הוא דלא תיכול\u0004 \u0005[שלא תאכל]\u0006 מעשר שני וביכורים שיצאו חוץ לירושלים, \u0003אבל\u0004 אם \u0003יצאו חוץ למחיצתן\u0004 (חוץ לירושלים) \u0003וחזרו\u0004 לירושלים — \u0003מותרין.\u0004","ומעירים: בבבל היו שונים את המחלוקת בענין עובר שהוציא את ידו והחזירה, כפי שנאמר לעיל, שרב אמר: ואבר עצמו אסור, ור' יוחנן אמר: ואבר עצמו מותר. \u0003במערבא מתנו הכי\u0004 \u0005[בארץ ישראל היו שונים\u0006 את המחלוקת \u0005כך,\u0006 בלשון אחרת\u0005],\u0006 \u0003רב אמר: יש לידה לאברים,\u0004 שאבר שיצא הריהו כנולד, ואינו ניתר בשחיטת אמו, אפילו אם החזירו. \u0003ור' יוחנן אמר: אין לידה לאברים,\u0004 ולכן אם החזיר את האבר — הריהו מותר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 להלכה בין שתי הלשונות? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 כשיצא רובו של אבר, ולענין \u0003למיסר\u0004 \u0005[לאסור]\u0006 \u0003מיעוט אבר ש\u0004נשאר \u0003בפנים,\u0004 שלפי הלשון הראשונה שאמר רב: אבר עצמו אסור — רק מה שיצא אסור, למרות שהחזירו, אבל מה שנותר בפנים לא נאסר. אבל לפי הלשון \"יש לידה לאיברים\" — כיון שיצא רובו הריהו נחשב כאילו יצא כולו, ובכך נאסר גם המיעוט שבפנים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה בבית המדרש: \u0003לדברי האומר אין לידה לאברים,\u0004 אם \u0003הוציא העובר את ידו והחזירה, וחזר והוציא את ידו\u0004 השניה \u0003והחזירה,\u0004 והוציא אבר אחר והחזירו, \u0003עד שהשלימו לרובו,\u0004 שרובו של העובר יצא וחזר, \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003הא נפק ליה רובא\u0004 \u0005[הרי יצא לו הרוב],\u0006 ואם כן כנולד הוא, ולא תועיל שחיטת אמו להתירו. \u0003או דלמא\u0004 \u0005[או שמא]\u0006 נאמר: \u0003כיון דהדר הדר\u0004 \u0005[כיון שחזר\u0006 — \u0005חזר],\u0006 והותר בשחיטתה?","ו\u0003אם תמצי לומר כיון דהדר הדר\u0004 \u0005[אם תמצא לומר כיון שחזר חזר],\u0006 ואין רואים את הדבר כיציאת רובו, יש לשאול: אם \u0003הוציא עובר את ידו וחתכה\u0004 אדם, \u0003וחזר והוציא את ידו\u0004 האחרת \u0003וחתכה,\u0004 וכן הלאה, \u0003עד שהשלימו לרובו\u0004 של עובר, \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003הא נפיק ליה רובא\u0004 \u0005[הרי יצא לו רובו]\u0006 של העובר, ולא תועיל שחיטת האם למה שנותר ממנו בפנים. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003רובא\u0004 \u0005[רוב]\u0006 שיצא \u0003בבת אחת בעינן\u0004 \u0005[צריכים אנו],\u0006 כדי שייחשב כילוד?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו:"],["\u0003זה הכלל:\u0004 החותך מקרבי הבהמה בחייה \u0003דבר ש\u0004הוא \u0003גופה\u0004 — \u0003אסור,\u0004 ולא תועיל לו שחיטתה, גם אם היה בגופה בשעת השחיטה. \u0003ו\u0004החותך דבר \u0003שאינה גופה,\u0004 אלא מן העובר, אם נשאר בגופה — \u0003מותר\u0004 בשחיטתה. ויש לשאול: דבר \u0003שאין גופה\u0004 שהוא מותר, \u0003לאתויי מאי\u0004 \u0005[להביא את מה]\u0006 הוא בא? \u0003לאו לאתויי כהאי גוונא\u0004 \u0005[האם לא להביא כגון זה],\u0006 שיצא רוב העובר מחותך, ולהתיר מה שנותר בפנים?","ודוחים: \u0003לא,\u0004 יש לומר שבא \u0003לאתויי\u0004 \u0005[להביא]\u0006 עובר \u0003קלוט\u0004 (שפרסותיו אינן שסועות) שנמצא \u0003במעי פרה,\u0004 לומר שהוא מותר בשחיטת אמו. \u0003ו\u0004הוצרך הדבר \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' שמעון.\u0004 לומר, \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אמר ר' שמעון: קלוט בן פרה אסור,\u0004 מפני שאין לו סימני בהמה טהורה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 שכבר \u0003יצא לאויר העולם, אבל במעי אמו\u0004 — \u0003שרי\u0004 \u0005[מותר].\u0006","בענין עובר שהוציא ידו ממעי אמו קודם שחיטה, ששנינו שהיד אסורה משום שיצאה חוץ למחיצתה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חנניא: הוציא עובר\u0004 של בהמת קדשים \u0003את ידו בעזרה\u0004 קודם שנשחטה, \u0003מהו?\u0004 האם נאמר: \u0003מגו דהוי\u0004 \u0005[מתוך ש\u0006העזרה \u0005הריהי]\u0006 \u0003מחיצה לגבי קדשים,\u0004 שהיא מתירה את אמו שנשחטה בתוכה, ולא חוצה לה — \u0003הוי נמי לגבי דהאי\u0004 \u0005[הריהי\u0006 נחשבת מחיצה גם \u0005לגבי\u0006 עובר \u0005זה],\u0006 ואף שהוציא את ידו בעזרה — אינה נחשבת כיוצאת מחוץ למחיצתה, והותרה בשחיטת אמו. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003לגבי דהאי\u0004 \u0005[לגבי\u0006 עובר \u0005זה]\u0006 העזרה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מחיצה היא,\u0004 מפני ש\u0003מחיצת עובר\u0004 — \u0003אמו היא,\u0004 ואם יצא אבר ממנה — יצא ממחיצתו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ותבעי לך\u0004 \u0005[ותישאל לך]\u0006 שאלה זו לגבי בהמת \u0003קדשים קלים בירושלים,\u0004 שהוציא העובר את ידו ממעיה: האם ירושלים, שרק בין חומותיה מותר לאכול קדשים קלים, נחשבת כמחיצה לגביו, ולא נאסרה ידו, או שמא מאחר שיצאה ממעי אמו הריהי נחשבת כיוצא חוץ למחיצה? אלא \u0003קדשים קלים בירושלים מאי טעמא לא קא מיבעיא לך\u0004 \u0005[מה טעם לא נשאלה לך]\u0006 — משום שאתה מניח ש\u0003מחיצת עובר\u0004 — \u0003אמו הוא, הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כשהוציא ידו בעזרה, אמור: \u0003מחיצת עובר אמו הוא,\u0004 ולא העזרה.","בברייתא שהובאה לעיל (סא,ב) שנינו שעובר שהוציא ידו ממעי אמו, אף ששחיטת האם אינה מתירה את היד באכילה, מכל מקום היא מטהרת אותו מטומאת נבילה. ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אילפא:\u0004 אם \u0003הוציא עובר את ידו בין\u0004 שחיטת \u0003סימן לסימן,\u0004 בין שחיטת הקנה לשחיטת הוושט, קודם שנגמרה השחיטה, \u0003מהו?\u0004","\u0003מי\u0004 \u0005[האם]\u0006 \u0003מצטרף סימן ראשון לסימן שני לטהריה\u0004 \u0005[לטהר אותו,\u0006 את היד שיצאה\u0005]\u0006 \u0003מידי\u0004 טומאת \u0003נבלה, או לא?\u0004 שהרי כששחטו את הסימן הראשון, מתירה השחיטה את האבר באכילה וגם מטהרת אותו מטומאת נבילה, כחלק מן העובר. אבל שחיטת הסימן השני באה רק לטהרו מטומאת נבילה, שהרי נאסר באכילה, ושמא אינן מצטרפות לשחיטה אחת לטהרו? \u0003אמר רבא: קל וחומר, אם הועיל לו\u0004 ה\u0003סימן ראשון לסימן\u0004 ה\u0003שני להתירו באכילה\u0004 את העובר כולו, \u0003לא יועיל לו\u0004 לאבר שיצא \u0003לטהריה\u0004 \u0005[לטהר אותו]\u0006 על כל פנים \u0003מידי\u0004 טומאת \u0003נבלה?\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 עובר שהוציא את ידו ממעי אמו, ונשחטה האם, ששנינו שאף שהעובר עצמו הותר בשחיטתה, אותה יד נאסרה לעולם משום בשר שיצא ממחיצתו, \u0003מהו לחוש\u0004 (לחשוש) \u0003ל\u0004איסור של אותה יד ב\u0003זרעו\u0004 של אותו עובר, שהוליד לאחר שהוציאוהו ממעי אמו וגדל?","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דאזל אבהמה מעלייתא\u0004 \u0005[אם תאמר שהלך,\u0006 בא, \u0005על בהמה מעולה,\u0006 רגילה\u0005],\u0006 וילדה, \u0003מאי איריא האי דאית ביה\u0004 \u0005[מה שייך,\u0006 מדוע לשאול על \u0005זה שיש בו]\u0006 \u0003איסור יוצא\u0004 ממחיצתו?","\u0003אפילו בן פקועה דעלמא\u0004 \u0005[סתם],\u0006 כל עובר שהוציאוהו ממעי אמו שנשחטה — \u0003נמי\u0004 \u0005[גם כן]\u0006 יש איסור בזרעו. שכך \u0003אמר רב משרשיא, לדברי האומר: חוששין\u0004 בבהמה \u0003לזרע האב,\u0004 שמייחסים את הבן לאב ולא רק לאם, \u0003בן פקועה\u0004 (שלאחר שנשחטה אמו פקעו את בטנה והוציאוהו ממעיה) \u0003הבא על בהמה מעלייתא\u0004 \u0005[מעולה,\u0006 רגילה\u0005]\u0006 — \u0003הולד אין לו תקנה,\u0004 שכיון שמצד האב אינו טעון שחיטה, ומצד אמו טעון שחיטה — לא תועיל שחיטה להכשירו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 שאלה זו אלא במקרה \u0003דאזל\u0004 \u0005[שהלך,\u0006 בא\u0005]\u0006 אותו בן פקועה שהוציא את ידו קודם שחיטה, על נקבה שהיא \u0003בן פקועה דכוותיה\u0004 \u0005[שכיוצא בו],\u0006 שגם היא אינה טעונה שחיטה, וילדה, איפוא, ולד שאינו טעון שחיטה, אלא שהוא בא מכוחו של אב שידו נאסרה משום יוצא. והשאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם כל \u0003אבר\u0004 של האב \u0003מוליד\u0004 את ה\u0003אבר\u0004 המקביל לו בוולד, \u0003ו\u0004אם כן \u0003חתיך ליה ושרי\u0004 \u0005[חותך את\u0006 היד של הוולד \u0005ו\u0006הוולד כולו \u0005מותר].\u0006 \u0003או דלמא מבלבל זרעיה\u0004 \u0005[או שמא מבולבל\u0006 מפוזר \u0005זרעו]\u0006 בוולד כולו, וכולו אסור?","לאחר ששאל שאלה זו \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 ר' ירמיה: \u0003פשיטא דמבלבל זרעיה\u0004 \u0005[פשוט\u0006 הדבר \u0005שמתבלבל זרעו],\u0006 ש\u0003אם כן,\u0004 שכל אבר מוליד אבר מקביל לו, הרי כל אב \u0003סומא\u0004 היה \u0003יולד סומא, וקיטע\u0004 (שידו קטועה) היה \u0003יולד קיטע!\u0004","\u0003אלא פשיטא דמבלבל זרעיה\u0004 \u0005[פשוט\u0006 הדבר \u0005שמתבלבל זרעו],\u0006 \u0003והכי קמיבעיא לן\u0004 \u0005[וכך נשאלה לנו]\u0006 השאלה: \u0003בהמה בעלמא\u0004 \u0005[סתם],\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מכח חלב ודם\u0004 של האב והאם \u0003קאתיא\u0004 \u0005[היא באה],\u0006 שהם מצד עצמם אסורים, \u0003ו\u0004בכל זאת \u0003שריא\u0004 \u0005[\u0006היא \u0005מותרת]?\u0006 ואם כן, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן,\u0006 באיסור בשר שיצא ממחיצתו, \u0005אינו שונה],\u0006 ולמרות שיש באב איסור מחמת היד שהוציא ממעי אמו — הולד שבא מכוחו מותר. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003תרי איסורי אמרינן\u0004 \u0005[\u0006ב\u0005שני איסורים\u0006 שהולד בא מכוחם, חלב ודם, \u0005אנו אומרים]\u0006 שהתורה התירה, אבל \u0003תלתא לא אמרינן\u0004 \u0005[\u0006ב\u0005שלושה\u0006 איסורים, חלב ודם ואיסור יוצא, \u0005אין אנו אומרים]?\u0006","ומקשים: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]\u0006 יש כאן שלושה איסורים? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר\u0004 — \u0003איסור חלב ודם איכא\u0004 \u0005[יש],\u0006 באב שהוציא ידו ממעי אמו, אבל \u0003איסור יוצא ליכא\u0004 \u0005[אין\u0006 בו\u0005]\u0006 כלל.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 — \u0003איסור יוצא איכא\u0004 \u0005[יש\u0006 בו\u0005],\u0006 אבל \u0003איסור חלב (ודם) ליכא\u0004 \u0005[אין\u0006 בו\u0005]!\u0006 ומנין שכך סבור כל אחד מהם?","\u0003דתנן\u0004 \u0005[ששנינו]:\u0006 איסור \u0003גיד הנשה נוהג בשליל\u0004 (עובר) שכלו חדשי עיבורו, ונמצא חי במעי בהמה שנשחטה, \u0003ו\u0004כן \u0003חלבו אסור,\u0004 אלו \u0003דברי ר' מאיר.\u0004 שהוא סבור שדינו של עובר זה ככל בהמה, ולשיטתו גם אינו ניתר בשחיטת אמו (להלן פט,א). וכיון שאינה נחשבת לגביו מחיצה מתרת, ממילא, אם הוציא את ידו קודם שחיטת אמו — אינה נאסרת משום בשר שיצא חוץ למחיצתו. \u0003ר' יהודה אומר: אין\u0004 איסור גיד הנשה \u0003נוהג בשליל\u0004 כזה, \u0003וחלבו מותר.\u0004 שהוא סבור שהעובר אינו נחשב בהמה לעצמה, להחיל עליו איסורים אלה, אלא הוא חלק מאמו. אך מטעם זה עצמו שחיטת אמו מתירה אותו, ולכן אם הוציא את ידו ממעיה קודם שחיטה — נאסרה היד משום בשר שיצא ממחיצתו. ונמצא שלכל הדעות, ולד לאב שהוציא ידו ממעי אמו, בא מכח שני איסורים לכל היותר, ככל בהמה!","\u0003אלא,\u0004 צריך אתה לומר, ש\u0003כל\u0004 שבא \u0003מכח\u0004 איסור — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שהוא אסור משום כך, אלא אומרים אנו \u0003דשרי\u0004 \u0005[שהוא מותר],\u0006 ואם כן זרעו של עובר שהוציא ידו ממעי אמו בוודאי מותר, ולא בכך נסתפק ר' ירמיה.","\u0003ו\u0004אלא \u0003הכי קמיבעיא לן\u0004 \u0005[כך נשאלה לנו],\u0006 כך יש להסביר את שאלת ר' ירמיה: אם היה זה עובר נקבה שהוציא ידו ממעי אמו, \u0003מהו לגמוע את חלבו?\u0004 האם נאמר: \u0003חלב דעלמא\u0004 \u0005[של סתם\u0006 בהמות\u0005],\u0006 האם \u0003לא כאבר מן החי דמי\u0004 \u0005[הוא נחשב],\u0006 שהרי הוא פורש מגוף החי, \u0003ו\u0004למרות זאת \u0003שרי\u0004 \u0005[הוא מותר]?\u0006 אם כן, \u0003האי נמי לא שנא\u0004 \u0005[\u0006חלב \u0005זה גם כן אינו שונה],\u0006 ולמרות שיש בבהמה איסור בשר שיצא ממחיצתו — אין החלב שלה אסור.","\u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003התם\u0004 \u0005[שם],\u0006 סתם חלב התירה התורה, שכן \u0003אית ליה תקנתא לאיסוריה\u0004 \u0005[יש לו תקנה לאיסורו]\u0006 לאיסור אבר מן החי — \u0003בשחיטה,\u0004 שמוציאה את הבהמה כולה מאיסור אבר מן החי. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 באיסור יוצא שיש בחלב של עובר שהוציא ידו — \u0003לית ליה תקנתא לאיסוריה\u0004 \u0005[אין לו תקנה לאיסורו]\u0006 \u0003בשחיטה?\u0004 שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: ה\u0003חותך מעובר\u0004 שבמעי בהמה קודם שחיטה, ולא הוציא את חתיכות העובר ממעיה — מה שחתך מותר באכילה לאחר שחיטת האם. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל בהמה מפרסת פרסה\u0004 ושוסעת שסע פרסות בבהמה אותה תאכלו\" (דברים יד, ו), ומה שנאמר בפסוק זה \u0003\"בהמה... בבהמה\"\u0004 הרי זה \u0003לרבות את הולד,\u0004 שהוא כבהמה המצויה בתוך בהמה.","ומקשים: \u0003אלא מעתה,\u0004 שאתה למד כן מן הביטוי \"בהמה בבהמה\", אם כן גם בדין תמורה שנאמר בו ביטוי זה: \"ואם המר ימיר בהמה בבהמה, והיה הוא ותמורתו יהיה קודש\" (ויקרא כז, י) — \u0003ימירו בו\u0004 בעובר, שאם יאמר על בהמת חולין, שהיא תמורת עובר שבמעי בהמת קדשים — תחול עליה הקדושה!","\u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין ממירין לא אברין בעוברין,\u0004 שאם אמר על אבר של בהמת חולין שיהיה תמורת עובר של בהמת קדשים — אין הקדושה חלה על האבר, \u0003ו\u0004כן \u0003לא\u0004 ממירין \u0003עוברין\u0004 של בהמות חולין \u0003באברין\u0004 של קדשים. \u0003ו\u0004כן \u0003לא\u0004 ממירים \u0003אברין ועוברין\u0004 של חולין \u0003בשלמין,\u0004 בבהמות קדשים שלמות, \u0003ו\u0004גם \u0003לא\u0004 ממירים בעלי חיים \u0003שלמין\u0004 של חולין \u0003בהן,\u0004 באברים ועוברים של בהמות קדשים!","\u0003אלא\u0004 לא מ\"בהמה בבהמה\" למדים להתיר עובר שבמעי בהמה, אלא ממה ש\u0003אמר\u0004 שם \u0003קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכל בהמה...\u0004 בבהמה תאכלו\", שלשון \"כל\" באה \u0003לרבות את\u0004 כל מה שבבהמה, ובכלל זה \u0003הולד,\u0004 שהוא מותר כחלק מגופה של הבהמה שהותר בשחיטה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכל מה שבבהמה תאכלו, \u0003אפילו חותך מן הטחול ומן הכליות\u0004 שבמעיה \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיה מותר! \u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חותך מן העובר שבמעיה\u0004 — \u0003מותר באכילה,\u0004 חותך \u0003מן הטחול ומן הכליות\u0004 — \u0003אסור באכילה?\u0004 ומשיבים, \u0003אמר\u0004 שם \u0003קרא\u0004 \u0005[הכתוב]:\u0006 \"בבהמה \u0003אותה\u0004 תאכלו\" — אותה כשהיא \u0003שלמה ולא חסרה,\u0004 שאם נחסר דבר ממנה עצמה לא תאכלנו, שלא הותר בשחיטתה.","ומקשים: \u0003אלא מעתה,\u0004 שאתה מתיר עובר שלם שבתוכה מ\"כל בבהמה\", \u0003השוחט את הבהמה ומצא בה\u0004 עובר ב\u0003דמות יונה\u0004 — \u0003תשתרי\u0004 \u0005[תהיה מותרת]\u0006 אותה דמות יונה באכילה! \u0003אלמה\u0004 \u0005[משום מה]\u0006 \u0003אמר רבי יוחנן: השוחט את הבהמה ומצא בה דמות יונה\u0004 — \u0003אסור באכילה?\u0004"],["ומשיבים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003פרסות,\u0004 כפי שנאמר שם \"וכל בהמה וכו' ושוסעת שסע שתי פרסות ומעלת גרה בבהמה אותה תאכלו\" (דברים יד, ו), \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","ושואלים: \u0003אלא מעתה,\u0004 שצריך שיהיו לו פרסות, עובר \u0003קלוט\u0004 (שפרסותיו אינן שסועות לשתיים) שנמצא \u0003במעי פרה ליתסר\u0004 \u0005[שייאסר]!\u0006 ומשיבים: \u0003הא תנא דבי\u0004 \u0005[הרי שנה החכם בבית מדרשו]\u0006 של \u0003ר' ישמעאל כ\u0004שיטת \u0003ר' שמעון בן יוחי:\u0004 מה שנאמר שם \u0003\"פרסה... בבהמה\u0004 אותה \u0003תאכלו\"\u0004 (שם), מלמד שעובר הנמצא במעי בהמה, שיש לו פרסה אחת, שאינה שסועה לשתים — מותר באכילה.","\u0003רב שימי בר אשי אמר: לעולם\u0004 יש להסביר \u0003כדקאמרת מעיקרא\u0004 \u0005[כמו שאמרת מתחילה],\u0006 שעובר הנמצא במעי פרה מותר מן הביטוי \"בהמה... בבהמה אותה תאכלו\" (שם), שעובר קרוי \"בהמה בבהמה\". \u0003ודקא קשיא לך\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך]\u0006 לדרך זו, ממה ששנינו במשנה בתמורה: \u0003אין ממירין\u0004 בעוברים, שאין דין תמורה בעוברים, למרות שגם שם נאמר \"בהמה בבהמה\" (ויקרא כז, י), על כך יש להשיב כי \u0003הא מני\u0004 \u0005[זו,\u0006 אותה משנה, \u0005כשיטת מי היא]?\u0006 שיטת \u0003רבי שמעון היא,\u0004 ש\u0003מקיש\u0004 (משוה) במקום אחר \u0003תמורה למעשר\u0004 בהמה, לומר שדין תמורה שייך רק בדברים שנוהג בהם מעשר בהמה, ולשיטתו יש לומר גם: \u0003מה מעשר אינו נוהג באברים ועוברים,\u0004 אלא רק בבעלי חיים שיכולים ללכת, שנאמר: \"כל אשר יעבור תחת השבט\" (ויקרא כז, לב) — \u0003אף תמורה אינה נוהגת באברים ועוברים.\u0004","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר]\u0006 שמשנה זו, שיטת ר' שמעון היא? \u0003דתנן\u0004 \u0005[ששנינו]\u0006 באותה משנה, \u0003אמר ר' יוסי: והלא במוקדשים,\u0004 כלומר, כשמקדיש בדרך רגילה, \u0003האומר: \"רגלה של\u0004 בהמה \u0003זו עולה\"\u0004 — הרי \u0003כולה\u0004 נעשית \u0003עולה.\u0004 ואם כן, \u0003אף\u0004 בתמורה, \u0003כשיאמר:\u0004 \u0003\"רגל של\u0004 בהמה \u0003זו תחת\u0004 בהמה \u0003זו\"\u0004 — \u0003תהא\u0004 הבהמה \u0003כולה,\u0004 ולא רק הרגל, \u0003תמורה תחתיה.\u0004 ומדברים אלו משמע שגם התנא שר' יוסי חולק עליו מסכים עמו בהנחה הבסיסית, שבמוקדשים, כשאומר \"רגלה של זו עולה\" — כולה עולה.","ויש לשאול: \u0003למאן קא מהדר ליה\u0004 \u0005[למי הוא משיב]\u0006 דברים אלו? כלומר, מי הוא התנא של המשנה, שעמו הוא דן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לר' מאיר ור' יהודה, מי אית להו האי סברא\u0004 \u0005[האם יש להם,\u0006 מקבלים הם \u0005סברה זו]\u0006 במוקדשים? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול האומר \"רגלה של זו עולה\"\u0004 — \u0003תהא כולה עולה? תלמוד לומר:\u0004 \"ואם בהמה אשר יקריבו ממנה לה' \u0003כל אשר יתן ממנו לה' יהיה קדש\"\u0004 (ויקרא כז, ט), ומכאן יש לדייק: מה שיתן \u0003ממנו\u0004 יהיה \u0003קדש\u0004 — \u0003ולא כולו\u0004 יהיה \u0003קדש.\u0004","\u0003יכול\u0004 יפדה אותו אבר שהוקדש, וכך \u0003תצא\u0004 בהמה זו כולה \u0003לחולין? תלמוד לומר: \"יהיה\u0004 קדש\" — \u0003בהוייתה תהא,\u0004 שאותו אבר ישאר בקדושתו. \u0003הא כיצד\u0004 יש לנהוג? \u0003תמכר\u0004 הבהמה \u0003לצרכי עולות,\u0004 לאנשים שצריכים להקריב קרבן עולה, והם יקדישו אותה כולה לעולה, \u0003ודמיה\u0004 שקיבל תמורתה יהיו \u0003חולין, חוץ מדמי\u0004 אותו \u0003אבר שבה\u0004 שהקדיש, אלו \u0003דברי ר' מאיר ור' יהודה.\u0004","\u0003ר' יוסי ור' שמעון אומרים: מנין לאומר \"רגלה של זו עולה\"\u0004 — \u0003תהא כולה עולה? תלמוד לומר: \"יהיה\u0004 קדש\" — \u0003לרבות את כולה.\u0004 ואם כן, \u0003למאן\u0004 \u0005[למי]\u0006 משיב ר' יוסי, שכשם שאם הקדיש אבר אחד חלה הקדושה על הבהמה כולה, כך אם המיר אבר של בהמת חולין בבהמת קדשים תהא בהמת החולין כולה תמורה?","\u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא משיב \u0003לר' מאיר ור' יהודה\u0004 — \u0003מי אית להו האי סברא\u0004 \u0005[האם יש להם סברה זו]\u0006 במוקדשים? והרי לשיטתם אין הקדושה חלה על כולה! \u0003אלא לאו\u0004 \u0005[האם אינו]\u0006 משיב \u0003לר' שמעון\u0004 הסבור כן? ונמצא שר' שמעון הוא התנא של אותה משנה.","ודוחים: \u0003לא,\u0004 יש לומר שהתנא של אותה משנה הוא ר' מאיר או ר' יהודה. ומה שטען ר' יוסי: והלא במוקדשים האומר \"רגלה של זו עולה\" — כולה עולה, אין זה משום שכך סבור גם התנא הראשון, אלא \u0003ר' יוסי טעמא דנפשיה קאמר\u0004 \u0005[את הטעם של עצמו הוא אומר],\u0006 לשיטתו שלו, ואין מכאן ראיה לענייננו.","בהמה \u0003המבכרת\u0004 (העומדת ללדת את ולדה הראשון), \u0003המקשה לילד,\u0004 ובעליה רוצה שלא תמות — \u0003מחתך אבר אבר\u0004 מהעובר שבמעיה, \u0003ומשליך לכלבים,\u0004 ואינו צריך לקבור כל אבר שחתך, כדין קדשים שאסורים בהנאה, לפי שאין הבכור קדוש בבכורה עד שיצא רובו מן הרחם. ואם \u0003יצא רובו\u0004 של הוולד כאחד, וחתכו — \u0003הרי זה יקבר,\u0004 משום שביציאת רובו חלה עליו קדושת הבכורה. \u0003ו\u0004האם \u0003נפטרת מן הבכורה,\u0004 שהוולד הבא שייוולד לה אינו בכור.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים במקרה זה: \u0003יצא שליש\u0004 העובר חוץ לרחם אמו, \u0003ומכרו\u0004 את השליש הזה \u0003לגוי, וחזר ויצא שליש אחר,\u0004 ובכך יצא רובו — \u0003רב הונא אמר:\u0004 ולד זה \u0003קדוש\u0004 בבכורה, \u0003רבה אמר: אינו קדוש.\u0004","ומסבירים את טעמיהם: \u0003רב הונא\u0004 ש\u0003אמר קדוש, קסבר\u0004 \u0005[סבור הוא]:\u0006 בכור שמתקדש כשיצא רובו — \u0003למפרע\u0004 הוא \u0003קדוש, וכיון דנפק ליה רוביה\u0004 \u0005[שיצא לו רובו]\u0006 — \u0003איגלאי מילתא למפרע דמעיקרא הוה\u0004 \u0005[התגלה הדבר למפרע שמתחילה היה]\u0006 \u0003קדוש, ו\u0004לפיכך \u0003מאי דזבין\u0004 \u0005[מה שמכר]\u0006 לגוי — \u0003לא כלום זבין\u0004 \u0005[מכר],\u0006 שאינו יכול למכור דבר שאינו שלו.","ואילו \u0003רבה\u0004 ש\u0003אמר אינו קדוש, קסבר\u0004 \u0005[סבור הוא]:\u0006 בכור \u0003מכאן ולהבא\u0004 הוא \u0003קדוש,\u0004 רק משעה שיצא רובו, \u0003ו\u0004לפיכך, \u0003מאי דזבין\u0004 — \u0003שפיר זבין\u0004 \u0005[מה שמכר\u0006 לגוי מתחילה — \u0005יפה מכר],\u0006 ונמצא שוולד זה פטור מבכורה, מפני החלק שנמכר לגוי.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 רב הונא ורבה \u0005לשיטותיהם].\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בשאלה זו: אם \u0003יצא שליש\u0004 מן הבכור \u0003דרך דופן\u0004 הרחם, בניתוח, \u0003ו\u0004אחר כך יצאו שאר \u0003שני שלישי\u0004 העובר \u0003דרך\u0004 פתח \u0003רחם\u0004 — \u0003רב הונא אמר: אינו קדוש\u0004 בבכורה, \u0003רבה אמר: קדוש.\u0004","ומסבירים: \u0003רב הונא אמר: אינו קדוש\u0004 — \u0003רב הונא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר:\u0004 בכור \u0003למפרע\u0004 הוא \u0003קדוש,\u0004 שלאחר שיצא רובו מתברר כי כשנולד נתקדש. \u0003ו\u0004אולם במקרה זה \u0003רובא קמא ליתיה\u0004 \u0005[הרוב הראשון לא היה בלידה]\u0006 \u0003ב\u0004דרך ה\u0003רחם,\u0004 והרי בכור שיצא שלא דרך פתח הרחם אינו קדוש בבכורה. ואילו \u0003רבה אמר: קדוש\u0004 — \u0003רבה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר:\u0004 בכור \u0003מכאן ולהבא קדוש,\u0004 משייוולד רובו. \u0003ו\u0004הרי במקרה זה, כשיצא \u0003רובא\u0004 \u0005[הרוב]\u0006 — \u0003דרך\u0004 פתח ה\u0003רחם נפיק\u0004 \u0005[יצא].\u0006","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 המחלוקת להיאמר בשני המקרים. \u0003דאי אשמעינן בהא\u0004 \u0005[שאם היה משמיע לנו רק בזו],\u0006 שיצא שליש ומכרהו לגוי, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב הונא\u0004 שלמפרע הוא קדוש, \u0003משום\u0004 שאם היינו אומרים מכאן ולהבא הוא קדוש, נמצא \u0003דלקולא\u0004 \u0005[שהוא מקל],\u0006 שהוא פוטרו מן הבכורה. \u0003אבל בהך\u0004 \u0005[בזו],\u0006 שיצא שליש דרך דופן, \u0003דלחומרא\u0004 \u0005[ש\u0006הוא \u0005להחמיר],\u0006 שאם נאמר כדברי רבה, שמכאן ולהבא הוא קדוש, הריהו מחייבו בבכורה — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה\u0006 הוא \u0005לו]\u0006 רב הונא \u0003לרבה.\u0004"],["\u0003ואי אתמר בהא\u0004 \u0005[ואילו היה נאמר בזו],\u0006 כשיצא שליש דרך דופן ושני שליש דרך רחם, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רבה\u0004 שהוא קדוש מכאן ולהבא, מפני שהוא לחומרה, שהוא מחייבו בבכורה. \u0003אבל בהא\u0004 \u0005[בזו],\u0006 שיצא שליש ומכרו לגוי, וחזר ויצא שליש, שאם נאמר שמכאן להבא הוא קדוש הרי זו קולה, שנפטר מן הבכורה \u0005—\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לרב הונא,\u0004 שלמפרע הוא קדוש, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים. ומקשים על דברי רב הונא.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המבכרת המקשה לילד\u0004 — \u0003מחתך אבר אבר ומשליך לכלבים.\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה היא ש\u0003מחתך\u0004 אבר אבר \u0003ומניח,\u0004 ואחר כך משליך לכלבים כל מה שחתך? \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 שבכור \u0003למפרע הוא קדוש,\u0004 שכשיצא רובו מתברר כי כבר מתחילה היה קדוש, הלוא \u0003יקבר מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שאת כל מה שחתך יצטרך לקבור, כדין קדשים שאי אפשר להקריבם!","ודוחים: \u0003לא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003במחתך ומשליך\u0004 מיד לכלבים כל אבר שהוא חותך, שבשעה שהוא עושה כן עדיין אינו קדוש.","ומקשים: \u0003אבל מחתך ומניח, מאי\u0004 \u0005[מה]\u0006 דינו, \u0003יקבר?\u0004 אם כן \u0003אדתנא סיפא\u0004 \u0005[עד ש\u0006הוא מוסיף ו\u0005שונה בסוף]:\u0006 \u0003יצא רובו\u0004 בבת אחת — \u0003יקבר, ונפטרה מן הבכורה\u0004 — \u0003ליפלוג וליתני בדידיה\u0004 \u0005[שיחלק וישנה\u0006 בדין הראשון \u0005בעצמו]:\u0006 \u0003במה דברים אמורים\u0004 שמשליך לכלבים? \u0003במחתך ומשליך אבר אבר, אבל מחתך ומניח\u0004 — \u0003יקבר\u0004 כל מה שחתך!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן הוא אומר],\u0006 כלומר, כך אכן צריך להבין את הדברים: \u0003במה דברים אמורים\u0004 שמחתך אבר אבר ומשליך לכלבים? \u0003במחתך ומשליך, אבל מחתך ומניח\u0004 — \u0003נעשה כמי שיצא רובו\u0004 כאחת, \u0003ויקבר.\u0004","בענין ששנינו במשנתנו שאם יצא ראשו של עובר מבכרת — הרי זה קדוש בבכורה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 האם \u0003הלכו באיברין אחר הרוב, או לא הלכו באיברין אחר הרוב?\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כגון שיצא רוב\u0004 העובר \u0003במיעוט אבר,\u0004 שיצא כמחצית מגוף העובר, ועוד אחד מן האברים יצא במיעוטו, ואותו מיעוט משלים לרובו של העובר, \u0003וקא מיבעיא ליה\u0004 \u0005[ונשאלה לו]\u0006 לרבא: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003מיעוט\u0004 אבר \u0003דבראי\u0004 \u0005[שבחוץ],\u0006 האם \u0003בתר רוב דאבר שדינן ליה\u0004 \u0005[\u0006\u0005אחר רוב האבר\u0006 שנשאר בפנים \u0005אנו משליכים אותו],\u0006 וכאילו לא יצא, ואם כן לא יצא רובו של העובר, \u0003או\u0004 שמא \u0003בתר רובא דעובר שדינן ליה\u0004 \u0005[\u0006\u0005אחר רוב העובר אנו משליכים אותו]\u0006 — הרי","\u0003פשיטא דלא שבקינן רובא דעובר ואזלינן בתר רוב אבר\u0004 \u0005[פשוט\u0006 הדבר \u0005שאין אנו מניחים את רוב העובר והולכים אחר רוב האבר]!\u0006","\u0003אלא\u0004 מדובר \u0003כגון שיצא חציו\u0004 של העובר \u0003ברוב אבר,\u0004 שיצא כמעט חציו של העובר, ועוד אחד מן האברים יצא ברובו, ורוב האבר שיצא משלים לחציו של העובר, \u0003וקא מיבעיא ליה\u0004 \u0005[ונשאלה לו]\u0006 לרבא: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003מיעוט\u0004 אבר \u0003דבגואי\u0004 \u0005[ש\u0006נשאר \u0005בפנים],\u0006 \u0003מהו למישדייה בתר\u0004 \u0005[להשליך אותו אחר]\u0006 \u0003רוב\u0004 ה\u0003אבר,\u0004 ולהחשיבו כאילו גם הוא יצא?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003יצא רובו\u0004 — \u0003הרי זה יקבר.\u0004 ויש לברר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003רובו? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003רובו\u0004 של העובר \u0003ממש,\u0004 וכי \u0003עד השתא לא אשמעינן\u0004 \u0005[עד עכשיו לא השמיע לנו]\u0006 התנא דין \u0003רובו ככולו?\u0004 הרי כלל ידוע הוא, ואין חידוש בדבר!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003כגון שיצא חציו ברוב אבר?\u0004 ומכאן יש ללמוד שמיעוט האבר שבפנים מצטרף לרוב האבר שבחוץ, וכאילו יצא רובו של העובר!","ודוחים: \u0003לא,\u0004 אפשר לפרש שמדובר במשנה \u0003כגון שיצא רובו\u0004 של העובר \u0003במיעוט אבר, וקא משמע לן\u0004 \u0005[ומשמיע לנו]:\u0006 \u0003דלא שבקינן\u0004 \u0005[שאין אנו מניחים]\u0006 \u0003רובו\u0004 של \u0003עובר\u0004 של \u0003בהמה, ואזלינן בתר\u0004 \u0005[והולכים אחר]\u0006 רוב \u0003אבר.\u0004","ועוד בענין האופן המדוייק שבו חלה קדושה על הבכור, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 הואיל ופתח הרחם הוא המקדש את הבכור כשהוא יוצא דרכו, שנאמר \"פטר רחם\" (שמות יג, יד ועוד), אם \u0003כרכו\u0004 את העובר \u0003בסיב\u0004 בעודו ברחם וכך הוציאוהו, וכך כשנולד לא נגע בפתח הרחם, \u0003מהו\u0004 הדין? האם מהווה הדבר חציצה? וכן אם עטף אותו \u0003בטליתו\u0004 והוציאו \u0003מהו?\u0004","וכן אם יצא כשהוא עטוף \u0003בשליתו\u0004 (השק שבו הוא נתון) \u0003מהו?\u0004 על הדבר האחרון תוהים: \u0003בשליתו? אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא,\u0004 הרי כך הוא נולד כרגיל! \u0003אלא\u0004 כך שאל: אם יצא כשהוא עטוף \u0003בשליא אחרת,\u0004 של עובר אחר, \u0003מהו?\u0004","אם \u0003כרכתו\u0004 אשה בידיה \u0003ואחזתו והוציאתו\u0004 כך שלא נגע בפתח הרחם, \u0003מהו\u0004 הדין? ומבררים: \u0003היכי דמי\u0004 \u0005[איך בדיוק מדובר]\u0006 בכל המקרים הללו? \u0003אי דנפק דרך רישיה\u0004 \u0005[אם שיצא דרך ראשו,\u0006 שראשו יצא תחילה\u0005],\u0006 ואחר כך עטפוהו — הלוא כבר \u0003פטרתיה\u0004 \u0005[פטרה אותו],\u0006 כלומר, הרי זה פטר רחם, שמשעה שיצא ראשו הריהו כיילוד אף שלא יצא רובו, וכבר נתקדש בבכורה! \u0003אלא\u0004 צריך לומר \u0003דנפק\u0004 \u0005[שיצא]\u0006 \u0003דרך מרגלותיו\u0004 (רגליו האחוריות), וקודם שיצא רובו עטפוהו.","ועוד שאל רבא: אם \u0003בלעתהו חולדה\u0004 את העובר בתוך הרחם, \u0003והוציאתו\u0004 מן הרחם כשהוא במעיה, \u0003מהו?\u0004 ותוהים: \u0003הוציאתו? הא אפיקתיה\u0004 \u0005[הרי הוציאה אותו]\u0006 במעיה, ובוודאי אין זה פטר רחם! \u0003אלא\u0004 הכוונה היא: \u0003בלעתו והוציאתו,\u0004 וחזרה \u0003והכניסתו והקיאתו\u0004 ברחם, \u0003ו\u0004אחר כך \u0003יצא מאליו, מהו\u0004 דינו? האם נתקדש בבכורה בלידה זו?","ועוד, אם \u0003הדביק שני רחמים\u0004 של שתי מבכירות, \u0003ויצא\u0004 עובר \u0003מ\u0004רחם \u0003זה ונכנס לזה,\u0004 ולאחר מכן יצא דרך פתח הרחם השני \u0003מהו?\u0004 האם נפטרה השניה מן הבכורה? וצדדי השאלה: האם הוולד \u0003דידיה פטר\u0004 \u0005[\u0006רחם \u0005שלו,\u0006 שהוא גדל בו, \u0005הוא פוטר],\u0006 \u0003דלאו דידיה לא פטר\u0004 \u0005[\u0006רחם \u0005שאינו שלו אינו פוטר].\u0006 \u0003או דלמא דלאו דידיה נמי פטר\u0004 \u0005[שמא\u0006 רחם \u0005שאינו שלו\u0006 הוא \u0005גם כן פוטר]?\u0006 לכל השאלות הללו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחא: נפתחו\u0004 ונתרחבו \u0003כותלי בית הרחם\u0004 עד שבשעת הלידה אין העובר נוגע בהם, \u0003מהו?\u0004 האם אנו אומרים ש\u0003אויר,\u0004 חלל פתח ה\u0003רחם מקדיש\u0004 \u0005[מקדש],\u0006 \u0003והאיכא\u0004 \u0005[והרי יש כאן],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003נגיעת\u0004 פתח ה\u0003רחם מקדשה\u0004 \u0005[\u0006היא ה\u0005מקדשת],\u0006 \u0003והא ליכא\u0004 \u0005[והרי אין כאן]?\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003מר בר רב אשי: נעקרו כותלי בית הרחם, מהו?\u0004 ותוהים: האם במקרה שכבר \u0003נעקרו\u0004 קודם הלידה אתה שואל? הלא במקרה זה \u0003ליתנהו\u0004 \u0005[אינם],\u0006 ואין כאן פתח רחם שמקדש בבכור! \u0003אלא\u0004 הכוונה היא: \u0003נעקרו\u0004 כותלי פתח הרחם ממקומם לתוך הרחם קודם הלידה, ויצא הוולד דרכם, \u0003ותלו ליה בצואריה\u0004 \u0005[ותלויים הם בצווארו]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם דווקא \u0003במקומן\u0004 \u0003מקדשי\u0004 \u0005[\u0006הם \u0005מקדשים],\u0006 \u0003שלא במקומן לא מקדשי\u0004 \u0005[אינם מקדשים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שלא במקומן\u0004 הם \u0003נמי מקדשי\u0004 \u0005[גם כן מקדשים]?\u0006","\u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: נגממו\u0004 (נחתכו) \u0003כותלי בית הרחם,\u0004 שניטל מעובי כתלי פתח הרחם סביב סביב, \u0003מהו? אמר לו: קא נגעת בבעיא דאיבעיא לן\u0004 \u0005[נגעת בבעיה שנשאלה לנו כבר],\u0006 ומשם תמצא תשובה לשאלתך. \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח אחר: \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מרבי אסי:\u0004 אם נחתך חלק מכותלי פתח הרחם, והיה ה\u0003עומד.\u0004 כלומר, מה שנשאר, \u0003מרובה על הפרוץ, ויצא\u0004 הוולד \u0003דרך\u0004 ה\u0003פרוץ,\u0004 או אם היה ה\u0003פרוץ מרובה על העומד, ויצא\u0004 הוולד \u0003דרך\u0004 ה\u0003עומד, מאי\u0004 \u0005[מה]\u0006 הדין?","ומכאן נלמד לשאלתך, שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003איבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 השאלה \u0003אלא\u0004 במקרה שיש \u0003פרוץ מרובה על העומד, דאיכא\u0004 \u0005[ש\u0006על כל פנים \u0005יש]\u0006 \u0003עומד בעולם,\u0004 אלא שיש שהפרוץ מרובה ממנו, \u0003אבל\u0004 אם \u0003נגממו\u0004 כותלי בית הרחם לגמרי, \u0003לא קא מיבעיא ליה\u0004 \u0005[לא נשאלה לו],\u0006 שבזה בוודאי אינו מתקדש."],["\u0003בהמה שמת עוברה בתוך מעיה, והושיט הרועה את ידו ונגע בו, בין\u0004 שהיה זה \u0003בבהמה טמאה, בין בבהמה טהורה\u0004 — הרועה \u0003טהור,\u0004 שאין העובר מטמא כנבילה. \u0003ר' יוסי הגלילי אומר: ב\u0004בהמה \u0003טמאה\u0004 — \u0003טמא, ובטהורה\u0004 — \u0003טהור.\u0004","ושואלים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006 שמטהר עובר מת במעי בהמה? \u0003אמר רב חסדא, קל וחומר\u0004 הוא: \u0003אם הועילה\u0004 שחיטת \u0003אמו להתירו באכילה,\u0004 אם נמצא מת במעיה, \u0003לא תועיל לו\u0004 כשהיא חיה \u0003לטהוריה\u0004 \u0005[לטהר אותו]\u0006 \u0003מידי\u0004 טומאת \u0003נבלה\u0004 כשהוא במעיה?","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 טעם לדין זה ב\u0003בהמה טהורה,\u0004 ב\u0003בהמה טמאה מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וכי ימות מן הבהמה אשר היא לכם לאוכלה הנוגע בנבלתה יטמא\" (ויקרא יא, לט), \u0003\"וכי ימות מן הבהמה\"\u0004 — \u0003זו בהמה טמאה, \"אשר היא לכם לאכלה\"\u0004 — \u0003זו בהמה טהורה,\u0004 ובכך \u0003איתקש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 בכתוב דין נבלת \u0003בהמה טמאה ל\u0004דין נבלת \u0003בהמה טהורה, מה בהמה טהורה\u0004 — \u0003עוברה\u0004 שמת במעיה \u0003טהור,\u0004 כפי שלמדנו לעיל מקל וחומר, \u0003אף בהמה טמאה\u0004 — \u0003עוברה\u0004 שמת במעיה \u0003טהור.\u0004","ושואלים: \u0003ור' יוסי הגלילי,\u0004 האומר שעובר מת שנמצא בבהמה טמאה טמא, \u0003מאי טעמא\u0004 \u0005[מה\u0006 לדעתו \u0005טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר ר' יצחק: דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בדין החיות הטמאות: \u0003\"וכל הולך על כפיו בכל החיה ההולכת\u0004 על ארבע טמאים הם לכם, כל הנוגע בנבלתם יטמא\" (שם כז), וכך דורשים את הכתוב — \u0003מהלכי כפים\u0004 (שאין להם פרסה שסועה כשל בהמה טהורה) ש\u0003ב\u0004תוך גופה של בהמה \u0003חיה טמאתי לך.\u0004","ושואלים: \u0003אלא מעתה,\u0004 לפי הסבר זה, עובר \u0003קלוט,\u0004 שפרסותיו אינן שסועות אלא שלימות, שנמצא \u0003במעי פרה\u0004 — \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 במותו אף שהוא ממין טהור, שהרי בכלל \u0003מהלכי כפים\u0004 שנמצא \u0003ב\u0004בהמה \u0003חיה הוא!\u0004 ומשיבים: הכתוב מטמא \u0003מהלכי כפים\u0004 שנמצאים \u0003במהלכי ארבע\u0004 (\"וכל הולך על כפיו בכל החיה ההולכת על ארבע\"), \u0003והאי\u0004 \u0005[וזה]\u0006 הקלוט שבמעי פרה — \u0003מהלכי ארבע\u0004 שנמצאים \u0003במהלכי שמנה הוא,\u0004 שלקלוט יש ארבע פרסות, וכיון שפרסותיה של הפרה שסועות לשתים, נמצא כאילו יש לה שמונה פרסות.","ומקשים: אם באופן זה אתה מפרש, שרק מהלכי כפיים (בעלי פרסה אחת) שנמצאים במהלכי ארבע מטמאים, עובר שפרסותיו שסועות כשל \u0003פרה,\u0004 שנמצא \u0003במעי גמל,\u0004 שהוא בהמה טמאה שפרסתה אינה שסועה — \u0003לא תטמא\u0004 במותה, שהרי \u0003מהלכי שמנה במהלכי ארבע הוא!\u0004 ומשיבים: יכול היה הכתוב לומר: \u0003\"הולך\"\u0004 ונאמר: \u0003\"וכל הולך\"\u0004 — \u0003לרבות פרה במעי גמל,\u0004 שהיא מטמאת במותה.","ושואלים: עובר \u0003קלוט\u0004 טהור \u0003במעי\u0004 טהורה \u0003קלוטה ליטמא\u0004 \u0005[שיטמא],\u0006 שהרי \u0003מהלכי ארבע ב\u0004תוך \u0003מהלכי ארבע הוא!\u0004 ומשיבים: \u0003להכי אהני\u0004 \u0005[לזה הועיל]\u0006 ה\u0003קל וחומר\u0004 של \u0003רב חסדא,\u0004 לטהר כל עובר מת במעי כל בהמה טהורה, שאם הועילה לו אמו להתירו באכילה — קל וחומר שתועיל לטהרו מידי טומאת נבילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחדבוי בר אמי: חזיר\u0004 שנמצא \u0003במעי חזירתא\u0004 \u0005[חזירה]\u0006 — \u0003לא ליטמא\u0004 \u0005[שלא יטמא]\u0006 במותו, לפי הסבר זה, שכיון שהוא שוסע פרסה — \u0003מהלכי שמנה במהלכי שמנה הוא!\u0004","\u0003אלא אמר רב נחמן בר יצחק, מהכא\u0004 \u0005[מכאן]\u0006 המקור לשיטת ר' יוסי הגלילי, ממה שנאמר בקרבן עולה ויורד, שמביא מי שנטמא ונעלם ממנו שהוא טמא, ואכל קודש או נכנס למקדש: \u0003\"נפש כי תגע בכל טמא או בנבלת חיה טמאה או בנבלת בהמה טמאה או בנבלת שרץ טמא\u0004 והוא טמא ואשם\" (שם ה, ב), ויש לתמוה: מדוע לא הזכיר כאן מי שנוגע בנבלת בהמה טהורה?","\u0003וכי נבלת בהמה טמאה מטמאה, ובטהורה\u0004 נבלתה \u0003לא מטמאה? אלא איזה זה\u0004 שיש בו הבדל בין זו לזו? \u0003זה עובר, שב\u0004מעי בהמה \u0003טמאה\u0004 הוא \u0003טמא, וב\u0004מעי \u0003טהורה\u0004 הוא \u0003טהור.\u0004","ושואלים: \u0003ומאחר דנפקא ליה\u0004 \u0005[שיוצאת לו]\u0006 הלכה זו \u0003מ\u0004דברי \u0003רב נחמן בר יצחק,\u0004 הראיה של \u0003ר' יצחק,\u0004 מן הכתוב \"וכל הולך על כפיו בכל החיה ההולכת על ארבע\" (ויקרא יא, כז) \u0003למה לי?\u0004 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 הראיה של \u0003ר' יצחק, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כוליה לכדרבי הוא דאתא\u0004 \u0005[\u0006הפסוק \u0005כולו\u0006 שממנו דורש רב נחמן בר יצחק, למה שדרש \u0005רבי\u0006 מפסוק זה \u0005הוא שבא],\u0006 כמבואר להלן, ומדבריו של ר' יצחק \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006 לא\u0005],\u0006 שדורשים מפסוק זה גם דרשה זו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 שבה נזכרה הדרשה שהביא ר' יצחק לעיל מ\"כל הולך על כפיו בכל החיה\". \u0003אמר ר' יונתן,\u0004 שהיה מתלמידיו של ר' ישמעאל: \u0003נמתי\u0004 (אמרתי) \u0003לו לבן עזאי, למדנו\u0004 מן הכתוב על \u0003נבלת בהמה טהורה ש\u0004היא \u0003מטמאה, ו\u0004על \u0003נבלת בהמה טמאה ש\u0004היא \u0003מטמאה,\u0004 וכן על \u0003נבלת חיה טמאה ש\u0004היא \u0003מטמאה,\u0004 ואילו","\u0003נבלת חיה טהורה לא למדנו מנין\u0004 שהיא מטמאה! \u0003נם\u0004 (אמר) \u0003לי:\u0004 הדבר נלמד ממה שנאמר \u0003\"כל הולך על כפיו בכל החיה ההולכת\u0004 על ארבע טמאים הם לכם הנוגע בנבלתם יטמא\" (ויקרא יא, כז), ש\"בכל החיה\" מרבה גם חיה טהורה.","\u0003נמתי לו: וכי נאמר \"וכל חיה\"? והלא לא נאמר אלא: \"בכל החיה\",\u0004 וכפי שהסברנו לעיל, \u0003ל\u0004טמא \u0003מהלכי כפים\u0004 הנמצאים \u0003ב\u0004גופה של בהמה \u0003חיה הוא דאתא\u0004 \u0005[שבא],\u0006 כלומר, לעובר מת שבמעי בהמה או חיה טמאה! \u0003נם לי: ומה ישמעאל\u0004 (ר' ישמעאל) \u0003אומר בדבר הזה?\u0004","\u0003נמתי לו\u0004 בשם ר' ישמעאל: דבר זה נלמד ממה שנאמר \"וכי ימות מן הבהמה אשר היא לכם לאכלה הנוגע בנבלתה יטמא\" (ויקרא יא, לט), מה שנאמר: \u0003\"וכי ימות מן הבהמה\"\u0004 — \u0003זו בהמה טמאה, \"אשר היא לכם לאכלה\"\u0004 — \u0003זו בהמה טהורה,\u0004 וכיון ש\u0003למדנו\u0004 מן הכתובים (ראה להלן) ש\u0003חיה בכלל בהמה,\u0004 שכאשר הכתוב מזכיר בהמה — גם חיה בכלל זה, \u0003ו\u0004כן ש\u0003בהמה בכלל חיה\u0004 — יש ללמוד גם לענייננו, שכשטימא הכתוב נבלת בהמה טהורה — טימא גם נבלת חיה טהורה.","וכן לעניינים אחרים, \u0003חיה טהורה בכלל בהמה טהורה, חיה טמאה בכלל בהמה טמאה,\u0004"],["\u0003בהמה טמאה בכלל חיה טמאה, בהמה טהורה בכלל חיה טהורה.\u0004 והוסיף ר' יונתן, \u0003ובלשון הזה אמר לי\u0004 בן עזאי, לאחר שאמרתי לו דברים אלו בשם ר' ישמעאל: חבל על בן עזאי שלא שימש את ר' ישמעאל!","לגופו של הענין מבררים, מה ששנינו: \u0003חיה בכלל בהמה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת הבהמה אשר תאכלו שור שה כשבים וגו' איל וצבי ויחמור\" וגו'\u0004 (דברים יד, ד), \u0003הא כיצד\u0004 מונה הכתוב איל וצבי שהן חיות, בתוך \"זאת הבהמה\"? אלא מכאן למדנו ש\u0003חיה בכלל בהמה.\u0004","\u0003בהמה בכלל חיה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת החיה אשר תאכלו מכל הבהמה אשר על הארץ כל מפרסת פרסה\"\u0004 (ויקרא יא, ב), \u0003הא כיצד\u0004 אתה מיישב את הכתוב, שמתחילה הוא פותח ב\"זאת החיה\", וממשיך ב\"מכל הבהמה כל מפרסת פרסה\"? אלא מכאן למדנו ש\u0003בהמה בכלל חיה.\u0004","ומעתה מבארים את המשך הברייתא: מה ששנינו \u0003חיה טהורה בכלל בהמה טהורה\u0004 — \u0003ל\u0004ענין \u0003סימנים\u0004 נאמר, שהחיה נחשבת טהורה אם יש לה אותם סימנים שנמנו אצל הבהמה הטהורה, שהיא מעלה גרה ומפריסה פרסה, ופרסתה שסועה. ומה ששנינו:","\u0003חיה טמאה בכלל בהמה טמאה\u0004 — נוגע \u0003ל\u0004ענין איסור \u0003הרבעה\u0004 של מינים שונים, וכפי שבבהמה אין חילוק בין הטהורה לטמאה לענין זה, שנאמר: \"בהמתך לא תרביע כלאים\" (ויקרא יט, יט), כך גם בחיה אין חילוק בין טהורה לבין טמאה.","ומה שנאמר: \u0003בהמה טמאה בכלל חיה טמאה\u0004 — \u0003ל\u0004ענין מה שאמר \u0003רבי\u0004 נאמר.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בפרשת קרבן \"עולה ויורד\", שמביא מי שנטמא ונעלם הדבר ממנו ואכל קודש או נכנס למקדש: \"נפש אשר תגע וכו' או בנבלת חיה טמאה או בנבלת בהמה טמאה ונעלם ממנו והוא טמא ואשם\" (ויקרא ה, ב), ועל כך \u0003רבי אומר: אקרא אני\u0004 (כלומר, די שיהיה כתוב כאן) רק \u0003חיה\u0004 טמאה, \u0003בהמה למה נאמרה?\u0004 והרי בהמה בכלל חיה!","אלא כדי ללמדנו גזירה שווה: \u0003נאמרה כאן \"בהמה טמאה\", ונאמר להלן,\u0004 בטמא האוכל את הקודש (במזיד) גם כן \u0003\"בהמה טמאה\"\u0004 (\"ונפש כי תגע וכו' או בבהמה טמאה וכו' ואכל מבשר זבח השלמים אשר לה' ונכרתה הנפש ההיא מעמיה\" (שם ז, כא), \u0003מה להלן\u0004 מדובר ב\u0003טומאת קדש\u0004 — \u0003אף כאן,\u0004 שצריך להביא קרבן על השגגה, מדובר ב\u0003טומאת קדש,\u0004 שאינו מביא קרבן זה אלא אם אכל קודש (או נכנס למקדש) בשגגה כשהוא טמא. והרי דרשה זו מסתמכת על כך שבהמה טמאה בכלל חיה טמאה.","ומה ששנינו: \u0003בהמה טהורה בכלל חיה טהורה\u0004 נוגע \u0003ל\u0004ענין \u0003יצירה. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אשה \u0003המפלת\u0004 נפלים שצורתם כ\u0003מין בהמה חיה ועוף, בין\u0004 שהיו כמין בהמה חיה ועוף \u0003טמאין, בין טהורין, אם\u0004 הפילה \u0003זכר\u0004 — \u0003תשב\u0004 ימי טומאה וימי טהרה שנתנה התורה \u0003ל\u0004יולדת \u0003זכר;\u0004","\u0003אם נקבה\u0004 — \u0003תשב\u0004 ימי טומאה וימי טהרה שנתנה התורה \u0003ל\u0004יולדת \u0003נקבה;\u0004 אם","\u0003אינו ידוע\u0004 מה מינו של העובר — \u0003תשב\u0004 ימי טומאה וימי טהרה גם \u0003לזכר ו\u0004גם \u0003לנקבה,\u0004 אלו","\u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: כל שאינו מצורת אדם אינו\u0004 נחשב \u0003ולד,\u0004 לשבת עליו ימי טומאה וטהרה. ובמקום אחר נתבאר כי לשיטת ר' מאיר נלמד הדבר ממה שהזכיר הכתוב לשון יצירה בחיה ובעוף (\"ויצר ה' אלקים מן האדמה כל חית השדה ואת כל עוף השמים\". בראשית ב, יט), כפי שהזכיר באדם (\"ויצר ה' אלקים את האדם\". שם ז). ולענין זה נאמר בברייתא שבהמה בכלל חיה, שהיולדת כמין בהמה — יושבת ימי טומאה וטהרה, כמו היולדת כמין חיה, שהרי בהמה בכלל חיה. ושבים למה שנאמר (לעיל ע,ב) בשם רב נחמן בר יצחק, כי ר' יוסי הגלילי, שאמר במשנתנו שעובר מת שבמעי בהמה טמאה — טמא, למד דין זה ממה שנאמר בקרבן עולה ויורד: \"ונפש כי תגע וכו' בנבלת בהמה טמאה\" (ויקרא ז, כא), שיש לשאול: וכי נבלת בהמה טהורה לא מטמאה? אלא למדנו מכאן לעובר מת שנמצא במעי בהמה, שבבהמה טמאה הוא טמא, ובבהמה טהורה הוא טהור.","ושואלים: \u0003ולרבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים]\u0006 של משנתנו, שגם עובר מת שנמצא בבהמה טמאה — טהור, \u0003האי קרא\u0004 \u0005[אותו מקרא]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003כוליה לכדרבי הוא דאתא\u0004 \u0005[\u0006אותו כתוב \u0005כולו לכמו\u0006 שדרש \u0005רבי\u0006 מכתוב זה \u0005הוא שבא],\u0006 ללמד שקרבן עולה ויורד בא על אכילת קודש בטומאה בשגגה.","\u0003האשה שמת ולדה בתוך מעיה, ופשטה\u0004 (והושיטה) \u0003חיה\u0004 (המיילדת) \u0003את ידה ונגעה בו\u0004 בעובר כשהוא במעי אמו — \u0003החיה טמאה\u0004 \u0003טומאת שבעה\u0004 ימים, כמי שנוגע במת, \u0003והאשה טהורה\u0004 מכל טומאה \u0003עד שיצא הולד.\u0004","בקשר לדין משנתנו מביאים מה ש\u0003אמר רבה: כשם שטומאה\u0004 ש\u0003בלועה\u0004 בתוך הגוף \u0003אינה מטמאה\u0004 מה שנגעה בו — \u0003כך טהרה בלועה אינה מיטמאה,\u0004 אינה מקבלת טומאה, וכגון אדם שבלע טבעת טהורה ונכנס לאוהל שהמת נמצא בו — אין הטבעת נטמאת.","ושואלים, \u0003טומאה בלועה מנלן\u0004 \u0005[מנין לנו]\u0006 שאינה מטמאת? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין בהמה שמתה: \u0003\"והאוכל מנבלתה יכבס בגדיו\u0004 וטמא עד הערב\" (ויקרא יא, מ), שצריך לטבול גופו ובגדיו, וכשמגיע הערב הריהו טהור; \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה \u0003ש\u0004\u0003אכל סמוך לשקיעת החמה? וקאמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 שהוא \u0003טהור\u0004 משעה שיגיע הערב, למרות שיש במעיו חתיכת נבילה שלא נתעכלה.","ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם],\u0006 \u0003דלא חזיא\u0004 \u0005[ש\u0006אותה חתיכה \u0005אינה ראויה]\u0006 \u0003ל\u0004אכילת \u0003גר,\u0004 כלומר, אינה ראויה לאכילת אדם, ובמקרה זה פקע ממנה שם נבילה!","ומוסיפים: \u0003הניחא\u0004 \u0005[זה נוח],\u0006 אמנם יש מכאן הוכחה אם נלך \u0003ל\u0004שיטת \u0003רבי יוחנן\u0004 ש\u0003אמר\u0004 בענין זה: \u0003אחת זו ואחת זו,\u0004 בין טומאה חמורה לטמא אדם, ובין טומאה קלה לטמא אוכלים, הנבילה מטמאה \u0003עד\u0004 שתיפסל \u0003ל\u0004אכילת \u0003כלב;\u0004 לשיטתו \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 שמוכח מכאן שטומאה בלועה אינה מטמאת, שאם לא כן — היתה מטמאת, שהרי עדיין ראויה היא לאכילת כלב.","\u0003אלא ל\u0004דעת \u0003בר פדא\u0004 ש\u0003אמר: טומאה חמורה\u0004 מטמאה הנבילה כל זמן שהיא ראויה לאכילה \u0003לגר, וטומאה קלה\u0004 היא מטמאה \u0003עד\u0004 שתיפסל \u0003ל\u0004אכילת \u0003כלב\u0004 — אין מכאן הוכחה, שיש לומר שאינה מטמאה כשהיא במעי האוכל \u0003משום דלא חזיא\u0004 \u0005[ש\u0006כבר \u0005אינה ראויה]\u0006 \u0003לגר הוא,\u0004 שמשעה שנבלעה אינה ראויה לאכילת אדם!","ומשיבים: חתיכת נבילה שזה עתה נבלעה, \u0003נהי דלא חזיא\u0004 \u0005[\u0006גם \u0005אם אמנם אינה ראויה]\u0006 לאדם \u0003בפניו,\u0004 כשהוא יודע שנבלעה, מכל מקום \u0003שלא בפניו,\u0004 אם לא היה יודע על כך — \u0003מיחזיא חזיא ליה\u0004 \u0005[ראויה היא לו],\u0006 וכגון שהיתה זו חתיכה קטנה שלא נלעסה, ודין נבילה גמורה יש לה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו, איפוא]\u0006 מקור לכך ש\u0003טומאה בלועה\u0004 אינה מטמאה את הנוגע בה, \u0003טהרה בלועה מנלן\u0004 \u0005[מנין לנו]\u0006 שאינה נטמאת?","ומשיבים, \u0003קל וחומר\u0004 הוא: \u0003ומה כלי חרס\u0004 שאין בו חלל טפח \u0003המוקף צמיד פתיל,\u0004 שמכסהו צמוד ומהודק, \u0003שאינו מציל על טומאה שבתוכו מלטמא,\u0004 שאם כזית מן המת מצוי בתוכו — נטמא הכלי וגם כל מה שבאותו בית; \u0003דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003טומאה רצוצה,\u0004 דחוסה בקרקע או בכלי, שאין לה חלל טפח \u0003בוקעת ועולה עד לרקיע\u0004 — בכל זאת \u0003מציל\u0004 אותו כלי חרס כשהוא באוהל המת \u0003על טהרה שבתוכו מלטמא,\u0004"],["\u0003אדם שמציל על טומאה שבתוכו מלטמא,\u0004 כפי שלמדנו לעיל מן האוכל נבילה, שהוא טהור לאחר שטבל, למרות שהטומאה בגופו — \u0003אינו דין שמציל על טהרה שבתוכו מליטמא?\u0004","ודוחים: \u0003מה לכלי חרס,\u0004 דין הוא שיציל על טהרה שבתוכו מלהיטמא, \u0003שכן אין\u0004 כלי חרס \u0003מטמא מגבו,\u0004 שאם נגעה טומאה מצידו החיצוני אינו נטמא, אלא רק מתוכו, \u0003תאמר באדם שמטמא\u0004 \u0003מגבו,\u0004 כשנגעה בו טומאה, ושמא לא יציל על טהרה שבלועה בתוכו מלהיטמא!","ומשיבים: \u0003אטו אנן\u0004 \u0005[וכי אנו]\u0006 \u0003מגבו\u0004 של כלי חרס \u0003קאמרינן\u0004 \u0005[אמרנו,\u0006 רצינו להוכיח\u0005]?\u0006 והלא \u0003מתוכו קאמרינן\u0004 \u0005[אמרנו],\u0006 מתוכו של חרס רצינו להוכיח לתוכו של אדם, שכשם שתוכו של כלי חרס מציל על טהרה שבו מלהיטמא — כך תוכו של אדם יציל על טהרה שבו מלהיטמא.","ומצד זה, \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003כלי חרס חמור\u0004 יותר מאדם, \u0003שכן\u0004 הוא \u0003מטמא מאוירו,\u0004 כשהטומאה מצויה בחללו, גם בלא שתיגע בו הטומאה. ואילו אדם אינו נטמא מטומאה שנמצאת בחלל גופו (כגון בחלל פיו), אלא רק אם נגעה בו. ונמצא שהקל וחומר עומד בעינו.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור ל\u0003בלוע\u0004 של \u0003למעלה,\u0004 שאדם מציל על טומאה שבלע דרך פיו מלטמא — ממה שאמרה התורה, שהאוכל נבילה טובל ונטהר למרות שחתיכת הנבילה מצויה בגופו. אבל \u0003בלוע\u0004 של \u0003למטה,\u0004 דבר שהוכנס לגופו דרך פי הטבעת, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שאינו מטמא? ומשיבים, \u0003קל וחומר\u0004 הוא: \u0003ומה למעלה, שאינו עושה עיכול\u0004 \u0003— בכל זאת\u0004 \u0003מציל\u0004 מה שבלוע בו; \u0003למטה,\u0004 שהוא מקום \u0003שעושה עיכול,\u0004 שכבר נתעכלה שם הטומאה — \u0003אינו דין ש\u0004הוא \u0003מציל?\u0004 ודוחים: ומה קל וחומר יש כאן?","\u0003כלום,\u0004 כלומר, הרי אינו \u0003עושה עיכול\u0004 (אינו מעוכל) \u0003למטה אלא על ידי\u0004 הלעיסה והעיכול שמל \u0003מעלה!\u0004 ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003עיכול\u0004 של \u0003למטה רב\u0004 \u0005[גדול יותר]\u0006 משל מעלה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו,\u0006 איפוא\u0005]\u0006 \u0003בלוע\u0004 שב\u0003אדם\u0004 שאינו מטמא, \u0003בלוע\u0004 ב\u0003בהמה מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003קל וחומר: ומה אדם\u0004 \u0003ש\u0004הוא \u0003מטמא מחיים,\u0004 שגם בחייו הוא מטמא, כגון זב ומצורע — \u0003מציל בבלוע, בהמה שאינה מטמאה מחיים,\u0004 אלא רק כשהיא נבילה — \u0003אינו דין שתציל בבלוע?\u0004","ופורכים את הקל וחומר: \u0003מה לאדם,\u0004 שיש בו צד קל, \u0003שכן צריך שהייה בבית המנוגע\u0004 בצרעת כדי שייטמאו מלבושיו, ואינם נטמאים מיד כשנכנס לבית, \u0003תאמר בבהמה, שאינה צריכה שהייה בבית המנוגע\u0004 כדי לטמא כלים שעליה?","ודוחים: \u0003בהמה\u0004 ש\u0003אינה צריכה שהייה בבית המנוגע,\u0004 \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003ל\u0004ענין \u0003כלים ש\u0004מונחים \u0003על גבה.\u0004 ואולם לענין כלים שעל גביו, \u0003אדם נמי לא בעי\u0004 \u0005[גם כן אינו צריך]\u0006 שהייה כדי שייטמאו!","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אדם \u0003הנכנס לבית המנוגע וכליו\u0004 (בגדיו) מונחים \u0003על כתפיו,\u0004 שאינו לבוש בהם, \u0003וסנדליו וטבעותיו\u0004 מונחים \u0003בידיו\u0004 — \u0003הוא והן טמאין מיד.\u0004 אבל אם \u0003היה לבוש כליו, וסנדליו ברגליו, וטבעותיו באצבעו\u0004 — \u0003הוא טמא מיד, והן טהורין עד שישהא בכדי אכילת פרס\u0004 (חצי ככר לחם). ומדובר באכילת פרס מ\u0003פת חטים ולא\u0004 מ\u0003פת שעורים,\u0004 שהוא זמן ארוך יותר, וכן בשיעור הזמן שנצרך לאוכלה כשהוא \u0003מיסב\u0004 (שוכב על צידו), \u0003ואוכל\u0004 אותה \u0003בליפתן,\u0004 יחד עם דברים שרגילים לאכול עם הפת.","\u0003אמר רבא:\u0004 מדוע הוצרך רבה לומר דבר זה? והרי \u0003תרוייהו תננהי\u0004 \u0005[\u0006את \u0005שני הדברים הללו\u0006 כבר \u0005שנינו במשנה],\u0006 \u0003טומאה בלועה תנינא\u0004 \u0005[שנינו],\u0006 וגם \u0003טהרה בלועה תנינא\u0004 \u0005[שנינו]!\u0006","ומפרטים: \u0003טומאה בלועה\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אדם ש\u0003בלע טבעת טמאה\u0004 בטומאת מת, ונטמא בשעה שבלע אותה — הרי זה \u0003טובל\u0004 לטומאתו, \u0003ו\u0004מיד אחר כך \u0003אוכל בתרומתו,\u0004 למרות שהטבעת הטמאה במעיו, מפני שהיא בלועה. אם \u0003הקיאה\u0004 את הטבעת הזו — הרי הטבעת עדיין \u0003טמאה,\u0004 שלא נטהרה בטבילתו, ולכן חזרה \u0003וטמאתו\u0004 כשיצאה מגופו.","וכן \u0003טהרה בלועה תנינא\u0004 \u0005[שנינו]\u0006 שאינה נטמאת, \u0003דתנן\u0004 \u0005[ששנינו\u0006 באותה משנה\u0005]:\u0006 \u0003בלע טבעת טהורה, ונכנס לאהל המת\u0004 ונטמא שבעת ימים, \u0003והזה\u0004 (היזו עליו) ממי פרה אדומה ביום השלישי לטהרתו, \u0003ושנה,\u0004 שחזרו והיזו עליו ביום השביעי, \u0003וטבל והקיאה\u0004 — \u0003הרי היא\u0004 טהורה \u0003כמה שהיתה,\u0004 שלא נטמאה באוהל המת!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רבה\u0004 שטומאה בלועה אינה מטמאת, וטהרה בלועה אינה נטמאת, אינו במקרה המפורש במשנה זו, אלא \u0003כגון שבלע שתי טבעות, אחת\u0004 מהן \u0003טמאה ואחת טהורה,\u0004 ובא כאן לחדש ולומר \u0003דלא מטמיא לה\u0004 \u0005[שאינה מטמאת אותה],\u0006 ה\u0003טמאה לטהורה,\u0004 למרות שנגעו זו בזו."],["ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עובר\u0004 הבלוע במעי אמו \u0003וחיה\u0004 (מילדת) שנגעה בו במעי אמו, ש\u0003כשתי טבעות\u0004 בלועות \u0003דמו\u0004 \u0005[נחשבים],\u0006 \u0003וקא מטמא לה\u0004 \u0005[ו\u0006בכל זאת \u0005מטמא]\u0006 ה\u0003עובר\u0004 את ה\u0003חיה,\u0004 כפי ששנינו במשנתנו!","\u0003אמר רבה: שאני\u0004 \u0005[שונה]\u0006 \u0003עובר,\u0004 שאינו נחשב כבלוע \u0003הואיל וסופו לצאת. אמר רבא\u0004 בתמיהה: וכי \u0003עובר סופו לצאת,\u0004 ו\u0003טבעת\u0004 טמאה שבלע אדם \u0003אין סופו לצאת\u0004 ממעיו? ומדוע לא תטמא את הטבעת הטהורה? \u0003אלא אמר רבא: פומבדיתאי ידעי טעמא דהא מילתא\u0004 \u0005[חכמי פומבדיתא יודעים טעם דבר זה]\u0006 ששנינו במשנתנו, \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003רב יוסף.\u0004","ש\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: טומאה זו\u0004 של החיה \u0003אינה מדברי תורה, אלא מדברי סופרים\u0004 (חכמים). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003אינה מדברי תורה אלא מדברי סופרים?\u0004 מה פשר ההדגשה \"אינה מדברי תורה\"? ומשיבים: \u0003דלא תימא\u0004 \u0005[שלא תאמר]\u0006 שמשנה זו היא דווקא \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' עקיבא\u0004 ש\u0003אמר: עובר במעי אשה טמא, אלא אפילו ל\u0004דעת \u0003ר' ישמעאל\u0004 ש\u0003אמר: עובר במעי אשה טהור\u0004 — \u0003גזרו בה,\u0004 בחיה, \u0003טומאה מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב הושעיא: גזירה שמא יוציא\u0004 ה\u0003ולד\u0004 המת את \u0003ראשו חוץ לפרוזדור\u0004 הרחם, שאז הוא נחשב כילוד ומטמא, והחיה לא תרגיש בדבר, ותהא סבורה שהיא טהורה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 על ה\u0003אשה נמי\u0004 \u0005[גם כן]\u0006 יגזרו טומאה! ומשיבים: \u0003אשה מרגשת בעצמה\u0004 אם יצא ראש העובר חוץ לפרוזדור. ושואלים: אם כן, מדוע לגזור טומאה על החיה? \u0003ותימא\u0004 \u0005[ושתאמר]\u0006 \u0003לה\u0004 היולדת \u0003לחיה\u0004 מתי יצא ראשו! ומשיבים: \u0003טרידא\u0004 \u0005[\u0006היולדת \u0005טרודה]\u0006 בכאביה, ואינה פנויה להזהיר את החיה שלא תגע.","ומבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 שאמר \u0003ר' ישמעאל, ומאי\u0004 \u0005[ומהו]\u0006 שאמר \u0003ר' עקיבא?\u0004 ומשיבים, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בפרשת טומאת המת \u0003\"וכל אשר יגע על פני השדה\u0004 בחלל חרב וכו' יטמא שבעת ימים\" (במדבר יט, טז), והביטוי \"על פני השדה\", שמשמעו מקום גלוי — בא \u0003להוציא עובר\u0004 מת \u0003במעי אשה,\u0004 לומר שאינו מטמא, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 מה שנאמר \"על פני השדה\" בא \u0003לרבות גולל\u0004 (כיסוי הקבר) \u0003ודופק\u0004 (דופן הקבר שעליה נסמך הגולל), לומר שהם מטמאים.","ומעירים: \u0003ו\u0004לדעת \u0003ר' ישמעאל, גולל ודופק\u0004 שמטמאים — \u0003הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005לומד הוא אותה],\u0006 ולא מן הכתוב. ושואלים: \u0003ור' עקיבא\u0004 שאמר ש\u0003עובר במעי אשה טמא מדאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 היכן בתורה נלמד הדבר? \u0003אמר ר' אושעיא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כל \u0003הנוגע במת בנפש\u0004 האדם\" (שם יג), \u0003איזהו מת ש\u0004נמצא \u0003בנפש\u0004 (בתוכו) \u0003של אדם? הוי אומר זה עובר שבמעי אשה.\u0004","ומן הצד השני, \u0003ור' ישמעאל\u0004 מה הוא משיב לכך? לשיטתו \u0003האי מיבעי ליה\u0004 \u0005[\u0006דבר \u0005זה נצרך לו]\u0006 \u0003ל\u0004ענין \u0003רביעית\u0004 הלוג של \u0003דם הבאה מן המת,\u0004 לומר \u0003ש\u0004היא \u0003מטמאה\u0004 באוהל כמת, \u0003שנאמר: \"הנוגע במת בנפש האדם\", איזהו נפש של אדם שמטמא? הוי אומר זו רביעית דם,\u0004 כפי שנאמר \"כי הדם הוא הנפש\" (דברים יב, כג), וברביעית דם הנפש מתקיים הדבר.","\u0003ור' עקיבא,\u0004 שאינו למד דין זה מכאן, הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: אף רביעית דם הבא משני מתים מטמא באהל. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0005ר' עקיבא אומר: מנין לרביעית דם הבאה משני מתים\u0006 \u0003שמטמאה באהל?\u0004","\u0003שנאמר\u0004 באיסור הטומאה לכהן גדול: \u0003\"ועל כל נפשות מת לא יבא\"\u0004 (ויקרא כא, יא), והשינוי מלשון רבים ללשון יחיד (\"נפשות מת\") מלמד על מקרה של \u0003שתי נפשות\u0004 (מתים) \u0003ושיעור אחד\u0004 של נפש המת (רביעים דם), שמטמא באוהל, וכל שכן ברביעית הבאה ממת אחד, ולכן לא הוצרך לפסוק של ר' ישמעאל.","\u0003בהמה המקשה לילד, והוציא\u0004 ה\u0003עובר את ידו, וחתכה\u0004 הרועה, \u0003ואחר כך שחט את אמו,\u0004 למרות שהאבר שנחתך מטמא, שלא הותר בשחיטת הבהמה — \u0003הבשר\u0004 של העובר כולו שהיה מחובר ליד \u0003טהור,\u0004 מפני שבעל חיים אינו מקבל טומאה בחייו. אבל אם \u0003שחט את אמו ואחר כך חתכה\u0004 את היד, הרי \u0003הבשר\u0004 של העובר כולו שנגע בה טמא איפוא ב\u0003מגע נבלה,\u0004 אלו \u0003דברי ר' מאיר,\u0004 שלדעתו יש ליד דין נבילה, שלא נטהרה בשחיטת האם.","\u0003וחכמים אומרים:\u0004 שחיטת הבהמה, למרות שלא הועילה לאבר שיצא להתירו באכילה, מכל מקום הועילה לטהרו מטומאת נבילה, ודין בשר העובר שנגע בה כדין \u0003מגע טרפה שחוטה,\u0004 שאסורה באכילה, אבל טהורה מטומאת נבילה."],["\u0003מה מצינו ב\u0004בהמה \u0003טרפה ששחיטתה מטהרתה\u0004 מטומאת נבילה, למרות שהיא אסורה באכילה — \u0003אף שחיטת בהמה תטהר את האבר\u0004 של העובר שבמעיה, למרות שהוא אסור באכילה.","\u0003אמר להם ר' מאיר: לא, אם טיהרה שחיטת טרפה אותה,\u0004 משום שהוא \u0003דבר ש\u0004הוא \u0003גופה,\u0004 וכי \u0003תטהר את האבר\u0004 של העובר, שהוא \u0003דבר שאינו גופה?\u0004","ושואלים: \u0003מנין לטרפה ששחיטתה מטהרתה\u0004 מלטמא כנבילה? והרי \u0003בהמה טמאה אסורה באכילה,\u0004 ו\u0003אף\u0004 בהמה טהורה שהיא \u0003טרפה אסורה באכילה,\u0004 ואם כן נאמר: \u0003מה בהמה טמאה\u0004 — \u0003אין שחיטתה מטהרתה, אף טרפה\u0004 — \u0003לא תטהרנה שחיטה!\u0004","ודוחים: \u0003לא, אם אמרת בבהמה טמאה שלא היתה לה\u0004 מעולם \u0003שעת הכושר,\u0004 להיטהר מטומאתה על ידי שחיטה, \u0003תאמר בטרפה שהיתה לה שעת הכושר\u0004 להיטהר, קודם שנטרפה? וכיון שחלה עליה תורת שחיטה לטהרה — שוב אינה פוקעת ממנה.","ודוחים: \u0003טול לך מה שהבאת,\u0004 חזור בך מטענה זו, שכן לפי דבריך, \u0003הרי שנולדה טרפה מן הבטן, מנין\u0004 ששחיטתה מטהרתה? הרי לא היתה לה שעת הכושר כלל! אלא צריך לומר כך:","\u0003לא, אם אמרת בבהמה טמאה\u0004 שאין שחיטתה מטהרתה — \u0003שכן אין במינה\u0004 כלל \u0003שחיטה,\u0004 שדין שחיטה נאמר רק בבקר וצאן, להתירם באכילה ובהקרבה, ולא בבהמה טמאה, \u0003תאמר בטרפה שיש במינה שחיטה?\u0004 וכיון שכן, יש לומר שלא יצאה מכלל דין שחיטה.","ומוסיפים: לפי זה, עובר של פרה \u0003בן שמנה\u0004 חדשים שנולד \u0003חי,\u0004 קודם שנגמרו חדשי הריונו — \u0003אין שחיטתו מטהרתו\u0004 מטומאת נבילה, \u0003לפי שאין במינו\u0004 של בן שמונה \u0003שחיטה,\u0004 שכיון שלא נשלם עיבורו הריהו כירך אמו, ואינו ניתר אלא בשחיטת אמו כשהוא במעיה.","שנינו במשנה, שעובר שהוציא ידו ממעי אמו, ושחט את האם, לדעת ר' מאיר נטמא בשר העובר כולו בגלל חיבורו ליד, שהיא טמאה כנבילה. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה העובר טמא? הלוא \u0003טומאת בית הסתרים היא,\u0004 שמגע העובר באבר הוא בחיבור שביניהם, שאינו גלוי לעין, \u0003וטומאת בית הסתרים לא מטמיא\u0004 \u0005[אינה מטמאה]!\u0006 \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ר' מאיר\u0004 הולך \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 שמגע בית הסתרים מטמא?","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 בגד קטן ששיעורו \u0003שלשה על שלשה\u0004 טפחים, שישב עליו הזב וטימאו, \u0003שנחלק\u0004 לשנים — \u0003טהור מן המדרס,\u0004 שאינו מטמא אדם וכלים כדין מדרס הזב, מפני שאינו ראוי יותר לישיבה,","\u0003אבל\u0004 אם נשאר בכל אחד משני החלקים שיעור שלוש על שלוש אצבעות, שראוי לקבל טומאה אחרת, כגון טומאת מת — \u0003טמא\u0004 טומאת \u0003מגע\u0004 (נוגע ב) \u0003מדרס,\u0004 שהרי נגע בחלק השני בעודם מחוברים, \u0003אלו דברי ר' מאיר,\u0004 שהוא סבור שמגע בית הסתרים מטמא.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: וכי באיזה מדרס נגע זה\u0004 לאחר שנחלק? ומה שנגעו זה בזה בשעה שהיו מחוברים — אינו מגע, מפני שהוא מגע בית הסתרים! \u0003אלא\u0004 אם יש מקום לומר שנשתייר בו מטומאת הזב, הרי זה במקרה \u0003שאם\u0004 גם \u0003נגע בו זב\u0004 בגופו, ולא רק דרס עליו בנעליו — \u0003שיהא טמא\u0004 משום \u0003מגע זב,\u0004 שצד זה של טומאה לא פקע ממנו כל עוד יש בו שלוש על שלוש אצבעות. ואם כן, האם נאמר שחכמים הסבורים במשנתנו שהיד שהוציא העובר אינה מטמאה את בשרו, סבורים כר' יוסי, שמגע בית הסתרים אינו מטמא?","ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[וכי לא נאמר עליה]\u0006 על הלכה זו, \u0003אמר עולא: לא שנו\u0004 שנחלק ר' יוסי \u0003אלא\u0004 בבגד שיש בו \u0003שלשה על שלשה שנחלק,\u0004 ואין באף אחד מחלקיו שיעור טומאת מדרס שיטמא את חבירו,","\u0003אבל\u0004 חתיכה של \u0003שלש על שלש\u0004 אצבעות \u0003הבאות מבגד גדול\u0004 — \u0003בשעת פרישתן מאביהן,\u0004 מן הבגד, קודם שנחתכו ממנו לגמרי, הריהן \u0003מקבלות טומאה מאביהן.\u0004 ואם כן \u0003הא נמי\u0004 \u0005[זה גם כן]\u0006 במשנתנו, יש לומר כי כאשר חותכים את ידו של העובר משאר אבריו — \u0003בשעת פרישתן מ\u0004ה\u0003אבר\u0004 (מן היד) \u0003מקבל\u0004 בשר העובר \u0003טומאה מ\u0004ן ה\u0003אבר,\u0004 גם לדעת מי שסבור שמגע בית הסתרים אינו מטמא.","\u0003רבינא אמר:\u0004 יש לחלק בין דין משנתנו לבין דין בגד שנחלק, באופן אחר: \u0003בגד\u0004 — \u0003לאו לחתיכה קאי\u0004 \u0005[אינו עומד לחיתוך],\u0006 ולכן מקום החיבור שבין חלקיו נחשב בית הסתרים. אבל \u0003עובר\u0004 זה — \u0003לחתיכה קאי\u0004 \u0005[עומד],\u0006 לחתוך את היד שהוציא, שהעובר עצמו מותר באכילה והיד אסורה, \u0003וכל העומד לחתוך\u0004 —"],["\u0003כחתוך דמי\u0004 \u0005[נחשב],\u0006 ונמצא שהעובר והאבר נחשבים (כשהם מחוברים) כשני דברים נפרדים שנוגעים זה בזה.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר רבינא חילוק זה? האם \u0003כ\u0004שיטת \u0003רבי מאיר\u0004 דווקא? \u0003דתנן\u0004 \u0005[ששנינו]\u0006 בענין טבילת כלים טמאים: \u0003כל ידות הכלים שהן ארוכות ועתיד לקצצן\u0004 — \u0003מטביל עד מקום מדה,\u0004 עד המקום בו היד עתידה להיקצץ, אלו \u0003דברי ר' מאיר,\u0004 שהוא רואה את מה שעתיד ליקצץ כאילו נקצץ.","\u0003ו\u0004אילו \u0003חכמים אומרים: עד שיטביל את כולו.\u0004 הרי שלדעתם העומד להיקצץ אינו נחשב כקצוץ.","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שגם אם לענין כלים אין אומרים שכל העומד ליחתך — כחתוך נחשב, \u0003חבורי אוכלין\u0004 (אוכלים מחוברים) כיון שהם רכים — \u0003כמאן דמפרתי דמי\u0004 \u0005[כמו נפרדים הם נחשבים],\u0006 \u0003ונגיעי בהדדי\u0004 \u0005[ונוגעים זה בזה],\u0006 ולכן רואים את יד העובר כחתוכה מגופו, ומטמאה אותו במגעה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004הסברו של \u0003עולא,\u0004 שבשעת חיתוך האבר מגוף העובר נטמא העובר — \u0003היינו דקתני\u0004 \u0005[זהו שהוא שונה]\u0006 במשנה: שחט את אמו ואחר כך \u0003חתכה\u0004 הבשר מגע נבילה, שכל עוד לא חתכה — אינו נטמא. \u0003אלא ל\u0004הסברו של \u0003רבינא\u0004 שכל העומד לחתוך נחשב כחתוך, \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003חתכה?\u0004 הרי כבר קודם שחתכה הבשר נטמא! ומשיבים: \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילת המשנה]\u0006 \u0003חתכה,\u0004 ושם הוצרך הדבר — \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן בסופה]\u0006 \u0003חתכה.\u0004","שנינו במשנה, \u0003וחכמים אומרים:\u0004 עובר שהוציא את ידו, ושחט את אמו ואחר כך חתכה — דין הבשר כדין \u0003מגע\u0004 (מה שנוגע) ב\u0003טרפה שחוטה.\u0004 ושואלים: \u0003טרפה שחוטה מי מטמיא\u0004 \u0005[האם היא מטמאה]?\u0006 הרי טהורה היא! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כ\u0004מו שאמר \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל,\u0004 ש\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: טרפה ששחטה\u0004 — \u0003מטמאה במוקדשין.\u0004","שנינו במשנה שכך מסבירים חכמים את טעמם: \u0003מה מצינו בטרפה ששחיטתה מטהרתה\u0004 — \u0003אף שחיטת בהמה תטהר את\u0004 היד שהוציא \u0003העובר\u0004 שבמעיה, למרות שהיד אסורה באכילה משום בשר שיצא חוץ למחיצתו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שכך \u0003אמר להן רבי מאיר:\u0004 לשיטתכם, \u0003וכי מי טיהרו לאבר זה מידי נבלה?\u0004 הרי \u0003שחיטת אמו\u0004 טיהרתו, \u0003אם כן תתירנו\u0004 אף \u0003באכילה!\u0004","\u0003אמרו לו: הרבה\u0004 (יותר) \u0003מצלת\u0004 שחיטת בהמה \u0003על\u0004 מה \u0003שאינו גופה יותר מ\u0004על \u0003גופה, שהרי שנינו:\u0004 ה\u0003חותך מן העובר שבמעיה\u0004 ולא הוציא את החתיכות ממעיה עד שנשחטה — \u0003מותר באכילה,\u0004 שהותר בשחיטתה. אבל החותך \u0003מן הטחול ומן הכליות\u0004 קודם שנשחטה — מה שבמעיה \u0003אסור באכילה,\u0004 שלא התירה אותו שחיטתה.","ושואלים: \u0003מאי קאמר\u0004 \u0005[מהו אומר]?\u0006 מה משיבים לו חכמים? הרי אינם עונים כלל לטענתו! \u0003אמר רבא ואמרי לה כדי\u0004 \u0005[ויש אומרים אותה בסתם,\u0006 בלי שם\u0005]:\u0006 \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך היא שנויה],\u0006 \u0003אמר להן ר' מאיר: וכי מי טהרו לאבר זה מידי נבלה\u0004 לשיטתכם? \u0003שחיטת אמו, אם כן תתירנו\u0004 גם כן \u0003באכילה! אמרו לו: טרפה תוכיח, ששחיטתה מטהרתה מידי נבלה, ואינה מתירתה באכילה.\u0004","\u0003אמר להן: לא, אם טיהרה שחיטת טרפה אותה,\u0004 מפני שהיא מטהרת \u0003דבר שהיא גופה, תטהר את האבר\u0004 של העובר, שהוא \u0003דבר שאינו גופה? אמרו לו:\u0004 מצאנו כי \u0003הרבה\u0004 (יותר) \u0003מצלת\u0004 ומועילה השחיטה \u0003על\u0004 דבר \u0003שאינו גופה, יותר מ\u0004על דבר שהוא \u0003גופה, שהרי שנינו:\u0004 ה\u0003חותך מן העובר שבמעיה\u0004 של בהמה, ולא הוציא את החתיכות עד שנשחטה — \u0003מותר באכילה,\u0004 חתך \u0003מן הטחול ומן הכליות\u0004 שבמעיה — \u0003אסור באכילה,\u0004 ולא הועילה שחיטתה להתירו, למרות שהוא מגופה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך],\u0006 כפי שהסביר רבא, \u0003אמר להן רבי מאיר: וכי מי טיהרו לאבר זה\u0004 שהוציא העובר \u0003מידי נבלה? אמרו לו: שחיטת אמו.\u0004 אמר להם: \u0003אם כן, תתירנו באכילה! אמרו לו: טרפה תוכיח, ששחיטתה מטהרתה מידי נבלה,\u0004 למרות ש\u0003אינה מתירתה באכילה.\u0004","\u0003אמר להן: אם טיהרה שחיטת טרפה אותה\u0004 עצמה, \u0003ו\u0004כן אם טיהרה שחיטת בהמה \u0003את האבר המדולדל בה,\u0004 שנחתך ומחובר בה במקצת, שאף על פי שהוא אסור באכילה אינו מטמא כנבילה (להלן קכז,ב), שכן הוא \u0003דבר שגופה, תטהר את\u0004 האבר שהוציא \u0003העובר, שאינו גופה?\u0004","\u0003אמרו לו: הרבה מצלת\u0004 שחיטה \u0003על\u0004 דבר \u0003שאינו גופה\u0004 של הבהמה \u0003יותר\u0004 מעל דבר ש\u0003מגופה, שהרי שנינו: חותך מן העובר שבמעיה\u0004 — \u0003מותר באכילה,\u0004 בשחיטת האם, חתך \u0003מן הטחול ומן הכליות\u0004 — \u0003אסור באכילה.\u0004","בענין מחלוקת ר' מאיר וחכמים, \u0003אמר ר' שמעון בן לקיש: כמחלוקת\u0004 ששנינו \u0003בעוברין,\u0004 האם שחיטת האם מועילה לאבר שהוציא העובר לטהרו מטומאת נבילה — \u0003כך מחלוקת באיברין\u0004 מדולדלים של הבהמה עצמה, שלר' מאיר שחיטתה אינה מטהרת אותם מטומאת נבילה, ולדעת חכמים מטהרת.","\u0003ורבי יוחנן אמר: מחלוקת באבר\u0004 של \u0003עובר\u0004 שהוציאו, \u0003אבל באבר\u0004 מדולדל של \u0003בהמה\u0004 — \u0003דברי הכל שחיטה עושה ניפול\u0004 כלומר, מחשיבה את האבר כאילו נפל ונחתך מגופה, ואינה מועילה לטהרו, וגם לדעת חכמים.","\u0003אמר ר' יוסי בר' חנינא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 האבר שהוציאו העובר \u0003אית ליה תקנתא\u0004 \u0005[יש לו תקנה]\u0006 \u0003בחזרה,\u0004 שאם החזיר העובר את ידו, ושחט את האם — מותרת היד באכילה, \u0003והא\u0004 \u0005[וזה],\u0006 האבר המדולדל של הבהמה — \u0003לית ליה תקנתא\u0004 \u0005[אין לו תקנה]\u0006 \u0003בחזרה,\u0004 שהרי אין מציאות שיחזור ויידבק בגוף הבהמה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא לעיל, \u0003אמר להם ר' מאיר\u0004 לחכמים: \u0003לא, אם טיהרה שחיטת טרפה אותה, ואת האבר המדולדל בה\u0004 — \u0003דבר שגופה, תטהר את העובר\u0004 — \u0003דבר שאינו גופה?\u0004"],["\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבי שמעון בן לקיש,\u0004 ר' מאיר \u0003לדבריהם\u0004 של חכמים \u0003קאמר להו\u0004 \u0005[אומר להם]:\u0006 \u0003לדידי\u0004 \u0005[לשיטתי],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003אבר\u0004 שהוציאו \u0003עובר, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003אבר\u0004 מדולדל של \u0003בהמה\u0004 — \u0003כי הדדי נינהו\u0004 \u0005[זה כמו זה הם]\u0006 ודינם אחד, שאין שחיטת הבהמה מטהרת אותם. אבל גם לשיטתכם, ששחיטת בהמה מטהרת את האבר המדולדל שבה, היה לכם לטמא את האבר שהוציא העובר, שהרי אינו גופה.","\u0003אלא ל\u0004שיטת \u0003רבי יוחנן,\u0004 שלדעת הכל אבר מדולדל אינו נטהר בשחיטה, \u0003קשיא\u0004 \u0005[קשה],\u0006 שהרי מפורש בברייתא שהיא מטהרתו!","\u0003אלא, אי אתמר הכי אתמר\u0004 \u0005[אם נאמרה\u0006 המחלוקת \u0005כך נאמרה],\u0006 \u0003אמר רבי שמעון בן לקיש: כמחלוקת ב\u0004אברים של \u0003עוברים\u0004 — \u0003כך מחלוקת באיברין\u0004 מדולדלים של הבהמה, \u0003ורבי יוחנן אמר: מחלוקת באבר\u0004 שהוציא \u0003עובר,\u0004 שלדעת חכמים נטהר האבר בשחיטת האם, ולדעת ר' מאיר אינו נטהר. \u0003אבל באבר\u0004 מדולדל של \u0003בהמה\u0004 עצמה — \u0003דברי הכל אין שחיטה עושה\u0004 את האבר \u0003ניפול,\u0004 כאילו נפל מן הבהמה בחייה, ולכן הוא נטהר על ידי השחיטה.","\u0003אמר ר' יוסי בר' חנינא, מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי יוחנן אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' מאיר,\u0004 שאבר מדולדל נטהר בשחיטה, ואבר שהוציא עובר לא נטהר? \u0003האי\u0004 \u0005[זה],\u0006 אבר מדולדל — הוא \u0003גופה\u0004 של הבהמה, \u0003והאי לאו\u0004 \u0005[וזה,\u0006 אבר שהוציא העובר, \u0005אינו]\u0006 \u0003גופה.\u0004","ועוד בענין מחלוקת ר' מאיר וחכמים, \u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: הכל מודים שמיתה עושה ניפול,\u0004 שאם מתה הבהמה — נחשב האבר כאילו נפל מגופה קודם לכן, ואינו מטמא כמוה כנבילה, אלא כאבר מן החי. \u0003ו\u0004כן הכל מודים ש\u0003אין שחיטה עושה ניפול,\u0004 שאם נשחטה הבהמה — רואים את האבר כמחובר לגופה בשעת שחיטה, והוא נטהר בשחיטתה, למרות שהוא אסור באכילה.","ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003באבר\u0004 שהוציא \u0003עובר\u0004 — הלוא \u0003מיפלג פליגי\u0004 \u0005[חלוקים הם],\u0006 שלדעת ר' מאיר שחיטה עושה ניפול, ואינו נטהר בשחיטתה, ולדעת חכמים נטהר בשחיטתה! \u0003אלא\u0004 תאמר שמדובר \u0003באבר\u0004 מדולדל של \u0003בהמה,\u0004 לשם מה הוצרך ר' יוחנן לומר דבר זה? הרי גם בענין \u0003מיתה תנינא\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 דבר זה במפורש, וגם לענין \u0003שחיטה תנינא\u0004 \u0005[שנינו]!\u0006","ומפרטים: \u0003מיתה תנינא\u0004 \u0005[שנינו]\u0006 להלן (קכז,ב) בענין בשר ואבר מדולדלים: \u0003מתה הבהמה\u0004 — \u0003הבשר\u0004 המדולדל נחשב כבשר שפרש מן החי, ולכן אינו מטמא כנבילה, אלא \u0003צריך הכשר,\u0004 שיבואו עליו מים, כדי להיטמא משרץ וכדומה שיגע בו, \u0003והאבר מטמא משום אבר מן החי, ואינו מטמא משום אבר מן הנבלה, דברי ר' מאיר.\u0004 הרי שר' מאיר רואה את האבר כאילו נפל מן הבהמה בחייה, ולכן דינו כאבר מן החי, ולא מצאנו שחכמים חלוקים עליו.","וכן ביחס ל\u0003שחיטה\u0004 שאינה עושה ניפול \u0003נמי תנינא\u0004 \u0005[גם כן שנינו]\u0006 שם: \u0003נשחטה\u0004 ה\u0003בהמה\u0004 — \u0003הוכשרו\u0004 הבשר והאבר המדולדל \u0003בדמיה,\u0004 בדם שיצא ממנה בשחיטה, לקבל טומאה, \u0003דברי ר' מאיר. ר' שמעון אומר: לא הוכשרו.\u0004 ועל כל פנים אין האבר מטמא משום אבר מן החי, שהוא אב הטומאה, ולכן הוא צריך הכשר לקבל טומאה, ומכאן ששחיטה אינה עושה ניפול, ואם כן, מה חידש ר' יוחנן בדבריו?","ומשיבים: \u0003אי מההיא\u0004 \u0005[אם מאותה\u0006 משנה\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 שחיטה גם כן עושה ניפול, ו\u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003הוכשרו?\u0004 אין כוונתו לאבר המדולדל, שהוא אכן טמא כאבר מן החי, ואינו צריך הכשר. אלא כוונתו רק ל\u0003בשר\u0004 המדולדל, שכן בשר שנפל מן החי — אינו מטמא, והוצרך לומר שדם שחיטת הבהמה הכשיר אותו לקבלת טומאה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"הוכשרו\" קתני\u0004 \u0005[שנינו],\u0006 בלשון רבים, ומשמע — הבשר והאבר המדולדלים, שבהם דנה המשנה! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 כלומר, לדרך זו הייתי מפרש לשון \"הוכשרו\" על שני מיני בשר שיש כאן: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לבשר הפורש מן הבהמה, וחד\u0004 \u0005[ואחד]\u0006 \u0003לבשר הפורש מן האבר\u0004 המדולדל, הנדון כבשר הפורש מאבר מן החי, ללמד ששניהם מוכשרים בדם השחיטה.","ושואלים: \u0003ומאי אולמיה דהאי מהאי\u0004 \u0005[ומה כוחו של זה\u0006 יותר \u0005מזה]?\u0006 מדוע הוצרך להוסיף ולשנות גם בשר הפורש מן האבר? ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ו\u0004בשר שעל אבר מן החי \u0003מטמא טומאה חמורה אגב אביו,\u0004 כחלק מאבר מן החי, שהוא אב הטומאה — \u0003אימא לא ליבעי\u0004 \u0005[אמור שלא יצטרך]\u0006 \u0003הכשר\u0004 לאחר שפרש מן האבר, לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא ב\"הוכשרו\" שגם הוא צריך הכשר. ושבים לעיקר דבריו של רב יצחק בר יוסף בשם ר' יוחנן, ששחיטה אינה עושה ניפול לאבר המדולדל בבהמה, להחשיבו כאבר מן החי, אלא הוא ניתר בשחיטתה.","\u0003אמר רב יוסף: נקוט\u0004 \u0005[החזק]\u0006 את דבריו של \u0003רב יצחק בר יוסף בידך,\u0004 שאכן כך אמר ר' יוחנן, שהרי \u0003רבה בר בר חנה קאי כוותיה\u0004 \u0005[עומד בשיטתו].\u0006 \u0003דתניא\u0004 \u0005[ששנויה ברייתא]:\u0006 \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל) — \u0003להביא האבר והבשר המדולדלין בבהמה ובחיה ובעוף, ושחטן, שהן אסורין\u0004 משום אבר מן החי. \u0003ואמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן\u0004 על דברים אלו:"]]};
